INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kudos-2', 21226, '2008-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gmct0zyxzv6is5pb812j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2jb7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kudos 2', 'Kudos 2 is the life-simulation strategy game from Positech Games (makers of Kudos, Democracy and Rock Legend). Kudos is the original inspiration for the game SimSocial by EA (also known as the myspace sims game). Kudos is a turn-based game that puts you in control of a single character and manages their life from age 20 to 30. You get to pick their friends, their job, and how they spend their free time, but there is a catch! You can only choose to do one thing each day, or two at the weekends. This makes Kudos 2 a game of agonizing choices. Do you turn down an invitation from a friend because you are too tired from work? Do you put more time into your friends or your career? When do you find time to look for a better job, or to spend time with your pet? Kudos 2 is unlike any strategy or casual game you have played before. The game has a totally original style, and uses artwork by legendary comic artist Jamie McKelvie. Every game of Kudos is unique. Did you become a high-flying corporate lawyer who cruises to the office each morning in a luxury car, but has no social life, or do you become a popular, trendy and much loved guitar-player, who works as a waitress to pay the bills? Will you have the money to splash out on a burglar alarm, or rely on your martial arts (or your faithful pet dog) to protect you from crime?' FROM games WHERE igdb_id = 21226 ON CONFLICT (game_id, language_code) DO NOTHING;
