INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demonophobia', 'Demonophobia is a Guro Survival Horror game where the emphasis is primarily on horror rather than survival. The game is about a 14-year-old Japanese schoolgirl, Sakuri Kunikai. After trying a demon summoning ritual, she wakes up in a terrifying realm of demons and tries to escape from this hell she ensnared herself into.' FROM games WHERE igdb_id = 195267 ON CONFLICT (game_id, language_code) DO NOTHING;
