INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wwii-aces', 5301, '2008-03-21', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/jfjlvaocxiamb6rrsft7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tzrkgq6aiips2ooiwkmf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWII Aces', 'Guns blazing, the Messerschmitt Bf-109 screams through the clouds toward you. Instinctively, you barrel-roll out of the way, hot lead missing your Spitfire by millimeters. You bank right, flank him and open fire.  •Unleash complex acrobatic flight tricks with a simple flick of the Wii Remote ™. Roll, loop, dodge and shoot like an ace with three distinct control schemes.  •Fly in over 70 historical WWII missions, including strategic bombing, paratrooper drops, frantic dogfights, and more.  •Get behind the guns of 12 legendary planes like the Spitfire, Ju-87 Stuka, Mosquito and He-111. Fly for the RAF, Soviet Air Force, or even the Luftwaffe.  •Tackle missions alone or fly with a friend. Or, go head-to-head in competitive split-screen multiplayer.' FROM games WHERE igdb_id = 5301 ON CONFLICT (game_id, language_code) DO NOTHING;
