INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Rangers: To the Rescue', 'Power Rangers: To The Rescue (Known simply as Power Rangers from the title screen) is a Plug It In & Play TV Game controller developed by HotGen and published by Jakks Pacific, released in 2008 and again in 2009. The controller is shaped in the red ranger''s helmet, which opens into a game controller.' FROM games WHERE igdb_id = 220101 ON CONFLICT (game_id, language_code) DO NOTHING;
