INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('checkers-premium', 87269, '2008-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ke3lj98axue61rbaqtnm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pcdj367yjc5zjya6vihu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Checkers Premium', 'The #1 Checkers app for iOS just got better. Play against your Game Center friends or random opponents using our new turn-based multiplayer feature!  Checkers Premium supports both 1 player and 2 player gameplay, so you can play against friends or test your skills against a challenging computer opponent.  Our new turn-based network play feature allows you to play up to 16 simultaneous network games against your Game Center friends or random network opponents over Wi-Fi or 3G.  Checkers Premium includes a host of exciting features, including: * Great graphics and awesome sound effects * Configurable player names and score tracking  * Outstanding AI engine provided by renowned AI researcher Martin Fierz  * Fully configurable 1 player difficulty level  * Undo function  * Option to enable / disable forced captures * Automatic save when you exit the app Checkers Premium currently plays according to American Checkers / English Draughts rules.' FROM games WHERE igdb_id = 87269 ON CONFLICT (game_id, language_code) DO NOTHING;
