INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto Shippuden: Naruto vs. Sasuke', 'Experience first-hand one of the most popular storylines from the NARUTO SHIPPUDEN arc as Naruto and Sasuke face off amidst a backdrop laced with intrigue and subterfuge! Discover, recruit, and swap fighters into your team to meet the needs of any given situation. Compete against your friends in Wireless Battle Mode for up to four players, or play cooperatively in the new Boss Rush Mode (local wireless only). Take part in thrilling battles and exciting mysteries, all leading up to the epic showdown between Naruto and Sasuke!' FROM games WHERE igdb_id = 24270 ON CONFLICT (game_id, language_code) DO NOTHING;
