INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank Universal', 'Tank Universal creates a huge virtual ''Tron-like'' world where you take part in immense 3D tank battles involving scores of units both friendly and not so friendly in wide open levels! Players can bombard the enemy from a distance or close the gap and dodge shells point blank - all in an immersive first person perspective.' FROM games WHERE igdb_id = 9455 ON CONFLICT (game_id, language_code) DO NOTHING;
