INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pitfall: The Big Adventure', 'Set in the Peruvian jungle, Pitfall: The Big Adventure combines the action of reptile dodging and vine swinging with clever puzzles. The game will feature over 60 levels spanning lush rainforests, creature-filled caves, and glacial mountains. Within these dynamic worlds, players will explore cavernous jungles, discover lost treasures, battle shamen, narrowly escape treacherous traps and outwit creatures using innovative, accessible game mechanics developed specifically to take advantage of the Wii motion sensing controls.' FROM games WHERE igdb_id = 84820 ON CONFLICT (game_id, language_code) DO NOTHING;
