INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruina: Haito no Monogatari', 'Ruina: Fairy Tale of the Forgotten Ruins is a free-to-play Japanese RPG made with the RPG Maker 2000 engine, originally released on December 24th, 2008 and made but just one person known as Shoukichi Karekusa (枯草章吉). The game won the Grand Prize in Freem!’s 4th Annual Game Contest and its generally considered as a cult classic. The game was fan translated into English in early 2021 by a user named Dink. The translation received the blessing of the original creator with the conditions that his name remain in or be added to any relevant documentation, signifying that he is the game’s creator and that the game always be available free of charge.' FROM games WHERE igdb_id = 152475 ON CONFLICT (game_id, language_code) DO NOTHING;
