INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Territory War Online', 'Defend your turf! They think they can take over your land? They have another thing coming... A throwback to classic games such as Worms and Scorched Earth, this turn-based battle game is off the chain; unleash ballistic destruction upon the invaders and shed no tears as they burst into dust. Test your skills online in this multiplayer edition -- Can you be the top dog? Jump online with your XGen account, or hit quickstart for instant action.' FROM games WHERE igdb_id = 254299 ON CONFLICT (game_id, language_code) DO NOTHING;
