INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Air Bloon', 'Hot Air Bloon is an online flash game released by Ninja Kiwi in November 2008 that is currently available on the Flash Archive. It is a horizontal scroller where the player is tasked with navigating a monkey hanging from a damaged blimp through an ever-accelerating series of obstacles while popping as many bloons as possible.' FROM games WHERE igdb_id = 286632 ON CONFLICT (game_id, language_code) DO NOTHING;
