INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman Blast', 'Look out for Bomberman Blast! There''s 8-person online multiplayer and you can even use your Mii as a Bomberman! A brand new addition to the Bomberman series is available on WiiWare! Up to eight players can battle online simultaneously via Nintendo Wi-Fi Connection! Simple controls make this a great game for family and friends to enjoy at anytime! New items can be triggered by shaking the Wii Remote controller for excitement never before experienced in a Bomberman title! You can even take the intensity up another notch by adding your own Mii caricatures to the mix! Battle results can be recorded on Nintendo Wi-Fi Connection Ranking, so see how you stack up against others around the globe! This title will prove to be a blast for everyone--from those who''ve never touched a Bomberman game, to the Bomberman masters!' FROM games WHERE igdb_id = 50701 ON CONFLICT (game_id, language_code) DO NOTHING;
