INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('assassins-creed-altairs-chronicles', 21349, '2008-02-05', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8yvv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7zft.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed: Altair''s Chronicles', 'As the direct prequel of the critically acclaimed console title Assassin’s Creed, discover more of the story of Altaïr as he must find “the chalice,” an object of such power that whoever is in possession of it can end the Crusades. Altair will explore a fully realized 3D world traveling through four cities of the Crusade’s Middle East. The game will feature acrobatic moves and exhilarating combo attacks that mix both sword skills and kicks. The setting is 1190 AD. The Third Crusade is tearing the Holy Land apart. You, Altaïr, intend to stop the hostilities by suppressing both sides of the conflict. • Be an Assassin Master the skills, tactics, and weapons of history’s deadliest and most secretive clan of warriors. • Action-platforming Gameplay Fast-paced action features swordfights, combo attacks and acrobatic moves that journey through historical 3D environments • Choose Your Weapon Learn and master 11 weapons for both close combat and long-range attacks, featuring five swords, varying types of daggers, explosives and a grappling hook • Immersive Storyline A deep and compelling storyline that will appeal to those who have both played the console title or are new to the franchise • Touch-Screen Mini-games Players will be able to use the Stylus to perform pickpocket maneuvers to carefully steal precious items from the crowd and make informants speak • Upgrade and Rank Up Collecting orbs will upgrade Altair’s health and weapons The game is no longer available for iOS and Android.' FROM games WHERE igdb_id = 21349 ON CONFLICT (game_id, language_code) DO NOTHING;
