INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherlock Holmes: The Awakened - Remastered Edition', 'The Sherlock Holmes series returns with this updated version of The Awakened, which brings a whole new dimension to the original title developed by Frogwares. Keeping with the traditional Point & Click gameplay style of the original adventure games, The Awakened has been totally rethought, offering players a new third-person view while keeping the original first-person view available also.' FROM games WHERE igdb_id = 27849 ON CONFLICT (game_id, language_code) DO NOTHING;
