INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherlock Holmes: The Mystery of the Persian Carpet', 'Hunker down at your London flat at 221b Baker St. The year is 1896, and Scotland Yard has called Sherlock Holmes with an urgent request for help. A young painter has been found murdered and rolled up in a remarkable Persian carpet. Along with Watson, you must investigate the peculiar crime, exploring crime scene locations in search of missing clues. Interact with suspects, and analyze police reports and witness statements to solve the crime and unravel the mystery of the Persian carpet.' FROM games WHERE igdb_id = 14854 ON CONFLICT (game_id, language_code) DO NOTHING;
