INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Infinite World', 'Dragon Ball Z: Infinite World combines all the best elements of previous Dragon Ball Z games, while boasting new features such as “Dragon Missions”, new battle types and drama scenes for fans to delve deeper than ever before into the Dragon Ball Z universe. The new “Dragon Missions” Dragon Ball Z Infinite World include many famous scenes from the Dragon Ball Z series never before seen in a video game.' FROM games WHERE igdb_id = 2570 ON CONFLICT (game_id, language_code) DO NOTHING;
