INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stress Attack', 'Stress Attack is a mobile action game set in a theme park created for stress relief. The player controls a character navigating various environments, including offices, supermarkets, suburbs, and cemeteries. The park is populated by robot figures resembling bosses and coworkers. The objective is to destroy objects and characters within each area.' FROM games WHERE igdb_id = 337771 ON CONFLICT (game_id, language_code) DO NOTHING;
