INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Baby!', 'Hello Baby! gives you the opportunity to be a babysitter who must look after a seven-month-old bouncing baby until it''s one year-old. From morning until evening, you must care for the charming youngster by feeding it, playing entertaining games and even changing nappies. Caring for your new baby friend couldn''t be easier thanks to a range of different mini-games themed around typical babysitting activities. So, whether you''re making sheep jump over a fence to send the tot to sleep or ensuring the milk bottle is the perfect temperature, you''re guaranteed hours of brilliant baby fun. What''s more, by successfully completing the various child challenges you can unlock a range of new outfits for your baby, including clothes, hats and accessories. In fact, there are 10,000 potential combinations of items to wear.' FROM games WHERE igdb_id = 47898 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 47898 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
