INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-weight-loss-coach', 47900, '2008-06-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rxftile8skmjhoetura8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv0xw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Weight Loss Coach', 'My Weight Loss Coach DS is a game for every adult, male and female who considers reaching and maintaining their target weight as a challenge. A program that fits your own objectives and respects your daily life constraints, My Weight Loss Coach supports you and tracks your progress and achievements by improving your energy balance. Developed in conjunction with a nutritionist, it helps you take control of your weight efficiently and feel better. Via an exclusive pedometer (included free with the game), you will be able to measure your real physical activity level and balance it following the advice of a fitness coach. Your motivation will increase with coaching sessions, daily challenges, mini-games and quizzes, play for only 10 to 15 minutes per day and you will feel the difference.' FROM games WHERE igdb_id = 47900 ON CONFLICT (game_id, language_code) DO NOTHING;
