INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Karaoke Revolution Presents: American Idol Encore', 'Step into the spotlight and become an idol. Karaoke Revolution Presents: American Idol Encore delivers the most realistic recreation of the American Idol experience with an all-new next generation game engine and 40 smash hits from the 70''s, 80''s, 90''s and today. Grab the mics and challenge your friends to find out who will be the next superstar and face the music as Simon Cowell, Paula Abdul and Randy Jackson critique your performances.' FROM games WHERE igdb_id = 21350 ON CONFLICT (game_id, language_code) DO NOTHING;
