INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gyakuten Touhou', 'Gyakuten Touhou is a visual novel & adventure style game based on the Gyakuten Saiban/Ace Attorney series. The player assumes the role of Aya Shameimaru as a defense attorney as she proves her clients not guilty using investigation, evidence, and cross-examination.' FROM games WHERE igdb_id = 300038 ON CONFLICT (game_id, language_code) DO NOTHING;
