INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('die-letzte-schlacht-der-elfen', 88953, '2008-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cdnaxtcacsaixsjlqenp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mbh5cqeumk34rjxwcgi8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die letzte Schlacht der Elfen', 'Der junge Elf Farodin Enrias bekommt vom König seiner Heimat Sirolan den Auftrag, "nord ostlich entfernt" in ein Loch reinzugehen, um dort zu einen Fürsten der Unterwelt vorzugehen und den schon mal zu schwächen.  Dabei trifft er verschiedene Gefährten, die er alle in seine Gruppe aufnimmt.  Darunter den gelangweilten Edwin Oddessirion, die ebenfalls gelangweilte Aliya und die viel zu viel plappernde Halbelfin Selphia.  Zusammen stellen sie sich diesem und weiteren Fürsten der Unterwelt, die alle dem trickreichen hormongesteuerten Dunkelelf dienen, den es ebenfalls zu bekämpfen gilt.  Ein EPISCHES Abenteuer mit TIEFGRÜNDIGER und GUT DURCHDACHTER Story erwartet dich!' FROM games WHERE igdb_id = 88953 ON CONFLICT (game_id, language_code) DO NOTHING;
