INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'White Knight Chronicles', 'White Knight Chronicles is a Japanese RPG (role-playing game) which allows players to explore an expansive and exciting world of turn-based combat, adventure and comradery A PlayStation 3 exclusive, it was created by noted Japanese RPG game developer Level-5 and features both single player and online multiplayer action, the awesome power to assume the shape of the White Knight, the ability to build a persistent online town/lobby, communication via online blogs, message boards and quest logs, voice chat and beautiful game environments.' FROM games WHERE igdb_id = 7482 ON CONFLICT (game_id, language_code) DO NOTHING;
