INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Etch a Sketch', 'The timeless drawing toy Etch A Sketch comes out of the classic red box and comes alive on your computer screen! Grizelda the witch has shaken things up in the Land of Aha and Knobby needs your help. Experience the World’s Favorite Drawing Toy as you use your mouse to sketch unique masterpieces and help Knobby on his quest in adventure mode.' FROM games WHERE igdb_id = 51398 ON CONFLICT (game_id, language_code) DO NOTHING;
