INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-smash-bros-brawl--1', 328674, '2008-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa3v2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3p8e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Smash Bros. Brawl', 'Super Smash Bros. Brawl is an Adobe Flash game published by Extra Toxic as part of its Nintendo advent calendar microsite. The game was made to promote the game of the same name. Once the player starts the game, the player will have to alternate between clicking on one of their swords to send a beam into the opposing character (when that character is not using a shield on that spot), and holding up their own shield to deflect the other character''s sword. While the character that the player is facing will change after either character hits the other, the player is always playing as Mario. The game ends when either the player or the computer-controlled character hits their opponent five times. If the player wins, the game will save the amount of time it took for them to finish the game as the player''s record.' FROM games WHERE igdb_id = 328674 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 328674 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
