INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmopax', 'Cosmopax is a kind of virtual world where you can, among other things, stroll, make friends, chat, become famous, party, compete in games and take care of your Web-room. You just need to register - with full name, email and password - and then choose a fun Pixtar, which will be your face.' FROM games WHERE igdb_id = 138286 ON CONFLICT (game_id, language_code) DO NOTHING;
