INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet''N''Fuck: Street Racing', 'World of underground street racing filled with dangerous adventures. Expensive sport cars, gorgeous women and stunning tricks. All of that make your heartbeat faster. Beyond that, You don''t even know what will happen this evening. Will you get laid with another amazing blonde or crash your favorite ride? Anyway, you should try this incredible mix of sex and illegal street racing.' FROM games WHERE igdb_id = 221627 ON CONFLICT (game_id, language_code) DO NOTHING;
