INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sudoku-plus--3', 88712, '2008-07-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/j7uop23mtseu4htix6jo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bnshrcxbtczbzzoquwou.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', ':) Sudoku +', 'With unlimited play at seventeen difficulty levels, novices and experienced players alike will appreciate :) Sudoku +. Our tutorial, extensive feature set, and advanced hint system offer something for every player. The more you play, the more you will enjoy it! Our multi-stage hint system starts with a gentle reminder to get you back on track, and works up to an illustration of the exact technique to use and how it applies to the current board. Our hints ease those frustrating moments and teach you how to be a better player. Features include: - Puzzle generator for unlimited play - Scan puzzles from books/newspaper using camera - 17 difficulty levels, something for everyone - Tutorial teaches you new techniques - Large, high contrast digits are easier to read - Enter games from the newspaper - Solver helps you with games from the newspaper - Advanced techniques at the higher levels, including X-Wings, sashimi fish, and XY-Chains - User interface optimized for fewer touches - Choice of six color schemes - Never covers up the board while you are playing - Infinite undo/redo - Undo to the last solvable position - Board solvable indicator - Automatic or manual pencil marks - Save your game while you try alternatives - Automatically saves your game when you get a phone call, switch applications, or lock the phone - Highlighting helps you discover patterns - Game clock; compares your time to other players - Avoids graphic frills that distract from play - Choice of digit styles, including Kanji and Hanzi All games are true Sudoku, with symmetry and a single solution that can be discovered by logic alone. If you doubt that a puzzle can be solved by logic, simply have the hint system explain it to you step by step. If you enjoy Sudoku, this is the app for you!' FROM games WHERE igdb_id = 88712 ON CONFLICT (game_id, language_code) DO NOTHING;
