INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Mama: Mama Kills Animals', 'A browser game created by People for the Ethical Treatment of Animals (PETA), an animal rights organization based in the United States. It''s a parody of Cooking Mama created to advocate vegetarian and vegan diets. In it, PETA encouraged users to write to Cooking Mama developer Majesco Entertainment to create a version of the game with only vegetarian recipes. Mama Kills Animals consists of minigames related to the preparation of animal carcasses.' FROM games WHERE igdb_id = 18449 ON CONFLICT (game_id, language_code) DO NOTHING;
