INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Migux', 'Migux was a Brazilian online multiplayer-style social media and mass community game aimed at children and teenagers, developed by Brancaleone in 2007, and released on July 7, 2008. The video game ended in 2012 the loss of registered users and financial problems. The game was set in an underwater environment and had an educational proposal, in addition to helping children acquire environmental awareness.' FROM games WHERE igdb_id = 138040 ON CONFLICT (game_id, language_code) DO NOTHING;
