INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mud and Blood 2', 'Mud and Blood 2 is a real-time tactical level strategy game. The player takes command of a squad of American soldiers during World War II (operation Lüttich, August 1944), who will face endless waves of German troops.' FROM games WHERE igdb_id = 56020 ON CONFLICT (game_id, language_code) DO NOTHING;
