INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Matchstick', 'The aim of the Matchstick Puzzle by DS is to answer the questions by moving or rotating matchsticks. There are more than 150 puzzles of four difficulty settings to complete. The game also has hints to help the player decipher the more abstract clues.' FROM games WHERE igdb_id = 91700 ON CONFLICT (game_id, language_code) DO NOTHING;
