INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4Story Online', '4Story Online is a free-to-play, full 3D MMORPG proudly designed to invite players to take on the large scale warfare (RvR) and enormous quests. Exploring the ancient world of Iberia, players are provided with diverse game contents starting from PvP, RvR, Instant dungeons, Siege war, Boss monster raids, Diverse unique items, Smooth interface, Fabulous Rides, Character customizing, Item enchantment, and much more.' FROM games WHERE igdb_id = 27734 ON CONFLICT (game_id, language_code) DO NOTHING;
