INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('professor-layton-and-the-unwound-future', 1399, '2008-11-27', 93, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobav0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gbwqfjxvdzrvukaxx9pw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professor Layton and the Unwound Future', 'As with previous Professor Layton games, Unwound Future is an adventure game where the player solves puzzles offered by local citizens to progress the story forward, through dialogue and around 32 minutes of full motion video. The player moves about the game through still images of locations. The player can use the DS touchscreen to tap on non-player characters to start a dialog or to obtain a puzzle, and also can search anywhere on the background for hint coins, with some areas needing to be tapped several times to reveal a secret hint coin or puzzle. Puzzles are brainteasers of many varieties, including visual, math, and logic. There is no time limit to solve puzzles, and the player can get up to 3 hints at a cost of one hint coin each; a new feature in Unwound Future is a "super hint", costing 2 coins, that can only be bought after the other 3 hints have been revealed, but that nearly reveals the puzzle''s solution. If the player is correct in solving the puzzle, they gain a number of "Picarats", a form of currency within the game. Guessing the incorrect answer will reduce the number of picarats the player can get on subsequent attempts. Players can visit certain areas in order to play undiscovered or unsolved puzzles that are left behind as the story progresses.' FROM games WHERE igdb_id = 1399 ON CONFLICT (game_id, language_code) DO NOTHING;
