INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1112: Episode 01', '1112 invites players into the life of Louis Everett, an average man residing in the peaceful town of Jalonsville, New Jersey, with his curious wife. Despite his ordinary existence, Louis is troubled by constant headaches and mysterious dreams, leading players on a suspenseful journey to uncover hidden truths. In this game, you''ll navigate through 15 detailed environments, interact with 8 distinct characters, and solve intriguing puzzles. The game''s advanced graphics and original score create an immersive world, turning Louis''s seemingly mundane life into a captivating, interactive mystery.' FROM games WHERE igdb_id = 213381 ON CONFLICT (game_id, language_code) DO NOTHING;
