INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('art-style-rotohex', 21177, '2008-10-27', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tjt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ijudxjefdr7m0ybk1u99.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art Style: Rotohex', 'Rotate and group colored triangles to create matching hexagons, but don’t let the playing field become full! Use colored triangle panels to create a vibrant mosaic of stained glass in Art Style: ROTOHEX. As triangles fall from the top of the screen, rotate them to group six panels of the same color and create a matching hexagon (HEX). Once the HEX has been formed, it will disappear, allowing the existing panels to shift and more to fill the playing field. Two different styles of intuitive controls and the clear-cut goal allow you to focus solely on the game play—which is vital, as the playing field will be full of panels before you know it. With multiple modes available (unlock more as you progress farther in SOLO mode), special item panels at your disposal, and the ability to play cooperatively or competitively with a friend, there will always be another HEX to create!' FROM games WHERE igdb_id = 21177 ON CONFLICT (game_id, language_code) DO NOTHING;
