INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turning Point: Fall of Liberty', 'Turning Point: Fall of Liberty is a first-person shooter video game. The game takes place in an alternate history in which Winston Churchill dies in 1931, eight years before the start of World War II, presenting the possibility of what could have happened to Europe, the United States, and the rest of the world without his leadership.' FROM games WHERE igdb_id = 7221 ON CONFLICT (game_id, language_code) DO NOTHING;
