INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty: World at War - Limited Collector''s Edition', 'The Call of Duty: World at War Limited Collector''s Edition is a package containing Call of Duty: World at War, a canteen, which has its lid stuck on as the inside is lead, a metal tin in which to store all Call of Duty games, a week of double XP, a golden clan tag to promote the player''s VIP status, and a code for unlocking the FG42 early. When the code is redeemed, the first heavy gunner slot for Create-A-Class will have an FG42. If the customer pre-ordered the game at Gamestop then the M1A1 Carbine will be put in the first slot of the rifleman class.' FROM games WHERE igdb_id = 292807 ON CONFLICT (game_id, language_code) DO NOTHING;
