INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zodiarc Ring', 'Two additional stories focused on Zodiarc''s protagonists Chapter 1. "Arcana Gakuen" is a prequel drawing school life before the main events. Chapter 2. "Mephistopheles" is about main character getting involved in an incident of Mephistopheles waking up every night.' FROM games WHERE igdb_id = 331146 ON CONFLICT (game_id, language_code) DO NOTHING;
