INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totally Spies! Totally Party', 'The game is primarily based upon a series of mini-games distributed around 10 boards and a showroom. On each board, 1 to 3 players will be able to face-off with a "bad guy". The players must win the mini-games in order to gain popularity points and lay traps against the bad guy. Watch out, the bad guys can also lay traps!' FROM games WHERE igdb_id = 5238 ON CONFLICT (game_id, language_code) DO NOTHING;
