INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dwk-5-hinter-dem-horizont', 81577, '2008-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co916a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuev8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DWK 5: Hinter dem Horizont', 'DWK 5: Hinter dem Horizont is a traditional point & click adventure game based on the movie Die wilden Kerle 5: Hinter dem Horizont. The young soccer players Leon, Vanessa, Maxi and Raban are practising in the woods - but suddenly Leon disappears. Of course his friends search for him and suddenly arrive in the land of vampires... The player alternately takes the control of the four protagonists and solves item based puzzles. To do so he explores his surroundings, takes everything he finds, talks with people and combines items with each other. In each scene the player can instantly switch between day and night which alters the persons he meet and the items he can interact with. When stuck the player has access to a hint system.' FROM games WHERE igdb_id = 81577 ON CONFLICT (game_id, language_code) DO NOTHING;
