INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fushigi Yuugi Suzaku Ibun', 'Fushigi Yuugi Suzaku Ibun is a simulation game for the anime and manga series Fushigi Yuugi. It''s story is based on the original Fushigi Yugi. The game, though having most of the characters as returning characters from the original series, it has apparently replaced Miaka and Yui. It was released on 2008, in two editions: limited and full edition. The game was also ported to NDS on June 25, 2009 and placed on the same cartridge as Fushigi Yuugi Genbu Kaiden: Kagami no Miko.' FROM games WHERE igdb_id = 62178 ON CONFLICT (game_id, language_code) DO NOTHING;
