INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anguna: Warriors of Virtue', 'Anguna: Warriors of Virtue is a Legend of Zelda style RPG that simply offers an enjoyable, dungeon crawling experience. It was released in 2008. It is a homebrew game for Gameboy Advance and Nintendo DS, featuring art by Chris Hildenbrand Anguna includes: 5 dungeons and a large overworld to explore Multiple weapons and items including: a sword, bow & arrows, bear traps, dynamite, lantern, magic boots, and more Many hidden rooms, secrets, and powerups Lots of interesting enemies and boss monsters NEW Bonus Ice Dungeon with Warp Ring powerup' FROM games WHERE igdb_id = 49509 ON CONFLICT (game_id, language_code) DO NOTHING;
