INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army of Two', 'Army Of Two throws gamers into hot spots ripped from current day headlines where they will utilize unique two-man strategies and tactics while seamlessly transitioning between playing with intelligent Partner AI (PAI) and a live player. When one man is not enough, it will take an army of two to fight through war, political turmoil and a conspiracy so vast it threatens the entire world' FROM games WHERE igdb_id = 996 ON CONFLICT (game_id, language_code) DO NOTHING;
