INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Hind', 'SUPER HIND is the ultimate tactical air combat game for a handheld. Explore breathtaking high-detail environments: rich geology, foliage, buildings, and atmospheric effects like rain, snow, and sunshine- even lightning. Take on a world of lethal fighting machines: helicopters, tanks, mobile missile platforms, jet aircraft, ballistic missile warships, submarines and more.' FROM games WHERE igdb_id = 44475 ON CONFLICT (game_id, language_code) DO NOTHING;
