INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sims Castaway Stories', 'Help your Sims thrive and survive when they wash ashore on an uncharted island. Create your Sims and guide them through an even deeper, directed Story mode, taking on a variety of challenges as you help them build their new life from scratch. Meet the natives, discover the hidden mysteries of the island, befriend new animals, and unlock rewards as your Sim achieves set goals. In open-ended Free Play mode, design your Sims and their shelters, explore the island, tell your own unique story. However you play, count on many unexpected twists and turns as you decide how their stories unfold.' FROM games WHERE igdb_id = 13140 ON CONFLICT (game_id, language_code) DO NOTHING;
