INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penguins Arena: Sedna''s World', 'It all begins when a penguin legend comes to life in the form of Sedna, the ancient Penguin Goddess. Global warming, melting ice caps, pollution... penguin tribes are endangered. Sedna tells them that there is room for but one tribe. And so the purging begins. Now it''s your turn to join the snowball battle and drive the other tribes into the sea.' FROM games WHERE igdb_id = 15779 ON CONFLICT (game_id, language_code) DO NOTHING;
