INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moorhuhn Fun Kart 2008', 'Moorhuhn: Fun Kart 2008 is a kart racing game starring Moorhuhn (Crazy Chicken) and friends. The eight racing tracks range from a barnyard to beaches to a desert with pyramids in the back ground. Power-ups can be picked up and used on opponents while racing. The player can choose between seven different characters, including two chickens, a frog, turtle, snowman, scarecrow and mole. The game offers three modes: a Championship (two championship each with four tracks), time challenge and two player mode. Kart classes included are 50cc, 100cc and 150 cc.' FROM games WHERE igdb_id = 43376 ON CONFLICT (game_id, language_code) DO NOTHING;
