INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Robot Taisen A Portable', 'An organization called the Shadow-Mirror, which exists in a parallel world where events happened in a different way than the original game world, thus making the state of the worlds different, though a bit similar at times. Its leader, Vindel Mauser, desires a world of eternal war to make humanity improve more through war. His plan is to send his agents towards another dimension, spy on the defense forces of the world in order to make adjustments on the attack, and eventually conquer it.' FROM games WHERE igdb_id = 79841 ON CONFLICT (game_id, language_code) DO NOTHING;
