INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Masyanya Under The Yellow Press', 'The game is a typical quest from Alawar. It was released on October 22, 2008. The game features an interface that includes a bar with collectible items, an inventory, a task list, a score multiplier gauge, a Masyanya icon, and a hint button. If you click incorrectly for too long, the multiplier will reset, and Masyanya will get sad. Collectible items can sometimes automatically combine. The game also includes close-up views and mini-games displayed in separate windows.' FROM games WHERE igdb_id = 335429 ON CONFLICT (game_id, language_code) DO NOTHING;
