INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cate West: The Vanishing Files', 'A series of unsolvable crimes, nicknamed The Vanishing Files, have bewildered the police and paralyzed the city of Arcadia. Cate West, a mystery novelist haunted by strange dreams, has psychic visions that might just hold the key to solving the crimes. Step into the role of Cate and find clues, compile evidence, bring criminals to justice and discover the link between The Vanishing Files and the mystery in her past.' FROM games WHERE igdb_id = 4752 ON CONFLICT (game_id, language_code) DO NOTHING;
