INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-legendary-starfy', 20280, '2008-07-10', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co92i7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vqiowejzhmowy50xzy0o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legendary Starfy', 'He may be the prince of a kingdom in the clouds, but Starfy''s not afraid to get his pointy hands dirty pummeling bad guys. Watch out, villains - Starfy and his gruff-talking sidekick clam, Moe, are setting out on another astonishing adventure: to help a mysterious, bunny-eared visitor find his lost memory. There''s nothing he can''t handle! Jetting through powerful ocean currents, gliding over bottomless pits, swimming straight up glittering rainbows, plowing into packs of shadowy evildoers, it''s all in a day''s work for the legendary Starfy. And when danger strikes, Starfy can team up with his friend to shape shift into four unstoppable forms. Is a tangle of overgrown bushes blocking the way? Starfy can transform into Monster and torch it with his scorching Fire Belly ability! Is a small army of baddies guarding a treasure? He can shape shift into Rooster and let out a Super Gawk! Mix it up with some mini-games! Hook up with your friends over local wireless (existing connection is required) and face off in fabulous mini-games, Race to the ocean floor in Depth Chargers, hook the big one in Fishing Derby, rush to trace shapes in Sand Tracer, and shoot some change in Coin Slinger, or challenge yourself to see how many tasty octopus snacks you can cook up in Dumpling Master! You can also team up with a friend over Local Wireless and play levels from the main adventure together as Starfy and his sister, Starly.' FROM games WHERE igdb_id = 20280 ON CONFLICT (game_id, language_code) DO NOTHING;
