INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'University Tycoon', 'University is awaiting you! Start out your student career in the time-honoured England, meet friends and visit foreign countries as an exchange student in order to achieve your task to pass the famous master degree with "suma cum laude". Choose between five characters, e.g. the nerd Jason, the pretty Lindsey or the ace Bobby and try to survive the hard student life.' FROM games WHERE igdb_id = 230630 ON CONFLICT (game_id, language_code) DO NOTHING;
