INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fable-ii-limited-collectors-edition', 47415, '2008-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ggf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scx9b4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fable II: Limited Collector''s Edition', 'Limited Collector''s Edition includes: Bonus DVD - Includes new ''Making-of Feature'' with Peter Molyneux and the team at Lionhead Studios and art gallery. Bonus In-Game Content (Requires LIVE account) - Includes "The Hall of the Dead" Dungeon, "The Wreckager" Legendary Cutlass Weapon and Spartan armor and energy sword. 48-hour Xbox LIVE Gold Trial Card - With Xbox LIVE Gold, players can show off their individual hero by inviting friends into their unique version of Albion or they can visit their friends'' Albion, and earn additional gold, experience and renown to take back into their own. Fable II is the true sequel to the wildly successful original that sold more than 3 million copies, offering even more choices and building on the core gameplay theme of "Fable," where a player’s every decision continually defines whom they become. "Fable II" is an action role-playing game (RPG) that truly allows players to live the life they choose in an unimaginably open world environment. Set 500 years after the original, "Fable II" will provide gamers with an epic story and innovative real-time gameplay, including a massive amount of freedom and choice to explore a vast collection of dungeons, catacombs and caves in the world of Albion.' FROM games WHERE igdb_id = 47415 ON CONFLICT (game_id, language_code) DO NOTHING;
