INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Star Cheer Squad', 'The game follows a year in the life of a cheerleader as they learn new cheers, participate in practices and create their own routines to make the squad and eventually become captain. On the Wii, the Wii Remote and Nunchuk, along with the Balance Board can be used to perform cheer and dance moves. Cheerleading choreographer Tony G of Bring It On fame acted as chief consultant to the game.[' FROM games WHERE igdb_id = 2849 ON CONFLICT (game_id, language_code) DO NOTHING;
