INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Ocean: Second Evolution', 'Enhanced remastered of Star Ocean: The Second Story exclusively for PSP New high-quality animated cut scenes and character designs by Production I.G. Characters will now change facial expressions depending on their mood Revised game engine and improved real-time battle system keep players immersed in the action More private actions and extensive new fully-voiced dialogue bring the story to life' FROM games WHERE igdb_id = 80504 ON CONFLICT (game_id, language_code) DO NOTHING;
