INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: The Hidden Staircase', 'NANCY''S ON THE CASE! Family heirlooms are disappearing all over Twin Elms. The residents are counting on Nancy Drew to solve the mystery before it''s too late! Interview people and gather clues using the stylus to uncover the location of the hidden staircase. Explore the large and mysterious Twin Elms house and examine anything that is out of place. Earn the top rank of Master Detective and find the stolen items.' FROM games WHERE igdb_id = 47916 ON CONFLICT (game_id, language_code) DO NOTHING;
