INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('real-stories-veterinaire', 268390, '2008-11-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co74v3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Stories: Veterinaire', 'This Wii-game in 3D offers a perfect and realistic simulation of the No. 1 job of most children: Veterinarian! The player can handle over 30 different cases of animal patients that correspond to reality in a veterinary practice and have been developed by specialists in the field. A variety of different animal species needs medical attention, and the player must use all the techniques of a good veterinarian such as talking to the owners, analysis and diagnosis, treatment, surgery, control to heal the little darlings. Realistic diagnosis and treatment instruments are used, and as the experience grows, the player can even earn diplomas and distinctions in addition to the great satisfaction of his patients. The game offers three different levels of difficulty, plus a knowledge quiz with 150 questions. The game is using the Wii''s own controller Wiimote and Nunchuck And allows a realistic immersion in the veterinarian world: the player can actively handle or operate animals, even in multiplayer, where two players can perform a complex treatment together.' FROM games WHERE igdb_id = 268390 ON CONFLICT (game_id, language_code) DO NOTHING;
