INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('korg-ds-10', 73009, '2008-07-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ca3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Korg DS-10', 'KORG DS-10 is a music creation program for the Nintendo DS that emulates the Korg MS range of synthesizers. The DS-10 creates sound with two analogue synthesizer emulators, each with two Voltage-Controlled Oscillators (the Korg MS-10 had only one VCO). The VCOs feature a sawtooth, a pulse (with a non-modifiable pulse width), a triangle and a noise waveform. There is also a four-part drum machine that uses the same sound creation techniques as the synthesizers. The sounds made by each of the synthesizer emulators are modified using virtual knobs to change the value of standard synthesizer parameters such as cutoff frequency and waveform shape. Additionally there is a screen where users can patch certain parameters to be modified by an LFO, the envelope generator, or VCO2.' FROM games WHERE igdb_id = 73009 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 73009 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
