INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-witcher-enhanced-edition', 20275, '2008-09-16', 86, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7mue.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3se7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Witcher: Enhanced Edition', 'Based on the novels by a popular Polish writer Andrzej Sapkowski, The Witcher is an action-oriented, epic fantasy RPG that takes players on a journey through a world which in many ways mirrors our own. Take on the role of Geralt of Rivia, a professional monster hunter, as he embarks on a quest of self-discovery and revenge. The game''s time-delayed decision-consequence system ensures that the consequences of your choices will become apparent only in the following chapters of Geralt''s story, discouraging returns to a previous save point. The Enhanced Edition includes technical and gameplay improvements that bring shorter loading times, more natural animations, and improved inventory, among others. Two new adventures titled The Price of Neutrality and Side Effects will extend players'' enjoyment of the game. Finally, the "D''jinni Adventure Editor" enables players to create their adventures and shared them with others.' FROM games WHERE igdb_id = 20275 ON CONFLICT (game_id, language_code) DO NOTHING;
