INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wii Music', 'Create a musical masterpiece with up to four players. Anyone can play the huge selection of instruments in Wii Music with simple motions. Play faster. Play slower. Skip a beat, or throw in 10 more. No matter what you do, Wii Music automatically transforms your improv stylings into great music. There are no mistakes - just playing for the pure joy of playing.' FROM games WHERE igdb_id = 3244 ON CONFLICT (game_id, language_code) DO NOTHING;
