INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dance-dance-revolution-x', 73042, '2008-09-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vuz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8diq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution X', 'Dance Dance Revolution X is a music video game, part of the Dance Dance Revolution series. DDR X was announced by Konami in 2008 for Japan and on May 15, 2008 for the North American PlayStation 2. The arcade version was announced on July 7, 2008, July 9, 2008 in Europe, and July 10, 2008 for North America. Released to celebrate the 10th anniversary of Dance Dance Revolution, DDR X sports an improved interface, new music, and new modes of play. The arcade release featured an overhauled (second generation) cabinet design with a widescreen display, e-Amusement and USB access, and an improved sound system. Despite such new design of its arcade cabinet, upgrade kit to change the edition of DDR on its first generation arcade cabinet from SuperNOVA2 (or earlier) to X is also available. The PlayStation 2 release has link ability with the arcade machine, multi-player support over LAN, and other improved and returning features such as EyeToy support. DDR X was called a "truly global version", with a multi-regional release by all three major Konami houses.' FROM games WHERE igdb_id = 73042 ON CONFLICT (game_id, language_code) DO NOTHING;
