INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Littlest Pet Shop: Garden', 'Your Littlest Pet Shop Pets Come to Life! Each game comes with 6 unique pets, collect them all! Collect and name 20 pets - including brand new Fanciest, Cuddliest, Sportiest, Chilliest and more! Dress up your pets with over 100 accessories to make them even cuter. Explore 4 unique pet-sized worlds! Compete in mini games with your little pets to earn Kibble Coins! Play 16 fun and challenging games with your pets to unlock accessories, playsets, and new pets too!' FROM games WHERE igdb_id = 48020 ON CONFLICT (game_id, language_code) DO NOTHING;
