INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kara no Shojo', 'Set in 1956, Reiji is investigating a series of strange crimes that revolve arround an all-female academy, which may be involved with the murder that killed his wife. Also, he meets Toko Kuchiki, a strange girl who hires Reiji for the job to "find her real self".' FROM games WHERE igdb_id = 46980 ON CONFLICT (game_id, language_code) DO NOTHING;
