INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ToHeart2: AnotherDays', 'ToHeart2: AnotherDays is a spin-off from ToHeart2, taking place sometime after the events of the original game, its main storyline allows the player to pursue seven heroines consisting of both supporting female characters from To Heart 2 and new characters. In addition, it also contains two additional scenarios that extend storylines from the original game.' FROM games WHERE igdb_id = 242474 ON CONFLICT (game_id, language_code) DO NOTHING;
