INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monster-hunter-freedom-unite', 20427, '2008-03-27', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hcz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hrwhy8rimgqnaelwxnpx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Hunter Freedom Unite', 'Japan''s most successful PSP title, Monster Hunter Portable 2G, is heading to Europe and US. Renamed Monster Hunter Freedom Unite, this latest installment in the epic Monster Hunter series delivers over 500 hours of gameplay spanning some 400 missions. Added with previously unreleased monsters, weapons and missions and you have the biggest Monster Hunter game to date. Using the Ad-Hoc connection players can adventure with up to three friends for a savaging multiplayer hunting party. From devising the strategy to executing the attack, players will need to work together in order to hunt down the ferocious beasts and progress through the wide range of quests on offer. Players will be rewarded for their use of deep fighting combat systems, encouraging them to seek out the more experienced hunters and team up in order to learn from their experience. Even in single player mode Hunters won''t be alone thanks to the introduction of the new AI Felyne feature. Accompanying players on quests your furry ally will helping them battle monsters and gather extra resources.' FROM games WHERE igdb_id = 20427 ON CONFLICT (game_id, language_code) DO NOTHING;
