INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imagine: Makeup Artist', 'Become an aspiring makeup artist! Start as an amateur and train yourself in different makeup techniques. Make your clients happy and beautiful by catering to their every need. Research the perfect looks, participate in contests, and build your reputation as a professional makeup artist! This is the sequel to Cosmetic Paradise, which was only released in Europe for the English-speaking audience.' FROM games WHERE igdb_id = 7931 ON CONFLICT (game_id, language_code) DO NOTHING;
