INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi Connection V5.5 Celebrity', 'The Tamagotchi Connection V5.5 Celebrity is a refresh of the Tamagotchi Connection Version 5. The Japanese edition was released on March 29, 2008, while the English edition was released in September 2008 in North America. The English version includes two additional games and several parent characters not on the Japanese version.' FROM games WHERE igdb_id = 229955 ON CONFLICT (game_id, language_code) DO NOTHING;
