INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Zone II: The Tears of Opa-Opa', 'Fantasy Zone II DX: The Tears of Opa-Opa is a special Fantasy Zone game first seen in the Sega Ages 2500 series entry, Sega Ages 2500 Series Vol. 33: Fantasy Zone Complete Collection. It is a remake of Fantasy Zone II: The Tears of Opa-Opa running on emulated Sega System 16 arcade hardware. As of MAME version 0.146u2, the game is currently available to play in an emulator. Fantasy Zone II DX was re-released with additional features in 2014 in Japan and 2015 worldwide as 3D Fantasy Zone II W on the Nintendo 3DS.' FROM games WHERE igdb_id = 202907 ON CONFLICT (game_id, language_code) DO NOTHING;
