INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ikki-tousen-eloquent-fist', 38475, '2008-11-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co723l.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikki Tousen: Eloquent Fist', 'Ikkitousen: Eloquent Fist is a fighter that includes ample amount of fan service, over 4000 animated cut scenes and is fully voice supported. The combat mode features an action system which allows players to control their characters with ease and the graphics are as high quality as the anime. Combat is all exciting and such but its the fan service that most people are looking forward to when they play this game. Rip the boss''s clothes to shreds as you launch sure kill attacks on them. Aside from the existing cast, the fighter spots original characters and story lines that comes with them. Enjoy portions of the plot that you will see no where else.' FROM games WHERE igdb_id = 38475 ON CONFLICT (game_id, language_code) DO NOTHING;
