INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shepherds-crossing-2', 47797, '2008-06-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49vj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scew6k.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shepherd''s Crossing 2', 'Shepherd''s Crossing 2 DS is a full featured and in-depth farming simulation and strategy game. At its heart, the game is about the player living in a small town and communicating with the other villagers while raising livestock, harvesting crops, and building a farm. Aside from laying out fields and deciding where to herd the animals, players must also pay attention to the placement of their resources, arranging their life as they see fit. As a special feature unique to the DS, interaction with others is a major part of the game. One can even court, date and marry. It''s just one goal in a game filled with things to do and people to meet. The game is beautifully animated in a Japanese anime style. The open-ended gameplay styles mean the player can choose what they want to do whether it be breed animals, farm their fields, build relationships with the people around town or any combination of these activities as well as many others. The DS allows for unique touch screen controls that are implemented into most of the in-game activities. With so many different activities and open-ended style simulation gameplay, there are hours and hours of entertainment available to players.' FROM games WHERE igdb_id = 47797 ON CONFLICT (game_id, language_code) DO NOTHING;
