INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vila do Nevoeiro R.E.L.I.D.O', 'Vila do Nevoeiro R.E.L.I.D.O is an psychological horror game that tells the story of Adam, who has recently moved to the strange Nevoeiro Village shortly after divorcing his wife, and his son, Charles, who has mysteriously disappeared in the midst of a distorted world. Desperately, Adam searches for Charles, not knowing if he is dreaming or going insane.' FROM games WHERE igdb_id = 261300 ON CONFLICT (game_id, language_code) DO NOTHING;
