INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Windy x Windam', 'Notable solely for being "That Fighting Game with Izuna and Shino in it", Windy X Windam is a Nintendo DS Fighting Game by Ninja Studio starring (or "co-starring", if you prefer) seven fighters from a remote island kingdom called Gawain, a place where people empowered with devices called "Windies" are given the ability to fly. They, along with a mysterious "eighth" malefactor, have assembled for a tournament, wherein the winner will have his/her one greatest wish granted. Aside from the flight and special attacks granted by their devices, the fighters also have the ability to transform (for a very brief period of time) into a more powerful form.' FROM games WHERE igdb_id = 94899 ON CONFLICT (game_id, language_code) DO NOTHING;
