INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abuzittin''in Maceraları II: İz Peşinde', 'This game starts in fullscreen. “Çıkış” in the menu or Alt+F4 shortcut will exit the game. In the intro, the developer states that the game “is sutiable for ages 11 and up”, “contains unfavourable behaviors” and “contains vulgarity”.Full Turkish solution of the game can be found in Extras.' FROM games WHERE igdb_id = 330333 ON CONFLICT (game_id, language_code) DO NOTHING;
