INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vantage Master Portable', 'This PSP remake of Vantage Master features new characters from The Legend of Heroes: Trails in the Sky, and multiplayer mode using the PSP''s wireless capabilities. Falcom announced the development of Vantage Master Portable for the PSP on December 20, 2007, which was released on the actual release data. Unlike the original Windows version, the interface is changed slightly for the PSP, meaning no PC mouse functionality. Otherwise, the game is essentially a complete 3D clone of the original Vantage Master with remastered orchestral music and corresponding gameplay mechanics.' FROM games WHERE igdb_id = 196855 ON CONFLICT (game_id, language_code) DO NOTHING;
