INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ricochet Infinity', 'Ricochet around the Galaxy in this dynamically brilliant breakout action game! Trek across 216 awesome levels, with thousands more online, earning new ranks in the Galactic Tournament, by yourself or with a friend. Play the re-energized Ring Game, winning new balls and ships with unique specialties to give you the edge! Control your ball with the wildly innovative Recall feature...once you’ve tried it, you can’t go back! Travel to the stars and beyond in your glorious quest to become the Ringmaster Grand Champion!' FROM games WHERE igdb_id = 23820 ON CONFLICT (game_id, language_code) DO NOTHING;
