INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleach: Soul Carnival', 'This game features more than 10 stages and the player must proceed to the final stage and fight Sōsuke Aizen. Bonus stages and extra characters can also be unlocked. The game takes place between Ichigo''s training and the Hueco Mundo arc. All characters appear in a super deformed version of themselves. A sequel for this game has been released.' FROM games WHERE igdb_id = 25930 ON CONFLICT (game_id, language_code) DO NOTHING;
