INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clue Classic', 'Clue Classic is a video game based on Hasbro''s Cluedo franchise. It was developed by Games Cafe and published by Reflexive Entertainment on June 3, 2008. The single-player interactive game was inspired by the artwork in the 2002/2003 Classic Detective Game version, featuring the original six characters, weapons and nine original rooms. Producer was Rob Adams, designer was Rob Adams, programmer was Chad Sterling, lead Artist was Erin Miller, and Music & Sound was by Staffan Melin and David Chan.' FROM games WHERE igdb_id = 47075 ON CONFLICT (game_id, language_code) DO NOTHING;
