INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Counter-Strike Online', 'Counter-Strike Online is a first-person shooter video game, targeted towards Asia''s gaming market released in 2008. It is based on Counter-Strike and was developed by Nexon with oversight from license-holder Valve. It uses a micropayment model that is managed by a custom version of Steam.' FROM games WHERE igdb_id = 77251 ON CONFLICT (game_id, language_code) DO NOTHING;
