INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('irekae-iq-crossword', 292040, '2008-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wte.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr8yc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Irekae IQ Crossword', 'For crossword fans who are tired of ordinary crosswords! If you know the words that enter each square from the hint of the vertical and horizontal key, replace the letters. It''s a new sense crossword puzzle that just replaces characters. If multiple words are completed with a single replacement, you will get a high score! In addition, the player''s IQ level will be judged according to the time required to clear and the score. The lovely picture with the theme of 10 regions around the world and the pleasure of being able to speak one after another with easy operation will definitely make you addicted ♪ Let''s play with 3 types of modes. There are three types of game modes: "World Mode" that clears the stage within the time limit, "IQ judgment mode" that judges the player''s IQ level, and "Free Mode" that you can play carefully without worrying about the time limit. Also, in the "Records" on the menu screen, you can check game results such as "IQ test results" and "high score". Get a high score with various techniques! You can solve crosswords just by replacing the characters, but the score fluctuates greatly depending on how you solve it! Aim for a high score by making full use of various techniques unique to "IQ crossword" such as "pair line" that completes two lines at the same time, "cross line" that completes lines at the same time, and "combo" of continuous correct answers. Let''s stay!' FROM games WHERE igdb_id = 292040 ON CONFLICT (game_id, language_code) DO NOTHING;
