INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'We Cheer', 'We Cheer brings the excitement and fun of cheerleading to the Wii Console. Use your Wii Remote(s) as pom-poms and get ready to show your team spirit while you kick, jump, flip, spin and dance to the rhythm of the hottest music from the past and present. Master your moves with precision and timing, and get ready to beat the other squads to claim the number 1 spot in the championship. Bring it on!' FROM games WHERE igdb_id = 5263 ON CONFLICT (game_id, language_code) DO NOTHING;
