INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Think Fast: The Ultimate Trivia Showdown', 'A game based upon the popular Buzz! series. The questions are now all Disney related and the host of the show is Genie from Aladdin. Battle with up to 4 players against each other using the buzzers. Players can choose between a few different game modes. The game modes include a Quick start mode (play 5 rounds using basic settings), Basic game mode (players can now choose for how long they want to play, at what location they want to play, and can choose a sound that will be played when they hit the big red button on their buzzer), and a Custom game mode (players can select their favorite rounds).' FROM games WHERE igdb_id = 5218 ON CONFLICT (game_id, language_code) DO NOTHING;
