INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Spyro: Dawn of the Dragon', 'Three long years have passed since Spyro and Cynder were trapped in the crystal, since then Malefor has unleashed his evil onto the world. In this third chapter of the epic Legend of Spyro trilogy, Spyro must fulfill his destiny and face the Dark Master. As evil spreads over the world, Spyro and Cynder must discover new abilities and unlock their true powers to defeat Malefor and stop him from destroying the world.' FROM games WHERE igdb_id = 1584 ON CONFLICT (game_id, language_code) DO NOTHING;
