INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Smash Bros. Brawl', 'Super Smash Bros. Brawl is the third installment in the Super Smash Bros. series and the follow-up to Super Smash Bros. Melee. This edition introduces super attacks referred to as final smashes, as well as a brand-new adventure mode in The Subspace Emissary which is a side-scrolling adventure in the style of a platformer. It retains all basic mechanics of the Super Smash Bros. series, such as a damage meter, stocks, and Smash-style attacks.' FROM games WHERE igdb_id = 1628 ON CONFLICT (game_id, language_code) DO NOTHING;
