INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unsolved Crimes', 'The game is set in New York City. The player is a rookie detective from the homicide division. There are eight cases in the game, and one larger case divided into sections. In this case, a model named Betsy Blake goes missing. She is the sister of the player''s partner, Marcy Blake.' FROM games WHERE igdb_id = 21376 ON CONFLICT (game_id, language_code) DO NOTHING;
