INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'River King: Mystic Valley', 'Journey to rivers, swamps, ponds and hidden fishing spots as you look for the mysterious River King to help your younger sister wake from her unexplained slumber. But you are not alone on this adventure, make friends with the magical creatures of Mystic Valley and unlock their special abilities to help you. You are your sister''s last hope and it will take all of your fishing skill to catch the elusive River King!' FROM games WHERE igdb_id = 20520 ON CONFLICT (game_id, language_code) DO NOTHING;
