INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Street Fighter II Turbo HD Remix', 'The Capcom arcade classic receives a whole new look with Super Street Fighter II Turbo HD Remix. Capcom maintains the integrity of the popular game by utilizing the original game code while upgrading the graphics with new artwork and high resolution 1080p images -- all of the art, from character animation to stage backgrounds, will be completely redrawn by Udon Entertainment, the company responsible for the official US Street Fighter series of comics. Super Street Fighter II Turbo HD Remix includes both online and offline competition for one to two players.' FROM games WHERE igdb_id = 21796 ON CONFLICT (game_id, language_code) DO NOTHING;
