INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s EndWar', 'In addition to traditional RTS controls, EndWar goes beyond other Real Time Strategy games by letting you use your own voice to control your units, offering you true control at the speed of thought. Instead of using the traditional top-down view, EndWar employs a unique third-person camera that puts you in the heart of the battle, making the use of terrain and cover even more critical to achieving victory. Zoom in and out at will and watch the devastation unfold as hundreds of units engage the enemy on fully destructible battlefields.' FROM games WHERE igdb_id = 7468 ON CONFLICT (game_id, language_code) DO NOTHING;
