INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barbie-horse-adventures-riding-camp', 45175, '2008-10-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dbr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie Horse Adventures: Riding Camp', 'Barbie Horse Adventures: Riding Camp is the fourth game of the Barbie Horse Adventures video game series based on the Barbie line of dolls by Mattel. The game was released on Microsoft Windows, Nintendo DS, PlayStation 2, and Wii in 2008. Gameplay: The player on the role of Barbie on an island which has been the victim of a storm. The game is freeform in a sandbox world, allowing the player a range of activities. The core gameplay is based around equestrianism: players tame, feed, groom, and train horses of various breeds. As Barbie, the player has the option of completing various quests given to her by the denizens of the island, such as finding lost items or fixing broken objects. Travel over the island is on horseback. Barbie can participate in timed horse races. Barbie can also buy diverse sets of clothing, enabling her to play dress-up.' FROM games WHERE igdb_id = 45175 ON CONFLICT (game_id, language_code) DO NOTHING;
