INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky Star: Ryouou Gakuen Outousai - DX Pack', 'Lucky Star: Ryouou Gakuen Outousai - DX Pack is a deluxe edition of the game that includes: - A copy of the game - A school girl''s sailor uniform - A collection of posters from Lucky Star - A school nameplate and pin There was also some pre-order bonuses that included such as a CD-ROM featuring various voice overs, a PC fighting game featuring characters from Lucky Star and a balsamic vinegar trap.' FROM games WHERE igdb_id = 214143 ON CONFLICT (game_id, language_code) DO NOTHING;
