INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('potpourrii', 21799, '2008-10-10', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hnnngapovbqvupueyexi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zgqjrytpywhp772jxzbo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Potpourrii', 'Potpourrii is played similar to the games Puzz Loop and Puzzle Bobble. The plot of the game revolves around a group of gnomes repairing their magical forest after a chaotic rampage by an evil warlock frees all the forest spirits. The object of the game is for the player to contain these spirits by matching three or more spirits of the same type in order to make them disappear.  Players shoot spirits from a cannon on a track that surrounds a swirling whirlpool (the "potpourii") where the spirits are suspended, with each quadrant of the play area corresponding to a different season and the different types of spirits players can shoot. The twist is that instead of simply matching the required number of spirits, the player must add to the cluster a different type of spirit that reacts to them and allows the cluster to disappear' FROM games WHERE igdb_id = 21799 ON CONFLICT (game_id, language_code) DO NOTHING;
