INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '428: Shibuya Scramble', 'A kidnapping on the streets of Shibuya brings together a hot-blooded detective, hard-hitting journalist, former gang leader, the head researcher of a big pharma manufacturer and a part-timer stuck in cat costume for a series of events each more unexpected and outrageous than the last.' FROM games WHERE igdb_id = 95069 ON CONFLICT (game_id, language_code) DO NOTHING;
