INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Primeval Hunt', 'Primeval Hunt is a shooting arcade game which is developed and published by Sega and runs on their Sega Lindbergh hardware. It comes in both standard and deluxe models, with the deluxe version featuring a 62" HD Screen. Released for arcades in early 2008, players in the game must hunt 10 species of dinosaur over 12 levels and 3 Bonus stages using light guns styled after pump action shotguns with speakers mounted for the first time in the ''butt'' of each gun. The game also utilizes a unique touch screen interface to give a free-roaming element to the gameplay. It is similar to the Big Buck Hunter arcade games.' FROM games WHERE igdb_id = 58735 ON CONFLICT (game_id, language_code) DO NOTHING;
