INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WALL-E', 'Go on a galaxy quest with WALL-E through eight exciting games. V.Smile V-Motion uses a wireless, motion-sensitive controller to help teach shapes, colors, matching, problem solving, logic, letters, numbers, puzzles and recycling. Featuring characters from Disney and Pixar''s WALL-E movie, kids will have a blast getting into the action.' FROM games WHERE igdb_id = 213194 ON CONFLICT (game_id, language_code) DO NOTHING;
