INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aquanaut-s-holiday-hidden-memories', 7271, '2008-09-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49vq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scspc5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aquanaut''s Holiday: Hidden Memories', 'The actual story mode of the game can be compared to an adventure game. The main - unnamed - character is a journalist, in search of the missing oceanographer William "Bill" Graber. Using a submarine called the Dolphin no.2 you explore the seas for clues. The game takes place in Kisira Atoll, in Polynesia. An oceanographic research facility named Kisira Base is the starting point and where you always come back to, for supplies (such as batteries for sonar navigation buoys) and equipment. Two scientists work at the base, the young and dreamy Jessica Porter and the conservative chief Robert Kemelman. Both assist you in solving mysteries, each in their own way. Jessica likes to believe fairytales and legends, while Robert usually comes up with a scientific explanation. All the fish, animals and other discoveries are added to a database. Some fish can communicate and the player has to repeat the sounds made by a fish, using the four trigger buttons of the Sixaxis controller. At all times, the unlocked area of the map is free to explore as you like.' FROM games WHERE igdb_id = 7271 ON CONFLICT (game_id, language_code) DO NOTHING;
