INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Atlantis', 'Atlantis is calling out to a true hero to save it from deadly peril in this long-awaited 3rd installment in the hit Atlantis Quest, The Rise of Atlantis series offering a unique blend of 3 popular gameplays. Set out on an exciting new quest in this spectacular mix of Match-3, Hidden Object and Adventure. Embark on a fascinating new journey around the ancient lands of Rome, Greece, Troy, Phoenicia, Babylon, Egypt and Carthage to acquire seven mysterious crystals of power. Appease Poseidon, the patron god of the Atlanteans, and save the legendary continent.' FROM games WHERE igdb_id = 26961 ON CONFLICT (game_id, language_code) DO NOTHING;
