INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Chaser: Stardust of Dreams', 'Magical Chaser ~Stardust of Dreams~ is a Japanese dōjin 2D fighting game for Windows, developed by the dōjin circle Dakken for the Fighter Maker 2nd engine and released in 2008. The game is a crossover of five magical girl Anime series: Ojamajo Doremi, Princess Comet, Fushigi Mahō Fan Fan Pharmacy, Fushigiboshi no Futagohime and Kasumin.' FROM games WHERE igdb_id = 315061 ON CONFLICT (game_id, language_code) DO NOTHING;
