INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dogfight 2 : The Great War', 'Dogfight 2: The Great War is a arcade flight game where players pilot historical planes (Spitfires, Mustangs, Messerschmitts) through intense missions in the Pacific, North Africa, Europe, and Russia, using unique "ACE" targeting to quickly lock and shoot down enemies while completing objectives like ground attacks or fleet defense' FROM games WHERE igdb_id = 383249 ON CONFLICT (game_id, language_code) DO NOTHING;
