INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plus Belle la Vie: Le Secret du Dr Livia', 'Based on the long-running French TV drama Plus belle la vie, this 2008 Nintendo DS adventure game lets players investigate a series of mysteries set in the fictional Marseille neighborhood of Le Mistral. Players take on the role of an original character conducting an investigation into a theft at the local bar and the sudden disappearance of a key figure from the show. The game combines dialogue-based exploration, clue gathering, and mini-games, and features familiar locations and characters from the series.' FROM games WHERE igdb_id = 349054 ON CONFLICT (game_id, language_code) DO NOTHING;
