INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-curse-of-montezuma', 125494, '2008-05-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co890z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsdga.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Curse of Montezuma', 'What happens when you combine beauty, brains and a taste for adventure? You get Cathie Jones, world famous archeologist and granddaughter of Emily Jones from The Treasures of Montezuma. In The Curse of Montezuma, Cathie picks up where her grandmother left off and embarks on an amazing match-three journey to find the legendary Fountain of Youth and stop the spread of a deadly virus. With millions of lives hanging in the balance, it''s up to you to match thousands of glittering gems along web-like latticework and unleash astonishing powers that can help Cathie reach her goal.' FROM games WHERE igdb_id = 125494 ON CONFLICT (game_id, language_code) DO NOTHING;
