INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Reflex: Steamworks Edition', 'Master the Art of Speed and become a Ninja Gamer! Ninja Reflex uses martial arts challenges to test your reflexes, sharpen your hand-eye coordination, and measure your reaction times to the millisecond. Wield throwing stars, katanas, nunchucks...even chopsticks! Progress from White Belt all the way to Black Belt, 3rd Degree, and see if you can complete the 50+ Steam achievements on your journey!' FROM games WHERE igdb_id = 82011 ON CONFLICT (game_id, language_code) DO NOTHING;
