INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Generation Xth: Code Breaker', 'Code Breaker is the second game in the "Generation Xth" trilogy.  It is a first person dungeon crawling RPG with turn based combat released for PC in Japan. You use a team of 6 people to explore the Abyss. The game allows you to carry over your save file from the first game to continue the adventure with your original team. The first and second game were later re-released together on the Playstation Vita in Japan under the name "Tokyo Shinseiroku: Operation Abyss" in 2014 and in North America and Europe under the name "Operation Abyss: New Tokyo Legacy" in 2015.' FROM games WHERE igdb_id = 14683 ON CONFLICT (game_id, language_code) DO NOTHING;
