INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet''N''Fuck Hawaiian Vacation', 'Your hawaiian vacation dream has came true! 20 minutes ago, your plane arrived at the heavenly islands. Endless white sand beaches, warm ocean and a lots of sexy bikini girls! But first of all you should take your baggage and catch a taxi. Wait a minute, Who is this beautiful blonde? I think she could be a good begining for our story :)' FROM games WHERE igdb_id = 221625 ON CONFLICT (game_id, language_code) DO NOTHING;
