INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Conan: Unchained', 'Age of Conan: Unchained is an award-winning and critically acclaimed massively multiplayer online game set in the sexy, savage and brutal world of Conan the Barbarian. Tread in the footsteps of the greatest fantasy hero of all time, and explore the vast reaches of Hyboria. Choose between twelve different classes, from Barbarian to Demonologist, and fight your way to riches and glory as you battle creatures straight out of hell or even engage in colossal guild vs. guild warfare!' FROM games WHERE igdb_id = 16402 ON CONFLICT (game_id, language_code) DO NOTHING;
