INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaidou-ni-kisu', 380806, '2008-12-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaza3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaidou ni Kisu', 'A story constantly demands to choose between two choices. Four men and women who had known each other via the internet had met and gone through several offline meetings. At the inn they are staying, they meet a mysterious girl, Hiro. As they gradually deepen their relationship with her, the protagonist fell in love with such a girl. During the limited days of the offline meeting, A pleasant and elated time slowly passes. ...Nevertheless, no matter how leisurely it is, The day of parting will definitely come. "...I won''t let that happen." There is only one choice entrusted to you. A story with only one turning point. Is it white...? Or is it black...? As those colors are placed upon, you will see what lies within those "gray eyes'''' for the first time.' FROM games WHERE igdb_id = 380806 ON CONFLICT (game_id, language_code) DO NOTHING;
