INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris Party', 'Experience Tetris like never before! Tetris Party is a deceptively simple, totally addictive puzzle game that is sure to keep you and all of your friends and family entertained for hours on end. The WiiWare game features ten never-before-seen single-player and multiplayer variations of Tetris, including Field Climber, Stage Racer, Shadow, and Wii Balance Board-enabled modes. Several of the modes give users the chance to take advantage of the unique point-and-shoot capabilities of the Wii Remote controller.' FROM games WHERE igdb_id = 5217 ON CONFLICT (game_id, language_code) DO NOTHING;
