INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Way of the Samurai 3', 'Honour, sacrifice, betrayal… Your choices make you who you are. How will history remember you? You must wield the sword of a mysterious lone samurai during Japan''s turbulent Sengoku era, in one of the most atmospheric action RPGs ever created. Explore the villages, body-strewn battlefields, bandit fortresses, immense castles and local town of Amana, in an open world bustling with a rich cast of colourful characters that you can help, ignore or victimise.' FROM games WHERE igdb_id = 7247 ON CONFLICT (game_id, language_code) DO NOTHING;
