INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantomphobia: Zhenli', 'The new version of an older game (Phantomphobia Outsider) it was released in 2008 by a Chinese team. It follows a similar premise to that of the older game, with Edward falling into a parallel world in which alchemy doesn''t exist and everyone has fulfilled his wishes. Now he must find a way back to his world, as well as solving a chimera incident. The game features boy x boy romance, and different paths and endings according to the chosen companion.' FROM games WHERE igdb_id = 331946 ON CONFLICT (game_id, language_code) DO NOTHING;
