INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saucer Arena', 'In Saucer Arena you are a flying saucer. The Order of Red Saucers Challenges you to fight in the arena. Your flying saucer is equipped with a recharging plasma shield. If it depletes, your hull takes damage directly.You are given 3 special abilities to use. Earn money by destroying units, which you can use to purchase upgrades. There are three difficulty levels, easy/medium/hard. Saucer Arena has 36 waves.' FROM games WHERE igdb_id = 348957 ON CONFLICT (game_id, language_code) DO NOTHING;
