INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'iRacing', 'From NASCAR, rallycross, and Aussie Supercars to sports cars and Grand Prix racing, iRacing has it all. All you need is a computer, a gaming wheel or game pad that simply plugs into the USB port of your computer and an Internet connection. iRacing centrally organizes all of the racing for you with over 150 cars and tracks, 40 official series , or you can choose to host your own race or race in one of over 800 private leagues.' FROM games WHERE igdb_id = 8204 ON CONFLICT (game_id, language_code) DO NOTHING;
