INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Football ''09', 'All the hard-hitting action of a realistic simulation and wacky arcade game in one! Authentic NFL strategies & teams 32 Top NFL pros, 22 Backyard kids Custom teams & plays Easy enough for rookies, challenging for all-stars Single game & season modes Crazy Power-ups & unlockables The only game with NFL pros as kids!' FROM games WHERE igdb_id = 4687 ON CONFLICT (game_id, language_code) DO NOTHING;
