INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deepolis', 'In Deepolis, the player takes on the role of under water admiral commanding a submarine in a three-dimensional underwater world, with the aim of completing quests and sinking other players and NePCs. As a result, the player collects experience points (EP) and advances upwards through the levels. The game optionally supports player clans, both for PVP and PVE play.' FROM games WHERE igdb_id = 318139 ON CONFLICT (game_id, language_code) DO NOTHING;
