INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Club', 'The Club is a new breed of third-person shooter, combining fast-paced run and gun gameplay, destructive environments, and lethal weapons. You will fight to survive in a shadowy underground blood-sport controlled by a faceless, obscenely wealthy and influential elite who place their bets on who will survive as the blood-bath ensues before them. Take control of up to eight uniquely trained killers motivated by greed, driven by pure insane bloodlust, and hell bent on earning respect on a global level.' FROM games WHERE igdb_id = 6940 ON CONFLICT (game_id, language_code) DO NOTHING;
