INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantastic Contraption', 'The original 2008 2D physics building game! With over 1.5 million players, Fantastic Contraption is a true classic. Your goal is simple: move the red ball from the blue building zone to the pink goal area. Your tools: wood rods (solid), water rods (pass through stuff), and wheels that turn clockwise or counterclockwise. Your solutions: NEAR INFINITE. Players have saved over 10 million unique designs, solving levels with everything from cars to catapults to conveyor belts or just pure gravity.' FROM games WHERE igdb_id = 168671 ON CONFLICT (game_id, language_code) DO NOTHING;
