INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Spy Fun House', 'Solve I Spy riddles to earn tickets to a Fun House, a topsy-turvy world where nothing is as it appears! Master brain-teasing puzzles and play exciting games while exploring the Fun House. The game is based on I Spy Fun House and is a remake of the DS version of this game.' FROM games WHERE igdb_id = 252149 ON CONFLICT (game_id, language_code) DO NOTHING;
