INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Super Sluggers Cards', 'To coincide with the North American release of Mario Super Sluggers in August 2008, an online card game was created on . The cards to collect for it were found on kid-friendly sites like 4KidsTV and Nick.com and even YouTube (mainly to promote the Mario Super Sluggers game itself).' FROM games WHERE igdb_id = 339844 ON CONFLICT (game_id, language_code) DO NOTHING;
