INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney All-Star Cards', 'Disney All-Star Cards is a collection of 6 card games, starring classic Disney characters such as Mickey, Minnie, Goofy, Donald and Daisy. All games feature 4 players, being 3 computer controlled. The game has a "currency", the pixie dust. It can be used to cheat during any of the games (the cheat is different to each game), to buy cards from the card store or to unlock artwork in the gallery.' FROM games WHERE igdb_id = 98009 ON CONFLICT (game_id, language_code) DO NOTHING;
