INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monopoly--18', 23767, '2008-10-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/g2rsyfgo3z5ovfa8b3zj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9v53.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monopoly', 'The famous Monopoly board game comes to the current generation of consoles featuring a variety of new features, including mini-games. The Monopoly video games promise a fresh take on the timeless classic with accessible gameplay for players of all ages and skill levels. The all-new digital gaming edition brings a party twist and features 4-player simultaneous play, ensuring that everyone is engaged and allowing the whole family to get involved in the fun and play together. Faster gameplay eliminates downtime freeing up players to wheel and deal their way through some of the most recognizable cities and landmarks from around the world. Families can fill up their passports as they try to unlock new and never-before-seen game boards or challenge each other to fun interactive mini-games like breaking out of the jail cell and running away with all the loot. Play in offline single or multi-player mode and compete to own it all and win!' FROM games WHERE igdb_id = 23767 ON CONFLICT (game_id, language_code) DO NOTHING;
