INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Tribe', 'Create a prosperous island paradise for your industrious, intelligent tribe with this real-time Brain Teaser! Your tribe will have a mind of its own, learning skills and starting families even when you`re not around, but check back often to keep your island idyllic. Uncover mysterious secrets; unlock exciting new technology; build wondrous structures, and even explore other exciting islands in My Tribe!' FROM games WHERE igdb_id = 16180 ON CONFLICT (game_id, language_code) DO NOTHING;
