INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA Manager 09', 'FIFA Manager 09 is a typical German soccer manager where the player is responsible for the financial and athletic success of his team. As usual the player has a lot of options to set which are located in several menu screens. The main part of the screen is surrounded by statistics screens which tell the most important facts without needing to navigate to the associated menu screen.' FROM games WHERE igdb_id = 20679 ON CONFLICT (game_id, language_code) DO NOTHING;
