INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sengoku Basara X', 'Sengoku BASARA X (pronounced Cross) is a 2D Fighting spinoff developed by Arc System Works and released by Capcom at the arcades on April 2008, featuring 10 playable characters each with their own uniqueness. Later on it was ported to the PlayStation 2, adding extra contents such as 2 more playable characters and a challenge mode.' FROM games WHERE igdb_id = 68950 ON CONFLICT (game_id, language_code) DO NOTHING;
