INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tatsunoko-vs-capcom-cross-generation-of-heroes', 50726, '2008-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pcw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3g8g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tatsunoko vs. Capcom: Cross Generation of Heroes', 'In this game, players engage in combat with a team of 2 characters or with a single giant character and attempt to knock out their opponents. It is the 7th Capcom-designed installment in their Vs. fighting game series, which includes the Marvel vs. Capcom and Capcom vs. SNK series, and the first to be fully rendered in 3D graphics. The game is set in a 2.5D environment; characters fight in a two-dimensional arena, but character models and backgrounds are rendered in three-dimensional graphics. The game is designed around a simplified three-button attack system, which was inspired by the simplistic control schemes commonly used by both the Vs. series and the Wii. This is an expanded port of the original Arcade game (that use Wii-based hardware) of the same name and was released only in Japan 2 years prior to the international updated version "Ultimate All-Stars". This port adds some new characters, including Viewtiful Joe.' FROM games WHERE igdb_id = 50726 ON CONFLICT (game_id, language_code) DO NOTHING;
