INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ape Quest', 'The ape kingdom is cursed and it''s up to you, the prince, to redeem yourself and restore peace to the land! Battle your way through the evil minions that have overrun Toqsica Kingdom by leveling up your character, collecting new weapons and items, and completing an endless variety of mini-games in this RPG-style ape adventure. It''s more fun than a barrel of monkeys, or apes for that matter!' FROM games WHERE igdb_id = 42799 ON CONFLICT (game_id, language_code) DO NOTHING;
