INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fading Shadows', 'Fading Shadows is a puzzle game set in a vast real-life world with fantasy elements. Navigate your sphere using the beam of light. You will meet numerous obstacles on your way - reveal ancient writings, set fire, reflect light in the mirrors, and evaporate water. Your sphere can change in substance.' FROM games WHERE igdb_id = 42880 ON CONFLICT (game_id, language_code) DO NOTHING;
