INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Fish', 'Click down the bottom to make bubbles to heal your fish, Click up the top to make spikes to kill the enemy. Click and hold to make them bigger to make them more effective. Killing enemies gives you cash which you can spend on upgrades such as ...shotguns...and ion cannons for your cute little fish called piggles or any other name you decide. Game starts out a little slow, but get into it and it gets a lot harder.' FROM games WHERE igdb_id = 335411 ON CONFLICT (game_id, language_code) DO NOTHING;
