INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dengeki Bunko ADV: Baccano!', 'Based on the two Grand Punk Railroad light novels, the game recounts the events aboard the Flying Pussyfoot train from multiple perspectives.The player''s goal is to help the passengers arrive safely in New York City by selecting the correct choices. The game can conclude with one of about fifty scenarios, depending on the player''s decisions.' FROM games WHERE igdb_id = 79641 ON CONFLICT (game_id, language_code) DO NOTHING;
