INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('naruto-shippuden-gekitou-ninja-taisen-ex3', 50729, '2008-12-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gdl.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto Shippuden: Gekitou Ninja Taisen EX3', 'The game includes three game modes that are new to the series. Naruto''s transformation now has three tails. Another new feature is the Senzai Ninriki (translated in Clash of Ninja Revolution 3 as Latent Ninja Powers), where every character glows a certain colour when they hit low health/crisis mode. Similar to gaining new specials in crisis mode as of the first Revolution game and beforehand Naruto: Gekitō Ninja Taisen! 3, the Senzai Ninriki is a special crisis mode that provides certain effects depending on the character, for example Naruto and Temari''s backward strong attacks no longer use up chakra, Hinata can chakra cancel her attacks with no chakra cost, Kakashi deals damage through guard with all his attacks, Neji and Gaara automatically deflect projectiles while standing still, certain characters'' moves become unblockable and so on. Most of the characters'' Senzai Ninriki effects change in Naruto Shippūden: Clash of Ninja Revolution 3 onwards. One of the game''s new modes is the "Hurricane Clash Mode", which is also reworked into the new story mode which is original from the main storyline. In this mode, the player controls their character in a full 3D movement perspective and can take on hordes of ninja in a beat em'' up genre fashion, with many character movesets retweaked solely for this mode. This style has not appeared in any later Gekitou Ninja Taisen/Clash of Ninja games ever since. This game was released only in Japan.' FROM games WHERE igdb_id = 50729 ON CONFLICT (game_id, language_code) DO NOTHING;
