INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DCS: Black Shark', 'DCS: Ka-50 Black Shark is a PC game of the Russian Ka-50 attack helicopter and is the first title in a new Eagle Dynamics and The Fighter Collection simulation series: Digital Combat Simulator (DCS). Following Eagle Dynamics tradition of excellence, DCS: Ka-50 Black Shark will bring an even more realistic simulation experience than its predecessor LockOn: Flaming Cliffs.' FROM games WHERE igdb_id = 21208 ON CONFLICT (game_id, language_code) DO NOTHING;
