INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 3 FES: Limited Edition', 'Each copy comes with 52-page Color Art Book, Soundtrack CD featuring 18 songs and outer Collector''s Box. Engaging Social Link system - build intimate relationships with friends and love interests alike Never the same game twice, with over 20 Social Links and a complex storyline encompassing a full school year. Intense, strategic battle system - Find and exploit enemy weaknesses with the help of your allies Highly stylized designs with beautiful 2D character portraits, detailed 3D animations, and heart-pounding cut scenes.' FROM games WHERE igdb_id = 41865 ON CONFLICT (game_id, language_code) DO NOTHING;
