INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('peggle-nights', 14813, '2008-09-03', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coalcm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar23bl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peggle Nights', 'The sun has set at the Peggle Institute, but the bouncy delight has just begun! Join the Peggle Masters on a dreamtime adventure of alter egos and peg-tastic action. Stay up late to aim, shoot and clear orange pegs, and bask in Extreme Fever glory under the silver moon. Then, put your Peggle skills to the ultimate test in Challenge mode. If you can master all that fevered action, play to your heart''s content with Duel mode and Quick Play. Plus, you can stock your Trophy Room and revel in clickable replays for even more rebounding joy! Explore all 60 levels in Adventure mode Meet a new Peggle Master and learn a new Magic Power Test your skills in 60 challenges Unlock Duel mode to compete against friends and the computer Celebrate your Peggle prowess with clickable replays and a Trophy Room!' FROM games WHERE igdb_id = 14813 ON CONFLICT (game_id, language_code) DO NOTHING;
