INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clonk Rage', 'Clonk Rage is the last title in the "Clonk" series from proprietor Matthes Bender of RedWolf Design, released originally in 2007 and as freeware around 2014. The content of the game is largely similar to the previous release, Clonk Endeavour, simulating nimble workers called "Clonks" that can be controlled en masse directly or via mouse commands to mine, build, and--in the oldest custom of the series--fight in a lighthearted melee.' FROM games WHERE igdb_id = 26429 ON CONFLICT (game_id, language_code) DO NOTHING;
