INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-king-of-fighters-98-ultimate-match', 43643, '2008-03-18', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p2i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10sb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Fighters ''98: Ultimate Match', 'A remixed version of King of Fighters ''98 with rebalanced gameplay, "Ultimate" fighting mode, an unlockable art gallery, and 64 fighters to choose from (10 of these were previously unseen in KoF ''98). Also included is the original Neo Geo version. Additionally, the game now supports 480p resolution. Featuring 5 game modes: Arcade, Single Play (no team), Endless (endurance trial), Practice and Challenge mode. Options include the ability to increase character sprite size, soften the sprite by various degrees (reduces blockiness), and a 3D/2D background toggle. The Ultimate fighting mode lets you toggle three different modes: Move Type: Dash / Step, Evasion Type: Avoiding / Urgent and Power Gauge: Advanced / Extra. The game comes with a second bonus disc, containing trailers and wallpapers for both this title, and the upcoming King of Fighters XII.' FROM games WHERE igdb_id = 43643 ON CONFLICT (game_id, language_code) DO NOTHING;
