INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Chireiden: Subterranean Animism', 'Touhou Chireiden: Subterranean Animism is the eleventh main game of the Touhou Project scrolling shooter series. Subterranean Animism features two playable characters, each with three weapon types representing a youkai assisting them from above ground. Like Mountain of Faith, collecting power items adds up to four "option" satellites around the character, which behave differently according to the character and weapon type, and can be sacrificed for a bomb effect. However, unlike Mountain of Faith, each bomb has a different behavior, and some cause special gameplay effects to occur.' FROM games WHERE igdb_id = 27165 ON CONFLICT (game_id, language_code) DO NOTHING;
