INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fab-5-soccer', 124633, '2008-04-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa7lv.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fab 5 Soccer', 'Create your Dream Team, The Superstars of the soccer world don''t stop playing when they step outside the arena. Join 24 of the world''s most famous players in frenzied, fast-paced, arcade-style 5-on-5 soccer matches. No time outs, few penalties, just frantic soccer play! The best players in the world playing soccer the way Join 24 of the world''s most famous players in Fab 5 Soccer for Nintendo DS. Create your Dream Team with the Superstars of the soccer world. They don''t stop playing when they step outside the arena. Get in on the action with frenzied, fast-paced, arcade-style 5-on-5 soccer matches. No time outs, few penalties, just frantic soccer play. Play the best players in the world the way you play with your friends. Build your team with all-star athletes like Lionel Messi, Luis Figo, Cesc Fabregas, Dejan Stankovic, Jose Reyes, Juan Veron, Dida Silva and more. Win matches to unlock training minutes and build your team''s skills in the Training Gym. Spend minutes to teach your players special moves and boost their stats. Unlock celebrated coaches and goalies to bring your entire team to the next level.' FROM games WHERE igdb_id = 124633 ON CONFLICT (game_id, language_code) DO NOTHING;
