INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chuzzle: Christmas Edition', 'Nuzzle up to some Chuzzly puzzle fun this holiday! The Chuzzles are all dressed up for Christmas and ready for some Yuletide fun! Match Chuzzles to clear them from the board and keep the fun going through all 4 chuzzly puzzly holiday games. The full version of Chuzzle Christmas Edition features: 4 ways to play Cool trophies and power-ups 2 difficulty settings Have a Chuzzly puzzly Christmas and a fuzzy new year! Play today!' FROM games WHERE igdb_id = 228643 ON CONFLICT (game_id, language_code) DO NOTHING;
