INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('discovery-a-seek-and-find-adventure', 9386, '2008-07-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/fy3cez0bbbbrhmsqpxft.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/oelqmohflpfsqzfk51p9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Discovery: A Seek and Find Adventure', 'Break out your magnifying glass and passport—it’s time for Discovery!, the seek-and-find game show with your host, Jerry Landers and the beautiful Jill Summers. Step up to the wheel, and choose today’s adventure! Will it be Spain, China, Australia, or one of three other fabulous international hot spots? Each locale hosts three scenes of play with hundreds of objects to find in each level—more than 1,000 objects in all! Complete a level and spin the wheel to play one of four fabulous mini-games: PriceTag Challenge, Blizzard Bucks, Scene Match Safari or Trivia Takeoff! Enjoy the sights, sounds and hidden-object adventures around the globe and across the U.S. when you make it to the U.S. Roadtrip Jackpot Round. You’ll race against the clock and search through six U.S. cities on your way to hitting the jackpot! Compete against 20 eagle-eyed contestants and rack up achievement stamps in five different game modes in this seek-and-find adventure. Join us for this week’s episode of Discovery!' FROM games WHERE igdb_id = 9386 ON CONFLICT (game_id, language_code) DO NOTHING;
