INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alien-crush-returns', 51097, '2008-12-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5z0o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/efpj02mj7ahdb4brpqdv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Crush Returns', 'Sci-Fi Pinball Action! Defeat an alien army and go online to compete for a high score! Alien Crush Returns is the ultimate incarnation of the popular TurboGrafx pinball classic, Alien Crush. Boasting innovative game play and control features, this is one Wii experience that you don''t want to miss! With all the ball-blazing simplicity and flipper-action thrills of standard pinball, Alien Crush Returns has all the visual and digital elements that you''ve come to expect in a video game, including grotesque, eye-stunning playfields as well as unique Action Ball gimmicks that redefine the fun and excitement of pinball. You can even nudge the machine with your Wii Remote controller. What''s more, you can connect via Nintendo Wi-Fi Connection to enjoy a variety of features, such as four-player head-to-head action, high-score competitions, and Extra Stage downloads.' FROM games WHERE igdb_id = 51097 ON CONFLICT (game_id, language_code) DO NOTHING;
