INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alone in the Dark: Inferno', 'Taking inspiration from the presentation style and structure of a number of acclaimed and globally popular TV action dramas, Alone in the Dark is split into a number of distinct episodes in a season-style format. With approximately 30-40 minutes of gameplay comprising each episode, the structure of Alone in the Dark is adapted for an audience familiar with the hard-hitting bite-size delivery of contemporary TV dramas, offering easy accessibility whether the player has hours to devote or only wants a quick TV-style fix.' FROM games WHERE igdb_id = 21303 ON CONFLICT (game_id, language_code) DO NOTHING;
