INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Crossing: City Folk', 'Step into a living, breathing world where days and seasons pass in real time and your destiny is yours to create. Enjoy a new house, a new neighborhood, and some new friends. Try your luck in a Fishing Tourney, collect shells, or participate in special events and holidays. Communicate with friends and family; travel to the new City, get a Mii makeover, and more. The world is your sparkling, fresh canvas. You choose the pace and you craft the adventures!' FROM games WHERE igdb_id = 2688 ON CONFLICT (game_id, language_code) DO NOTHING;
