INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gang Garrison 2', 'Originally conceived for the 2008 TIGSource.com ''Bootleg Demake'' competition, Gang Garrison 2 is a free multiplayer ''demake'' of Valve''s Team Fortress 2. Gang Garrison 2 presents the player with 9 unique classes to use in frenetic, cooperative multiplayer action in a stylish and unique 8-bit style.' FROM games WHERE igdb_id = 51308 ON CONFLICT (game_id, language_code) DO NOTHING;
