INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Petz Rescue Ocean Patrol', 'Petz Rescue: Ocean Sanctuary is an adventure game in which players manage a dolphin sanctuary for displaced or wounded ocean animals. Players complete various tasks and participate in mini-games, while learning about the plight of endangered species. Tasks/mini-games include tending to the wounds of dolphins, feeding dolphins, preparing medicine, and locating lost animals.' FROM games WHERE igdb_id = 70534 ON CONFLICT (game_id, language_code) DO NOTHING;
