INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('buzz-brain-bender', 23267, '2008-11-28', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2e6o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsox5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz! Brain Bender', 'Nothing bends your brain like Buzz! Give you and your friends a mad mental workout with Buzz''s brain-bending pocket puzzles on PSP. Buzz swaps his trademark suits and the bright lights of the studio for a lab coat and clipboard in Buzz!: Brain Bender - a light, entertaining and humorous way to give your brain a workout. Colourful, entertaining brain games, designed to be instantly understandable, fast-paced and accessible for all ages let you test your cognitive mojo or take on specific challenges. Once you''ve greased the wheels, Buzz!: Brain Bender lets you take on all comers with the entertaining Pass Around Brain Battle mode for up to six players, where one PSP is passed between players. Challenge your mind in 16 brain-bending mini-games across four fun categories: Analysis, Observation, Memory and Calculation Take the test and find out how powerful your brain is, collect Boffin Awards or try out the various challenges for the ultimate brain game fix Take on up to six friends on just one PSP with the exciting Brain Battle Pass Around mode Four player profiles can be saved, allowing you to compare your progress with friends and family.' FROM games WHERE igdb_id = 23267 ON CONFLICT (game_id, language_code) DO NOTHING;
