INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go, Diego, Go! Great Dinosaur Rescue', 'In Go, Diego, Go! Great Dinosaur Rescue your child joins Diego on an epic prehistoric adventure on the Nintendo Wii. In this journey to the earth''s Cretaceous Period, Diego, his sister Alicia and their pal Baby Jaguar travel millions of years back in time to the age of the dinosaurs to help Maia the Maiasaura find her way back to her family on Egg Island. In this amazing rescue adventure your child will explore a wild jungle-covered world filled with dinosaurs and volcanoes where they will have to climb rock walls, travel along monkey bars, solve puzzles and even jump on a pogo stick to help Diego’s friend find her way home.' FROM games WHERE igdb_id = 47978 ON CONFLICT (game_id, language_code) DO NOTHING;
