INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('professional-bull-riding-out-of-the-chute', 51113, '2008-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coar2y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctss7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professional Bull Riding: Out of the Chute', 'Rider or Bull? Pick one, press start and hang on! The Toughest Sport on Dirt is finally the Toughest Game on Gaming Console. Climb on the back of the most notorious, fearsome and nastiest bucking bulls on the planet for the wildest ride in any arena. Or become 2000 pounds of fury and play as the bull and turn your agressions toward that cowboy on your back. Justin McBride or Little Yellow Jacket? Get in the Chute... Features • Play as 12 real pro bull riders or 12 real raging bulls • Compete against a friend in Rider vs. Bull Mode • Win the 10-event PBR Season and make it to the World Finals in Las Vegas • Start a career as a Rider or a Bull • Unlimited Mode eliminates the clock for a battle of wills This is not a rodeo. This is the PBR!' FROM games WHERE igdb_id = 51113 ON CONFLICT (game_id, language_code) DO NOTHING;
