INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War of the Human Tanks: Alter', '"War of the Human Tanks: Alter is the second installment of the War of the Human Tanks series, and sequel to War of the Human Tanks. This time you assume command of the enemy of the first game, the Royal Army, and fight back for all you hold dear! War of the Human Tanks is a story driven strategy game with a gameplay reminiscent of Battleship and Chess, featuring a story of war, loyalty, sacrifice and human shaped tanks."' FROM games WHERE igdb_id = 11692 ON CONFLICT (game_id, language_code) DO NOTHING;
