INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectraball', 'Spectraball combines elements of platforming, puzzle solving, addictive gameplay, and stunning visuals to deliver an experience that sets a new standard for the genre. In addition, Spectraball utilizes Steamworks, offering full support for achievements and stat tracking. Roll, jump, and launch your way through several diverse and detailed environments.' FROM games WHERE igdb_id = 14918 ON CONFLICT (game_id, language_code) DO NOTHING;
