INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shijou-saikyou-miyamoto-julia', 288156, '2008-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7szd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqqa7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shijou Saikyou Miyamoto Julia', '50 years after the end of the Galactic War, the eastern galaxy''s bubble economy finally pops. The resulting depression catapults society into a desperate age of class stratification, with workers at the bottom struggling to make ends meet. Julia Miyamoto, the player character, is a temp worker doing her best to get by in the bad economy. She takes a gig at the Galaxy Crisis Management Organization, where she discovers that she has an incredible talent for cleaning up other people''s messes, and sets out to prove herself. In the process, she''ll find herself drawn into a galaxy-wide conspiracy. This mission-based action RPG has players setting out to clear missions by wiping out waves of enemies as efficiently as possible.' FROM games WHERE igdb_id = 288156 ON CONFLICT (game_id, language_code) DO NOTHING;
