INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shootanto: Evolutionary Mayhem', 'In Shootanto: Evolutionary Mayhem, players start as primates and battle lizardmen across the epochs, from primeval to medieval times and beyond. Players who survive each battle will evolve from a lowly monkey to an apeman, then caveman, a human knight, and finally a soldier. The combat continues to change as the lizardmen also evolve throughout the game.' FROM games WHERE igdb_id = 51630 ON CONFLICT (game_id, language_code) DO NOTHING;
