INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pixeljunk-eden', 10700, '2008-07-31', 87, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co248h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4vp1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PixelJunk Eden', 'Utterly unique and spellbindingly beautiful, PixelJunk Eden welcomes you to a psychedelic world unlike anything you’ve ever experienced before. As a tiny, silk-spinning “grimp,” it is up to you to collect the lost “Spectra” that have been scattered across all the gardens of Eden. Swing and jump between plants and rock formations, collect pollen to seed new plants and explore the incredible gardens to locate the precious “Spectra.” Lush visuals, slick controls and amazing music make it an incredibly atmospheric and addictive experience. Download the full game today and prepare to enter Eden! Key Features: • Stunning Visuals - Stylish graphics brought to life in gorgeous 1080p HD. • Multiplayer Co-op - Local co-op play for up to three players. • Trophy and Online Support - Unlock Trophies and track high scores via online leaderboards. • Video Recording - Record gameplay videos to the hard drive or upload directly to YouTube. • Remote Play - Supports Remote Play for PSP system*.' FROM games WHERE igdb_id = 10700 ON CONFLICT (game_id, language_code) DO NOTHING;
