INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TrackMania Nations Forever', 'TrackMania Nations Forever offers a new "Forever" version of the Stadium environment, a solid solo mode and 65 brand new, progressively challenging tracks. TrackMania Nations Forever will unite an even larger number of players than the original Nations thanks to its engaging multiplayer modes, innovative online functions and revolutionary interactivity between players.' FROM games WHERE igdb_id = 15773 ON CONFLICT (game_id, language_code) DO NOTHING;
