INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My World, My Way', 'The game puts the player into the role of Princess Elise, a young, spoiled princess on a quest to impress a handsome adventurer into being her boyfriend. Princess Elise has a unique ability to pout, changing the game''s landscape or enemy behavior. This ability can be used to force enemies to drop more loot, make the game easier or even complete sidequests.' FROM games WHERE igdb_id = 21253 ON CONFLICT (game_id, language_code) DO NOTHING;
