INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destroy All Humans! Path of the Furon', 'In Destroy All Humans! Path of the Furon, players will pick up where prequel Destroy All Humans! Big Willy Unleashed leaves off, controlling Crypto in the Funked Out 1970s when a mysterious new enemy attacks, launching a conspiracy that unravels Crypto''s groovy new way of life and threatens the very survival of his Furon race. Developed by THQ''s newly formed internal development studio Sandblast Games, Destroy All Humans! Path of the Furon takes players on a journey of Enlightenment and Destruction to help Crypto gain new powers from an alien Kung Fu Master in order to take on his most difficult enemy yet.' FROM games WHERE igdb_id = 2717 ON CONFLICT (game_id, language_code) DO NOTHING;
