INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rtl-biathlon-2009', 94853, '2008-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gim.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8knz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RTL Biathlon 2009', 'RTL Biathlon 2009 is a simulation of the Biathlon sport. Like the real sport it is basically divided into two sections: skiing and shooting. During the skiing sections the player steers his athlete into the correct direction and watches his stamina. In the middle of the screen is a power bar which gets filled by holding the assigned button - if the bar is too low the athlete gets slow and if it is too high he gets tired. Practically this results in steady button pressing to keep it as high as possible. During the shooting sequences the player shoots on targets while the cursor is wobbling. He can also hold his breath for a short time to steady his aim. In the career mode the player divides points into four categories, e.g. speed or stamina, which influence the athlethe''s capabilities. After successful championships he can improve these stats further. New in this instalment are super-powers which can be chosen at some point. When activated these give a big boost on a stat for a short time, e.g. "mountain skiing" boosts power when skiing uphill. These are available once per race. There are overall 15 courses which are partly licensed.' FROM games WHERE igdb_id = 94853 ON CONFLICT (game_id, language_code) DO NOTHING;
