INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: Undercover', 'The Need for Speed series got another dose of Hollywood magic with the release of Undercover. Take on jobs and compete in races to prove yourself as you infiltrate and take down an international crime syndicate. As you win each race, you’ll go deeper into the underworld web that rules Tri-City… and then tear it apart right under their noses. You make the calls, but don’t break your cover: inside the car or out of it, one mistake here could be your last.' FROM games WHERE igdb_id = 101 ON CONFLICT (game_id, language_code) DO NOTHING;
