INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uno', 'Everybody knows Uno - the classic card game of matching colors and numbers that''s #1 for family fun. Customize the game with your own house rules and penalties, throw down Action Cards like Skip and Reverse in furiously thrilling games! Get rid of your hand before everyone else, but don''t forget to shout "Uno!" when you''re down to one card!' FROM games WHERE igdb_id = 81358 ON CONFLICT (game_id, language_code) DO NOTHING;
