INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Villagers 3: The Secret City', 'Embark on a journey with a group of villagers in search of a new part of the island to populate. Land on the hidden shores of the northern side of Isola and explore what was once a secret city. Find new sources of food to nourish your villagers and help them rebuild the remains of this mysterious city. Who lived here before? Where have they gone? What is the secret of Isola?' FROM games WHERE igdb_id = 14910 ON CONFLICT (game_id, language_code) DO NOTHING;
