INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warriors Orochi 2', 'Warriors Orochi 2 is a 2008 video game developed by Koei (now Tecmo Koei) and Omega Force for the PlayStation 2. It is the sequel to Warriors Orochi, a crossover video game of the Dynasty Warriors and Samurai Warriors series. The game was released on September 23 in North America and September 19 in Europe. A version for the Xbox 360 was released on September 4, 2008 in Japan, and alongside the PS2 releases in North America and Europe. A PlayStation Portable version has been released in Japan, North America and Europe.' FROM games WHERE igdb_id = 7243 ON CONFLICT (game_id, language_code) DO NOTHING;
