INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tales-of-vesperia', 1209, '2008-08-07', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5gb4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/v2v1sbysnft2l0wrype0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Vesperia', 'Set in a world reliant on a mysterious ancient technology known as "blastia," the game follows former knight Yuri as he delves into a shadowy plot to use these magical devices to control civilization, or destroy it. A bold new interpretation of the elements that made the Tales series a hit with gamers around the world, Tales of Vesperia promises a standard-setting RPG experience on the Xbox 360. Using an all-new graphics engine and character designs by the renowned Kosuke Fujishima (Ah! My Goddess, Sakura Taisen), the game delivers high-quality HD character models and environments that are indistinguishable from traditional cel-based anime.' FROM games WHERE igdb_id = 1209 ON CONFLICT (game_id, language_code) DO NOTHING;
