INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('penny-arcade-adventures-on-the-rain-slick-precipice-of-darkness-episode-one', 14979, '2008-05-21', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ini.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qgusqawwtbnkli88t6fa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penny Arcade Adventures: On the Rain-Slick Precipice of Darkness - Episode One', 'On the Rain-Slick Precipice of Darkness, Episode One is the first installment in the RPG-Adventure game series based on the web comic Penny Arcade. Create your character in the classic comic style, and join Gabe and Tycho in the alternate 1920s universe of New Arcadia, where you''ll combat savage enemies, solve mysteries, meet bizarre new characters, and discover their unique sense of humor for a 100% authentic Penny Arcade experience! - Create-a-Player System lets you design and develop your own character, seeing it come to life in 3D and in the comic-style 2D cut scenes - Dynamic turn-based combat system, over-the-top animations, and team-up moves during enemy battles - Classic adventure game play combines with RPG elements to unravel the game''s mysteries and puzzles - Authentic Penny Arcade story and dialogue written exclusively by Jerry ''Tycho'' Holkins - Includes Gabe, Tycho, Annarchy, the Fruit F*cker and many other favorite Penny Arcade characters, plus new characters designed by Mike ''Gabe'' Krahulik' FROM games WHERE igdb_id = 14979 ON CONFLICT (game_id, language_code) DO NOTHING;
