INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4 Elements', 'The ancient kingdom is in trouble! The magic of the four elements that kept it running for centuries has been corrupted by evil powers and the altars no longer yield the energy of life. It is up to you to unlock the 4 ancient books of magic and collect 16 mysterious cards that will help you restore the kingdom to life. An adorable little fairy will be your aide in this perilous journey as you encounter elementals, dragons, knights, and various magic creatures.' FROM games WHERE igdb_id = 27893 ON CONFLICT (game_id, language_code) DO NOTHING;
