INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil: Degeneration', 'Resident Evil: Degeneration is a survival horror game based on the movie of the same name. It was released for the Nokia N-Gage 2.0 service in 2008, and later in 2009 released remastered port to iPhone & iPod Touch. Additionally in 2008 there was released two different versions with same name for other mobile devices, games is completely different from original game and it was reworked versions of "Resident Evil: Missions" and "Resident Evil: Missions 3D".' FROM games WHERE igdb_id = 25817 ON CONFLICT (game_id, language_code) DO NOTHING;
