INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Days of Memories: Sekai de Ichiban Atsui Fuyu', 'Released in December 1, 2008. This game is very similar to the first Season 365 no Omoi and concludes the previous two titles and is staged at a place similar to the last two entries. The protagonist is a third year kendo student who is energetic and reckless. He has to decide who he wants to spend his Christmas party with this year. The title parodies a popular Japanese phrase and TBS drama, One Hot Summer. The girls are Athena Asamiya, Mai Shiranui, Hibiki Takane, Hotaru Futaba, Rose Bernstein, Reina Takida, and Nintendo DS-only Athena Hatsushiro.' FROM games WHERE igdb_id = 221320 ON CONFLICT (game_id, language_code) DO NOTHING;
