INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Athletics', 'International Athletics and features incredibly intuitive controls adapted specifically for iPhone and iTouch. The game includes 11 of the worlds most compelling Track and Field events, set within full 3D international stadiums! Nows your chance to grab hold of this PSP chart hit in time for 2012!' FROM games WHERE igdb_id = 20321 ON CONFLICT (game_id, language_code) DO NOTHING;
