INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mushroom Age', 'Mushroom Age is a hidden object game with adventure elements. The player has to search the screen for items hidden in the scenery, that are described or displayed as silhouettes at the top and click on them. These items are then collected and removed from the screen, and some of them are stored in the inventory to be combined or used in puzzles and situations.' FROM games WHERE igdb_id = 87324 ON CONFLICT (game_id, language_code) DO NOTHING;
