INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Paradise', 'Animal Paradise takes place on a virtual farm where players are tasked with becoming best friends with all the animals throughout the game. Kids are introduced to new furry friends to care for and will unlock fun-packed mini-games such as Treasure Hunting, Footprint Trail and Shampoo Scrub. Once tikes have gained the animal''s trust, they can unlock cute, fun, and exclusive pet pictures to add to their virtual photo album.' FROM games WHERE igdb_id = 24326 ON CONFLICT (game_id, language_code) DO NOTHING;
