INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortimer Beckett and the Secrets of Spooky Manor', 'Come along with Mortimer on a ghostly seek-and-find adventure! Hunt the halls of the Beckett family mansion in search of mysterious hidden objects and solve a series of brain-bending puzzles to uncover the Spooky Manor mystery. What is this strange machine? Who shattered it into pieces? And what happened to Uncle Jerome? Only those with a keen eye for details will discover the answers hidden in Spooky Manor!' FROM games WHERE igdb_id = 8326 ON CONFLICT (game_id, language_code) DO NOTHING;
