INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('death-to-spies-moment-of-truth', 9377, '2008-03-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2oy1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar16s1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death to Spies: Moment of Truth', 'Moment of Truth is a sequel to the popular stealth action title Death to Spies. The game''s main character is Semion Strogov, a captain in the 4th department of the Soviet counterintelligence service called SMERSH. SMERSH literally means in Russian, Death to Spies, which was the name for a set of counterintelligence departments in the Soviet Army formed during World War II. Strogov is back from his previous missions and must now participate in a series of even more complicated and exciting military operations under the code name "Death to Spies: Moment of Truth". The hero possesses all the skills required to accomplish especially dangerous missions including, getting information about the disposition of hostile military and civil units, assassination of enemy agents and representatives of Wehrmacht’s high-ranking officers and espionage. By the order of his supreme commander Strogov, who passed through a serious retraining, will have to accomplish various top secret missions. His task is to capture spies, saboteurs and gather information about their actions using unique technologies and devices.' FROM games WHERE igdb_id = 9377 ON CONFLICT (game_id, language_code) DO NOTHING;
