INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Special Mission', 'The Special Mission is a flash game that was made available on the Japanese Metroid Prime 3: Corruption website in promotion of the game. The home page of the website is navigated through a first-person perspective similar to that in the game, with the mouse being used to control Samus Aran similar to the in-game Wii Remote motion controls. Clicking the left button of the mouse causes Samus to shoot. The purpose of the Special Mission is to collect fifteen Bonus Credits (five each in Red, Yellow and Blue) hidden around the website, which reveal access codes that unlock desktop wallpapers.' FROM games WHERE igdb_id = 360512 ON CONFLICT (game_id, language_code) DO NOTHING;
