INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bully: Scholarship Edition', 'Bully: Scholarship Edition is an action-adventure game developed by Rockstar Games, set in the fictional boarding school of Bullworth Academy. Players assume the role of teenager Jimmy Hopkins as he navigates the school''s social hierarchy, completing various missions and attending classes that serve as mini-games. The game features an open-world environment allowing free exploration, interactions with other students and faculty, and a dynamic day-night cycle. Enhanced from its original release, the Scholarship Edition includes additional missions, classes, characters, and unlockable items, providing an expanded and enriched gameplay experience.' FROM games WHERE igdb_id = 6574 ON CONFLICT (game_id, language_code) DO NOTHING;
