INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('trackmania-united-forever', 2451, '2008-04-15', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6kbb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lz69wv7nvzjmupok2myx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TrackMania United Forever', 'TrackMania is the most entertaining car racing game ever. Millions of players play it in single or multiplayer modes. TrackMania United Forever is the ultimate TrackMania edition thanks to the numerous additions and innovations it has to offer. This version brings together all the environments of the series and comes with a huge, enriched single-player campaign including 4 different modes and 420 progressively difficult tracks. Drive at mind-blowing speed on today''s most spectacular tracks. Soaring jumps, loops, hairpin bends, turbo boosts, track-breakers, rails and ramps...every track delivers a new and intense experience, offering sensational gaming across single and multiplayer modes.' FROM games WHERE igdb_id = 2451 ON CONFLICT (game_id, language_code) DO NOTHING;
