INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hajime-no-ippo-the-fighting-ds', 70566, '2008-12-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kgy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3sy6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hajime no Ippo: The Fighting! DS', 'The top selling boxing manga Hajime no Ippo illustrates the growth of the pushover Makunouchi Ippo. Through the sport, the boy matured both in spirit and in body. By meeting other boxers in the ring, he found both his way in life and purpose. Now you don''t have to be a passive spectator, step into the ring in the Challenge Mode with Ippo and experience the eye opening matches he went through. Besides the matches in the series, you can arrange games with your friends through the wi-fi facility of the DS. There is an abundance of minigames that will affect your player character''s attributes such as reflexes and attack power, be sure to try them all out and max your stats before the great game. Pick a fight with anyone in the roster in the Free Match Mode, you can expand the roster by defeating more and more opponents in the Challenge Mode. Try out in boxing and see if you can find your way through life via the sport.' FROM games WHERE igdb_id = 70566 ON CONFLICT (game_id, language_code) DO NOTHING;
