INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Void', 'A first-person game in which after starving to death, the player wakes up in the Void, a dying land housing numerous Sisters and long-absent Brothers, all of whom subsist on Color, the essence of life in the Void. With the player''s arrival, a resurgence of Color is observed in the Void, prompting the Brothers to return and subject the player to various trials so that he may also become a Brother by using and sharing Color.' FROM games WHERE igdb_id = 3273 ON CONFLICT (game_id, language_code) DO NOTHING;
