INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: The Clone Wars - Jedi Alliance', 'Star Wars: The Clone Wars - Jedi Alliance is an action/adventure game developed and published by LucasArts. It was released for the Nintendo DS entertainment system on November 11, 2008. It is set in the science fiction universe of Star Wars and is a tie-in to The Clone Wars TV series.' FROM games WHERE igdb_id = 21335 ON CONFLICT (game_id, language_code) DO NOTHING;
