INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Star Force 3: Red Joker', 'The world is in peril from a mysterious "noise" that is affecting the EM digital world. Through his bond with the alien Omega, Geo must transform into the legendary Mega Man to uncover the mystery behind the noise and protect the Earth. Can he master the new Mega Man transformations of Black Ace and Red Joker before it''s too late?' FROM games WHERE igdb_id = 1787 ON CONFLICT (game_id, language_code) DO NOTHING;
