INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dracula: Origin', 'Dracula: Origin reveals the dark origins of the Dracula curse. Once the ardent defender of Christendom, Dracula loses his faith in God when he is abandoned by his one true love after she marries. Dracula then makes a pact with the Prince of Darkness, and becomes a vampire.' FROM games WHERE igdb_id = 5442 ON CONFLICT (game_id, language_code) DO NOTHING;
