INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy: Crystal Chronicles - My Life as a King', 'Final Fantasy Crystal Chronicles: My Life as a King is a video game developed for the WiiWare service of the Wii console. Square Enix decided to make a game for the service that would be high profile, and it was decided that the game would be a simulation game and, later in development, a Final Fantasy title. The game is a city-building game set in the world of the action RPG Final Fantasy Crystal Chronicles and is the third title in the Final Fantasy Crystal Chronicles series. Following the events of the first Crystal Chronicles game, the son of a king who lost his kingdom during that game establishes a new one and sets about creating a peaceful and prosperous land.' FROM games WHERE igdb_id = 21054 ON CONFLICT (game_id, language_code) DO NOTHING;
