INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Fighter IV', 'Street Fighter IV brings the legendary fighting series back to its roots by taking the beloved fighting moves and techniques of the original Street Fighter II, and infusing them with Capcom’s latest advancements in next generation technology to create a truly extraordinary experience that will re-introduce the world to the time-honored art of virtual martial arts. Newcomers: - Abel - C.Viper - Rufus - El Fuerte - Gouken' FROM games WHERE igdb_id = 884 ON CONFLICT (game_id, language_code) DO NOTHING;
