INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret Files 2: Puritas Cordis', 'While her ex-boyfriend Max, a scientist, witnesses the brutal methods of Puritas Cordis at the excavation site of an ancient Indonesian temple complex, Nina joins forces with a priest in France to investigate the connection between the secret society''s sinister prophesies and the creepy leader of an ancient order. A dramatic race against time begins. Will the protagonists be able to avert the impending apocalypse?' FROM games WHERE igdb_id = 5146 ON CONFLICT (game_id, language_code) DO NOTHING;
