INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sniper-art-of-victory', 16948, '2008-06-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co221d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aril4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sniper: Art of Victory', 'WW II was a theatre of war for many specialized combat units, working together to ensure an army’s victory. Among them a unique role was played by hidden and deadly marksmen. Their ability to lay motionless waiting for the perfect shot together with their professional equipment allowed them to change the course of the history with one pull of a trigger. Become a sharpshooter and take part in the turning points of the WW II. Eliminate the Nazi general, who came to support the Germans lying siege to Stalingrad. Make your way through areas occupied by the Third Reich to your unit. Aid the Alliance forces during their offensive on the Italian Peninsula to break the resistance of the retreating Wehrmacht forces.' FROM games WHERE igdb_id = 16948 ON CONFLICT (game_id, language_code) DO NOTHING;
