INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reaxxion', 'Celebrating 30 years of breakout games, action-packed Reaxxion is the next generation, letting gamers wield the power to manipulate liquid metal to destroy targets! Like no breakout game before it, Reaxxion is a unique entertainment experience that will capture your imagination and excite your senses. Generate and absorb balls into the liquid metal paddle, or transform balls into golden, brick-busting dynamos in the "Reaxxion Chamber." With nine smashing power-ups and secret challenge levels, this electrifying game features the ultimate in variety and player-controlled action.' FROM games WHERE igdb_id = 9413 ON CONFLICT (game_id, language_code) DO NOTHING;
