INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Between', 'Between is a disjunct cooperative multiplayer game that takes place in an abstract, side-scrolling world where a character can be controlled. In the distance, a shimmering image of a tower is shown. It consists of blocks, each with a different squared pattern of colors. The aim of the game is to build the tower according to the pattern, but it is impossible to complete it without the help of the other player who has the same goal, but who is not visible on the player''s screen.' FROM games WHERE igdb_id = 95369 ON CONFLICT (game_id, language_code) DO NOTHING;
