INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sainth', 'Years after the events of "Wraith", a young girl named Lily, has a chance encounter with someone familiar. Following that, she soon finds herself stranded in a strange place with nary a soul in sight. As she struggles to gain her bearings, a voice echoes inside her head. It is the World Tree, telling her to seek out her memories from long ago... Sainth is a free RPG Maker game developed by Neo Kuriyo. It is the sequel to Wraith.' FROM games WHERE igdb_id = 126003 ON CONFLICT (game_id, language_code) DO NOTHING;
