INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hannah Montana: DVD Game', 'Have you always wanted to be the star of the show? Now you can! Get ready to rock with Hannah! All you need is your DVD and a remote control! Play on your own, or with friends and family in Party Play Mode! Rock out to the best hits of Hannah Montana! Join Hannah in a dance off with your friends! Drive the crowd wild as you test your drumming abilities! Hours of fun that you''ll love playing again and again! So grab that remote right now -- it''s your time to shine! The party starts here with 11 action-packed games you can play again and again.' FROM games WHERE igdb_id = 228444 ON CONFLICT (game_id, language_code) DO NOTHING;
