INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Naked Brothers Band: The Video Game', 'The Naked Brothers Band: The Videogame is an interactive music experience based on the highly successful Nickelodeon series. Band Manager Cooper has secured a nationwide tour for the Naked Brothers Band. The journey to success, however, is not going to be easy. Players will experience the real superstar life of the Naked Brothers Band on tour while playing instruments and singing along to 25 of their favorite Naked Brothers Band songs.' FROM games WHERE igdb_id = 47955 ON CONFLICT (game_id, language_code) DO NOTHING;
