INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo DVD Game: Funland of Freaky Frights', 'Scooby-Doo needs viewers'' help to solve a spooky mystery in this interactive program. Is Funland amusement park really haunted--or is some masked mastermind really pulling the strings? With remote control in hand, viewers become honorary members of Mystery Incorporated, helping the gang through a series of fun challenges to discover the truth. Up to four player can play this game.' FROM games WHERE igdb_id = 231471 ON CONFLICT (game_id, language_code) DO NOTHING;
