INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Masters, Inc.', 'Dive beneath the waves on a hidden object quest to recover an amazing historical artifact in Treasure Masters Inc. Solve dozens of brain-teasing puzzles, enjoy relaxing mini-games, and try to get to the hidden treasure first. Do you have a keen eye for detail and the wits to outsmart your enemies? If so, Treasure Masters Inc wants you on board!' FROM games WHERE igdb_id = 24771 ON CONFLICT (game_id, language_code) DO NOTHING;
