INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jam with the Band', 'Jam with the Band is a music video game developed and published by Nintendo for the Nintendo DS handheld game console. It is the sequel to the Japan-exclusive Daigasso! Band Brothers, which was released at the DS'' launch. Its release was accompanied by a Wii Channel for the Wii console called the Live Channel, known in Japan as the Speaker Channel, that allows players to hear the game''s sound through their television. It features the character Barbara Bat, who was also in the predecessor.' FROM games WHERE igdb_id = 21100 ON CONFLICT (game_id, language_code) DO NOTHING;
