INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psychosomnium', 'Psychosomnium is an experiment in illogical puzzles or dream world logic. You''ll play the game trying to figure out how to reach an obscure goal. You''ll have to do many strange things to reach this goal, like going in directions you wouldn''t expect to be able or even putting yourself in unreasonable, and perhaps deadly, peril.' FROM games WHERE igdb_id = 84249 ON CONFLICT (game_id, language_code) DO NOTHING;
