INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Hunters', 'Dragon Hunters is a fun platform action game, based on the stunning world featured in the successful Dragon Hunters TV series and the animated movie coming spring 2008. Dragon Hunters combines platform gameplay with many challenging puzzle and action elements. Use the 3 characters of the game according to their individual abilities, and make your way through a detailed fantasy world consisting of landmasses and planetoids floating mid-air.' FROM games WHERE igdb_id = 269734 ON CONFLICT (game_id, language_code) DO NOTHING;
