INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1000 Bornes: Coups-Fourres et Courses Folles!', 'Discover the famous card game 1000 Bornes on DS updated with some new features. The title features a "classic" mode with the same rules as the original but also a "special" mode with delightful mini-games to counter your opponent''s attacks using the stylus and microphone. A single cartridge holds up to six players.' FROM games WHERE igdb_id = 268069 ON CONFLICT (game_id, language_code) DO NOTHING;
