INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rainbow-web-2', 54309, '2008-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6nxq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scn60q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbow Web 2', 'Released in 2008 by Sugar Games and GameTop. Rainbow Web II is a matching game where three or more same-color gems have to be aligned in a spider web, horizontally or vertically, to make them disappear. Some of the jewels have letters, and the main goal of each level is to spell a phrase at the top-left of the screen by matching these gems. Black pearls can only be removed when they reach the web edge or center. There are two mini-games that appear between levels: a hunt for hidden pieces of an object in a scenery, and a sliding-tile puzzle.' FROM games WHERE igdb_id = 54309 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 54309 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
