INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Immortals of Terra: A Perry Rhodan Adventure', 'The Immortals of Terra is an epic space adventure set in 1346 New Galactic Era, 4934 AD, starring Perry Rhodan. This breathtaking story takes the player from the very top of a majestic floating palace, through the midst of intergalactic intrigue, to deep below the surface of incredible alien worlds. The goal is to unravel the mystery of the disappearance of Perry''s beloved, Mondra Diamond, but soon the plot thickens and the stakes get higher.' FROM games WHERE igdb_id = 9108 ON CONFLICT (game_id, language_code) DO NOTHING;
