INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heavy Armor Brigade', 'Step into the drivers seat as you journey through the battlefields of World War II with your Heavy Armor Brigade. Make quick decisions during the heat of battle and devise strategies to come out on top as you play cat and mouse with the enemy’s tank forces.' FROM games WHERE igdb_id = 47881 ON CONFLICT (game_id, language_code) DO NOTHING;
