INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ColourPod 2: DimensionPod', 'You are the last dimensionPod. Your dimensions have been driven to Darkness. Collect colour fragments on your colour Lens to accumulate abilities used to destroy colourless fragments. Warp to defeat fragments in both dimensions. Complete missions to unlock hints that will help you master dimensionPod. Try to restore pixels to your world!' FROM games WHERE igdb_id = 263381 ON CONFLICT (game_id, language_code) DO NOTHING;
