INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 3 Illust Puzzle', 'Persona 3 Illust Puzzle is a nonogram-style puzzle game. Like traditional nonograms, cells in a grid must be filled in in order to correctly reveal the image. The puzzles in this game are primarily tied to the Arcana motif of the Persona series with a total of forty puzzles, in color and monochrome difficulty levels. By completing puzzles, players fill out the game''s gallery.' FROM games WHERE igdb_id = 289391 ON CONFLICT (game_id, language_code) DO NOTHING;
