INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zenses: Rainforest', 'Zenses Rainforest allows players to explore the Amazon while playing games infused with rain drops, exotic flowers, waterfalls and giant trees. This refreshing experience encourages players to recharge their batteries while playing puzzle games such as Sapphire Wheel, Mirror Maze, Stack Jack and Bumble Breaker (names are currently being reviewed and may change).' FROM games WHERE igdb_id = 21295 ON CONFLICT (game_id, language_code) DO NOTHING;
