INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die2Nite', 'Browser-based game where you play a survivor in a town of 40 players, where you will have to work together to survive the longest possible against the relentless waves of zombies attacking every night.  You have a pool of action points each day, that you can spend to improve the town, gather resources, explore the surroundings etc. Teamwork is the key to build the vital improvements the town will need to survive.  Rogue-like elements allow you to unlock perks that you will be able to use in your following games.' FROM games WHERE igdb_id = 126127 ON CONFLICT (game_id, language_code) DO NOTHING;
