INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exploit', 'Exploit is a strategic pseudohacking game about a US hacker. One day, he receives a message from his friend sk3tch who tells him about the island Locha, a dictatorship in the middle of the ocean that filters internet access through a firewall, a government-mandated censor designed to curtail any political dissent. Sk3tch urges the hacker to use his skills for good and compromise it to bring some freedom to the country.' FROM games WHERE igdb_id = 173424 ON CONFLICT (game_id, language_code) DO NOTHING;
