INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Echochrome', 'Echochrome is a puzzle game created by Sony''s Japan Studio and Game Yarouze. Gameplay involves a mannequin figure traversing a rotatable world where physics and reality depend on perspective. The world is occupied by Oscar Reutersvärd''s impossible constructions. This concept is inspired by M. C. Escher''s artwork, such as "Relativity". The game is based on the Object Locative Environment Coordinate System developed by Jun Fujiki—an engine that determines what is occurring based on the camera''s perspective.' FROM games WHERE igdb_id = 18050 ON CONFLICT (game_id, language_code) DO NOTHING;
