INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Boyfriend', 'My Boyfriend is a virtual life simulation game for the Nintendo DS where the player chooses a boyfriend, and pursues them through various activities and mini-games. The game includes story-driven missions, outfit collection, and exploration of locations such as a residential area, park, school, football pitch, skate park, and shopping center.' FROM games WHERE igdb_id = 94828 ON CONFLICT (game_id, language_code) DO NOTHING;
