INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Feudalism II', 'The age of Feudalism continues! Once again you start a long journey as a weak chieftain with the goal of becoming the most powerful warrior and ruler of the whole world. The world is bigger now, there''re 6 different nations,12 heroes, lots of weapons, armor and much more ways to vanquish enemies. Recruit soldiers, buy and upgrade equipment, conquer cities and challendge great heroes to make yourself the king of kings!' FROM games WHERE igdb_id = 234915 ON CONFLICT (game_id, language_code) DO NOTHING;
