INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz!: The Pop Quiz', 'Buzz!: The Pop Quiz is a music trivia game show that supports up to eight players using specialized Buzz! Buzzers controllers. Players compete through eight rounds of questions about 90s and 2000s pop music, featuring traditional trivia, picture identification, and video clips. The game includes animated characters who dance to music during gameplay, and offers customizable quiz formats alongside a single-player mode.' FROM games WHERE igdb_id = 21360 ON CONFLICT (game_id, language_code) DO NOTHING;
