INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop', 'The single game gives players the chance to burst their way through waves of bubbles whilst grabbing power-ups (e.g. slow down the speed), multipliers, chains and aiming for worldwide high-scores. In multiplayer mode, Pop allows people to steal points from opponents and use the controller to pump up the bubbles for bigger explosions. Other power-ups darken the screen save for the player''s area or immobilize the cursor by striking it with lightning. It can also be played cooperatively.' FROM games WHERE igdb_id = 21828 ON CONFLICT (game_id, language_code) DO NOTHING;
