INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resistance 2: Collector''s Edition', 'It''s 1953. The Chimera have invaded America. Entire U.S. states lie in smoking ruins. Chicago and San Francisco are overrun. Mankind''s fate once again rests in the hands of Army Lt. Nathan Hale – an infected soldier who is becoming the enemy he despises. Resistance 2 Collector’s Edition includes: - Exclusive 5 ½" Chimera Hybrid action figure with Bullseye weapon. - Double-sided Resistance art book covering a war-torn America from two unique perspectives. - Bonus DVD including: Behind The Scenes video, Exclusive video commentary by Insomniac Games, "Twisted History" chronology video, Sneak peek at the upcoming Resistance novel, "Resistance: The Gathering Storm", Exclusive in-game HVAP Wraith multiplayer skin and more. -Resistance 2 video game' FROM games WHERE igdb_id = 43041 ON CONFLICT (game_id, language_code) DO NOTHING;
