INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mobile-suit-gundam-gihrens-greed-the-fear-of-axis', 56745, '2008-02-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ysp.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam Gihren''s Greed: The fear of Axis', 'Become the commander of great armies and lead your men off to war. Your main responsibility is to emerge victorious through the battle. Plan your strategies and learn about the chronology of Gundam battles. Before the great war could happen, you have to collect information on your enemies through spies, develop and produce weapons as well as other important tools.Based loosely on the Gundam series'' stroryline, you can recreate numerous scenarios with the characters, rescue your favourite character from certain death, put newly invented weapons to use and all in all, create your own history.' FROM games WHERE igdb_id = 56745 ON CONFLICT (game_id, language_code) DO NOTHING;
