INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hockey Allstar Shootout', 'Use the Wii Remote™ controller as a stick and take the shot as you compete in three exciting Hockey Skills Challenges. In Head 2 Head, it’s just you versus the best goalies in the world in a five-puck shootout. Race against the clock to post the most goals in the fastest time. The three difficulty levels will place you against three increasingly talented goalies, each donning the jersey of their home country.' FROM games WHERE igdb_id = 85182 ON CONFLICT (game_id, language_code) DO NOTHING;
