INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Experiment', 'Over sweeping cliffs and across scenic coastlines, this innovative shared adventure begins in the bowels of an old, dilapidated ship grounded ashore. Mysteriously, you find yourself in the ship''s operations room faced with a highly advanced panel of controls, surveillance monitors, and a wide array of sophisticated technology. As you scan the monitors frantically searching for answers to what this place is and why you are there, the only signs of life you have come across are a series of strange, curiously hard to identify animals, but then you see her; a woman.' FROM games WHERE igdb_id = 21489 ON CONFLICT (game_id, language_code) DO NOTHING;
