INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stronghold: Crusader Extreme', 'Stronghold: Crusader Extreme is an updated version of 2001''s Stronghold expansion, Stronghold: Crusader by Firefly Studios. Crusader Extreme is set in the Middle East during the Crusades era. Stronghold Crusader Extreme has additions of larger armies of 10,000 men, new buildings and missions. It also contains an updated version of the original Stronghold Crusader, which includes everything except for outposts, the god powers and the Extreme Crusader Trail. However if the official HD patch is installed, outposts can be built on maps on the original Stronghold Crusader part of Stronghold Crusader Extreme.' FROM games WHERE igdb_id = 9462 ON CONFLICT (game_id, language_code) DO NOTHING;
