INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpectrumTap', 'Gems change colors rapidly. Try your color perception and tap groups of same-colored gems before time runs out! SpectrumTap features many levels of increasing difficulty and high score functionality.' FROM games WHERE igdb_id = 41501 ON CONFLICT (game_id, language_code) DO NOTHING;
