INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rubik-s-puzzle-world', 5131, '2008-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ljde0lmbmtxaqng32e6u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsox9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rubik''s Puzzle World', 'Step inside the mysterious “27th part” of the Rubik''s cube - and discover a world of Rubik''s themed puzzles to tease and challenge the whole family. Welcome to Rubik''s World - an abstract environment populated by “Cubies” which make up the game''s DNA. Rubik''s World takes the shape, functionality and concept behind the famous Rubik''s Cube but twists and turns the rules to transform it into a unique Puzzle filled game experience for players of all ages. Get ready for a collection of games infused with the mental challenges which made the original Rubik''s Cube such a hit! The construction of the games will challenge your brain, enable you to solve increasingly difficult puzzles, and develop your logical capabilities – while having lots of fun! So take a trip inside the Rubik''s Cube and enter an abstract world of Rubik''s themed puzzles - each as addictive as the original cube we know and love! Features • Play 8 unique games which mix puzzles, quizzes, music and sound activities – as well as the classic cube solving game! • Multiplayer games allowing you to share the fun with family and friends. Compare your stats and progress, share environments, music compositions and more! • Each game requires forward thinking and involves complex mechanics but a simple interface – all based on the idea that every reaction can have multiple reactions • Expand your Rubik’s universe. The better you play, the more cubies come to life, unlocking new challenges and activities • Compose your own music. Hear your music being played by cubies in different places of the game! • See and hear your very own creations in the Rubik''s universe.' FROM games WHERE igdb_id = 5131 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 5131 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
