INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('animatch-animal-matching-game', 86874, '2008-10-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rpnzxsvey1kpcgo2zo1m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qsprcddhoho46oqmwaxx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AniMatch: Animal Matching Game', 'AniMatch is great FUN for kids and adults alike!  "This is a MUST HAVE APP for anyone with an iPhone and YOUNG KIDS... The buttons are BIG and very easy to navigate, the animal sounds are wonderful and the ''little jiggle'' the animals do when you succeed at a match had my kids very excited." - Customer Review (US) "Excellent! (*****) - My 6 year old is always grabbing my iPod to play this... I have to admit I have found myself opening this app and enjoying it myself. A+" - Customer Review (US) "Kid Perfect (*****) - Lost my Touch to my 3yo over this game" - Customer Review (US) "Animatch is FANTASTIC!!! (*****) - ... a must have app the HOLDS THEIR ATTENTION and develops memorization skills. My 2 1/2 year-old toddler love this one. She can play alone, or we take turns and make it a fun game together. Excellent for distracting them while you finish your dinner and wine at a restaurant!!" - Customer Review (US) "Very Addictive even for adults! (*****) - I can''t stop playing this game since installing it. Love the graphics and animal sounds" - Customer Review (US) *************************************************** Now with retina display graphics and native iPad support! AniMatch has reached the #1 Top Paid Kids'' app spot in the USA, France, and Germany, and has been a top selling Kids'' Game for over two years! ***** AniMatch was mentioned in the NEW YORK TIMES Travel Section as a great game to have on trips for restless kids! and was featured by Apple in "BEST KIDS'' GAMES" *****
