INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear Solid 4: Guns of the Patriots - Limited Edition', 'Metal Gear Solid 4: Guns of the Patriots is a story-driven adventure game, with seasoned hero Solid Snake drafted for one final mission. Set across stages including the Middle East and South America, the now aged Snake has been asked to assassinate his old adversary, Liquid Ocelot. The Limited Edition (available exclusively at certain retailers) includes a collectible metal case, Blu-Ray video containing "making of" documentaries, an extensive interview with Metal Gear Solid creator Hideo Kojima and Metal Gear Solid 4: Guns of the Patriots Original Soundtrack CD.' FROM games WHERE igdb_id = 45177 ON CONFLICT (game_id, language_code) DO NOTHING;
