INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winter Sports 2: The Next Challenge', 'Winter Sports 2: The Next Challenge is an arcade oriented 3D simulation of only the most popular winter sports. The player is placed at the center of high level sporting events broadcast live around the world. The excitement of this major international competition is portrayed authentically with commentators, TV cameras and immersive environments. 9 Sports with 15 different disciplines New Snowboard half-pipe contest Campaign with 42 extra challenges across all disciplines Multiplayer party fun: ''Hot Seat'' (4 players) and Split Screen (2 players) Supports the Wii Balance BoardTM' FROM games WHERE igdb_id = 5285 ON CONFLICT (game_id, language_code) DO NOTHING;
