INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PictoImage', 'PictoImage is a pick up and play puzzle game in which players to take turns drawing the image of a word, while competitors race against the clock to guess the word first. The words are generated at random and can be anything from an apple, to a waterfall or a butler! Even if art is not your best subject, the three playable modes means there really is something for everyone and it can actually help you learn to draw!' FROM games WHERE igdb_id = 84824 ON CONFLICT (game_id, language_code) DO NOTHING;
