INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectrobes: Beyond the Portals', 'Spectrobes: Beyond The Portals is the sequel to popular anime-inspired, sci-fi action/role playing game series Spectrobes, for Nintendo DS. Spectrobes: Beyond The Portals continues the story of Rallen and Jeena, interplanetary patrol officers who discover, excavate, awaken and train mysterious fossilized creatures known as spectrobes and then use them to battle enemies. The story revolves around the origins of ominous portals that lead to distant dimensions and a new nemesis who hopes to destroy the spectrobes.' FROM games WHERE igdb_id = 5175 ON CONFLICT (game_id, language_code) DO NOTHING;
