INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DUI', 'DUI is a world full of blocks. To pass the level, you should remove required amount of blocks and get the left blocks stay inactive(NOT ON GRAY BLOCK). Furthermore, we strongly recommend that you get your hands wet with the level editor through which you can create your own blocks world and then share the levels you made with your friends.' FROM games WHERE igdb_id = 254360 ON CONFLICT (game_id, language_code) DO NOTHING;
