INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commando: Steel Disaster', 'Commando: Steel Disaster is a run and gun video game game for the Nintendo DS developed by Mana Computer Software. The game played similarly to Metal Slug as players controlled an operative to stop a militant organization through five stages of merciless gun play and bullet dodging in a 2D, hand-drawn style.' FROM games WHERE igdb_id = 21272 ON CONFLICT (game_id, language_code) DO NOTHING;
