INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Championship Foosball', 'Jump into the fast-paced action of Foosball in your own living room! Using the motion-sensing technology in the Wii Remote, Championship Foosball creates a realistic gaming experience. Feel like you''re playing at a real table as you challenge your friends in 4-player action or rise through the ranks in single-player mode.' FROM games WHERE igdb_id = 51017 ON CONFLICT (game_id, language_code) DO NOTHING;
