INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hush', 'Hush is a short sociopolitical game inspired by the Rwandan Genocide in 1994, the darkest period of the Rwandan Civil War. Hush has the player relive the historical events through a personal experience - helping the Tutsi mother Liliane with her lullaby to keep her child silent and thus hide it from the Hutu.' FROM games WHERE igdb_id = 95475 ON CONFLICT (game_id, language_code) DO NOTHING;
