INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers G1 Awakening', 'Transformers G1: Awakening is a turn-based tactics mobile game in the Transformers franchise based on the 2007 Movie of the same name, developed and published by Glu Mobile. It was originally released for feature phones on November 12, 2008, before being ported to IOS in 2010. The game has been removed from the Apple App Store due to license reasons.' FROM games WHERE igdb_id = 315069 ON CONFLICT (game_id, language_code) DO NOTHING;
