INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Encyclopedia: First Story', 'Catherine had just finished taking her exams at the Academy for Magic when she received an urgent message born on the wings of a paper bird. Curious, she opened the note and was instantly transported to a strange jungle, where she began her whirlwind adventure to stop the awakening of a terrible dragon. As Catherine''s guiding hand, you''ll travel around the world, collecting various objects and then using them to solve cunning puzzles. Featuring hand-painted scenery, addictive mini-games and a spellbinding story, Magic Encyclopedia offers a seek-and-find adventure you''ll never forget!' FROM games WHERE igdb_id = 175070 ON CONFLICT (game_id, language_code) DO NOTHING;
