INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Women''s Murder Club - Death in Scarlet', 'A morning jog presents a chilling find... and a new wave of fear descends upon San Francisco. In this dramatic new interactive seek-and-find adventure based on author James Patterson''s best-selling novels, you become the detective, medical examiner and journalist as you seek to stop a killer and expose the truth. Featuring nine investigations, brain-bending puzzles, strikingly beautiful artwork and a spine tingling, all-new storyline, Women''s Murder Club: Death in Scarlet will have you racing to the finish to discover the killer.' FROM games WHERE igdb_id = 51404 ON CONFLICT (game_id, language_code) DO NOTHING;
