INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sacred 2: Fallen Angel - Collector''s Edition', 'Sacred 2: Fallen Angel - Collector''s Edition Includes: Additional DVD containing the "Elite Texture Pack," a set of ultra-high resolution textures for users of high-end computers. The unlockable in-game Carrier Imp, a special "pet" that transports the player''s treasure and additional inventory to its owner whenever summoned. (unlock code provided). A four-song music sampler from Nuclear Blast records, whose artist, Blind Guardian, is showcased in the game''s soundtrack, and an exclusive audio interview with the band and the game''s developer, discussing their collaboration to feature the band in-game. A printed map of the world of Ancaria that doubles as poster and electronic version of the Sacred 2 "Art and Vision" booklet.' FROM games WHERE igdb_id = 50329 ON CONFLICT (game_id, language_code) DO NOTHING;
