INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golf: Tee it Up!', 'Grab your clubs and play a few quick holes solo, or compete with friends in an 18-hole multiplayer tournament. With zany customizable characters and an assortment of panoramic, challenging courses, both beginner and experienced golfers will enjoy teeing it up. Need some special touch to get a leg up on the competition? Use the unique “Focus” feature to read the green and control the ball’s in-flight spin! A huge combination of game modes awaits, including stroke, cup and match play, each with local or LIVE multiplayer modes!' FROM games WHERE igdb_id = 20794 ON CONFLICT (game_id, language_code) DO NOTHING;
