INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Help Wanted: 50 Wacky Jobs!', 'Saving the world one job at a time. Help Wanted is the 1st Job Compilation centered around 50 wacky jobs! Play the 1st job compilation centered around 50 wacky jobs! Warning! Light-hearted humor ahead. Help Wanted is a fun, slap-stick game made for families. Save the world from impending extinction by shopping for defensive items. Take the time to shop as you earn money from the daily grind and add keep sakes to your displayable collection.' FROM games WHERE igdb_id = 21190 ON CONFLICT (game_id, language_code) DO NOTHING;
