INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock Band: Track Pack - Volume 2', 'This is the second of retail track packs for Rock Band. While the first pack was only made available for the platforms that do not support downloadable content, this one covers all major platforms. The original game is not required to play and Volume 2 includes twenty songs. The game also includes a code to export the songs to a hard drive for use in other Rock Band games (PS3/Xbox 360).' FROM games WHERE igdb_id = 80287 ON CONFLICT (game_id, language_code) DO NOTHING;
