INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski-Doo X-Team Racing', 'Get ready for high intensity extreme sports action in this multiplayer snowmobile racing game. Feel the rush as you wait for the green flag to drop on your snocross race. Your track hooks-up, rocketing you to the holeshot, and it now will take all your skill to tame the course and guts to execute stunts on huge fly-away jumps. For a totally different experience, enjoy the freedom of exploring the backcountry with no boundaries. Or show your style doing tricks on the radical new Freestyle sled.' FROM games WHERE igdb_id = 80137 ON CONFLICT (game_id, language_code) DO NOTHING;
