INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('professor-heinz-wolff-s-gravity', 5109, '2008-11-28', 53, 'https://images.igdb.com/igdb/image/upload/t_cover_big/jncxnod3s0mnk3ihty3q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ndw5v3uut8wjbdsm23b8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professor Heinz Wolff''s Gravity', 'Professor Heinz Wolff''s Gravity is an exciting puzzle game released on Nintendo Wii and Nintendo DS. Although there are subtle differences between each version, they all contain 100 puzzles of varying difficulty for you to solve. As the name suggests, these puzzles involve using gravity and other properties of physics to solve them. Gravity is suitable for the whole family and is a fun way to keep your mind at its sharpest!' FROM games WHERE igdb_id = 5109 ON CONFLICT (game_id, language_code) DO NOTHING;
