INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo Subs', 'A super-charged sequel to the hit time management game Turbo Pizza, Turbo Subs is twice the fun, twice the challenge, with twice as much speed. Hit the kitchen running as Rebecca and Robert continue their pursuit of building the greatest restaurant franchise in town. Except now they find themselves in a much bigger town, New York City! With loads of upgrades, secret sauces, and unique tastes, Turbo Subs is a delicious new adventure for the whole family!' FROM games WHERE igdb_id = 206070 ON CONFLICT (game_id, language_code) DO NOTHING;
