INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sim Taxi', 'The main objective of the game is to look for passengers and deliver them to their destinations as quickly as possible without damaging your car. A phone operator will help you locate customers. There''s a compass on the top left to guide you. There is a fuel and damage indicator on the bottom left and right of your screen. Check up on them periodically to avoid losing the game. Fill up on fuel, repair the taxi, upgrade your taxi and enjoy the ride.' FROM games WHERE igdb_id = 271387 ON CONFLICT (game_id, language_code) DO NOTHING;
