INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty of Egypt', 'As the ruler of the Egyptian Dynasty, it is your duty to guard the secrets of the Pyramids. Use your powerful stone shooters to destroy the Spheres of Divination before they disappear deep within the earth. The gameplay is similar to Zuma.' FROM games WHERE igdb_id = 53975 ON CONFLICT (game_id, language_code) DO NOTHING;
