INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kiss-before-midnight', 253644, '2008-02-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mqj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kiss Before Midnight', 'This dating simulation revolves around a group of nine people whose stories are all intertwined in the city of love, Paris. Paul has returned to his friends Amelie and Ricky after one year of studying in Berlin, and is thrilled to see his old crush Devine again, although he''s less thrilled about her getting married to macho Vincent in a few days. Ricky is interested in Luca, the red-haired waitress at the clique''s favorite café, while Amelie would like to get closer to her former professor Marcel Benoît. Amelie''s fashion-conscious and manipulative twin sister Estelle and flower girl Marie will also play their part. Taking control of these characters throughout 15 episodes, players influence the relationships between them, mainly by choosing what they say in conversations. Some characters occasionally have to be dressed for a specific event in a mini game, while a second, more frequent mini game allows characters to tip the mood or topic of a conversation in their favor by using cards representing certain gestures. In the end, the player''s actions through all episodes will determine who hooks up with whom.' FROM games WHERE igdb_id = 253644 ON CONFLICT (game_id, language_code) DO NOTHING;
