INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kryzta', 'Kryzta is an experimental action game by Cactus. On the surface, it looks like an arena shooter, but you are unable to fire. Instead, the focus is on avoiding enemy shots and maneuvering in such a way that the enemy hit each other, instead of you.' FROM games WHERE igdb_id = 199113 ON CONFLICT (game_id, language_code) DO NOTHING;
