INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summer Sports: Paradise Island', 'Check into the Paradise Island Resort and explore the vast array of recreational activities in a lush tropical environment. Compete against friends in a collection of summer-themed games including Basketball, Croquet, Lawn Darts, Badminton, Volleyball, Horse Shoes, and Mini-Golf. Bump, set, spike, throw, putt, shoot, swing, and more - all with intuitive Wii Remote gestures!' FROM games WHERE igdb_id = 5197 ON CONFLICT (game_id, language_code) DO NOTHING;
