INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'USA Today Crossword Challenge', 'USA Today Crossword Challenge offers you hundreds of different crossword puzzles on a grid of up to 15x15 squares in size. The game is controlled via the Nintendo DS stylus and onscreen icons. Answers to the questions can either be written directly into the game via the writing recognition area in the game or by bringing up a full keyboard.' FROM games WHERE igdb_id = 92335 ON CONFLICT (game_id, language_code) DO NOTHING;
