INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elements of Destruction', 'You are the master of disaster! Use tornadoes, lightning, earthquakes and many other forces of nature to do your bidding. Fired from your job as a top research scientist you have built a machine that allows you to control Nature and exact revenge on the corporation that fired you. Your quest for revenge takes you to locations across the globe where you must use the forces of nature in challenging ways. Shake down buildings with earthquakes, suck-up and throw objects with tornadoes, and strike down aircraft with lightning to cause mayhem in cities and towns across the earth.' FROM games WHERE igdb_id = 21517 ON CONFLICT (game_id, language_code) DO NOTHING;
