INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto Shippuden: Dairansen! Kage Bunshin Emaki', 'Naruto Shippuden: Dairansen! Kage Bunshin Emaki is an action/adventure video game featuring a top view. The game was developed and published by Takara Tomy for the Nintendo DS. Players control Naruto Uzumaki during the events of the Kazekage Rescue Mission through the Tenchi Bridge Reconnaissance Mission, which combines all the key moments since the abduction of Gaara to the reunion with Sasuke.' FROM games WHERE igdb_id = 61026 ON CONFLICT (game_id, language_code) DO NOTHING;
