INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daikaijuu Battle: Ultra Coliseum', 'Mega Monster Battle: Ultra Coliseum (大怪獣足取り ウルトラコロシアム Daikaiju Batoru Urutora Koroshiumu) is the first Ultra Galaxy video game released for Wii only. It''s released to coincide the series Ultra Galaxy Mega Monster Battle: Never Ending Odyssey. This game is succeeded by Mega Monster Battle: Ultra Coliseum DX: The Gathering of The Ultra Heroes!' FROM games WHERE igdb_id = 72480 ON CONFLICT (game_id, language_code) DO NOTHING;
