INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Custom Girl', '公式パーツ3300個を組み合わせて、オリジナルの少女をデザインし動かす「抜きに徹底」したアダルトゲームである。 最大の特徴として、ユーザーが開発改良した独自パーツファイル「tah」をフォルダに入れるだけで自動的にゲームシステム内部に取り込めることがある。ユーザーにより衣装やボディ・モーション・背景などが多数開発され、その量は18326種類、129390個、50GBを超えるなど大量の改造パーツが利用できる。' FROM games WHERE igdb_id = 92660 ON CONFLICT (game_id, language_code) DO NOTHING;
