INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Generation Xth: Code Hazard', 'The first in a trilogy of dungeon crawling RPGs for the PC. Create and customize a team of 6 people from 16 classes to try and survive the Abyss. The save file from the first game can be used in the second. The games were not originally released outside of Japan but a fan translation was made for Code Hazard. The first and second game were later re-released on the Playstation Vita in Japan under the name "Tokyo Shinseiroku: Operation Abyss" in 2014 and in North America and Europe under the name "Operation Abyss: New Tokyo Legacy" in 2015.' FROM games WHERE igdb_id = 14682 ON CONFLICT (game_id, language_code) DO NOTHING;
