INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Critter Round-Up', 'Quickly corral the critters into their own pens! Critters Round-Up is an original arcade-style puzzle game that tasks the player with building fences in order to separate different herds of critters. Be careful to watch the animals and make sure they don’t get you while you’re putting up your fences! More than 50 challenging levels take you to several exotic locations, including the Outback, the icy Arctic and more! Play solo or with a friend in Adventure Mode or play with up to 4 friends in all mini games, Co-Op Challenge and Marathon Mode!' FROM games WHERE igdb_id = 21824 ON CONFLICT (game_id, language_code) DO NOTHING;
