INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Hits 2', 'SingStar: Hits 2 is a karaoke game exclusively released in France. The features songs are almost exclusively from French artists. There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timeing; the sung words or octave does not play into the result. The game allows access to the SingStore, an online shop for downloading additional songs.' FROM games WHERE igdb_id = 43044 ON CONFLICT (game_id, language_code) DO NOTHING;
