INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons: Itchy & Scratchy Land', 'The Simpsons: Itchy & Scratchy Land is a 2.5D adventure mobile game based on The Simpsons. Run For Your Lives! It''s The Simpsons Itchy & Scratchy Land! Just like in the classic Simpsons episode, our favorite family''s theme park outing is ruined by Itchy & Scratchy ''bots. Play as Homer, Bart, Lisa and Marge as they survive Explosion Land, Unnecessary Surgery Land, Torture Land and Searing Gas Pain Land. Kill the Kill ''bots with Bart''s stink bomb slingshot. Build Bomb ''bots with Lisa''s Robo-Generator. Blow ''bots to bits with Marge''s vacuum gun. Life is a thrill ride with The Simpsons.' FROM games WHERE igdb_id = 190876 ON CONFLICT (game_id, language_code) DO NOTHING;
