INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Truth About 9th Company', 'The Truth About 9th Company is the first Russian documentary computer game. The game simulates the historical battle for Hill 3234 which took place on 7–8 January 1988 in southern Afghanistan between Soviet paratroop units of the 345th Independent Guards Airborne Regiment and mujahideen.' FROM games WHERE igdb_id = 158978 ON CONFLICT (game_id, language_code) DO NOTHING;
