INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EyeToy Play: PomPom Party', 'It''s time to get that party started, cheerleader style! EyeToy Play: PomPom Party is your chance to pull off some groovy moves and become the coolest cheerleader around. The game comes complete with a real set of pompoms, and as you follow the directions on-screen and wave them to the groove of the music, the EyeToy USB Camera will detect your movements and score your dancing.' FROM games WHERE igdb_id = 2215 ON CONFLICT (game_id, language_code) DO NOTHING;
