INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('planet-rescue-wildlife-vet', 149267, '2008-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co74x5.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planet Rescue: Wildlife Vet', 'Planet Rescue is a range of games focusing on environment issues. While children play, they also learn about endangered animals, pollution, and what can be done to help improve our behaviours. In Planet Rescue: Wildlife Vet, you have a great opportunity to join the most prestigious NGO vet clinic in the world. Choose the vet you want to be, male or female, pass the test period and start your permanent new job position in this environmental organisation. Besides managing your own clinic, you will tour the world to rescue, heal and take care of wild animals. Most of them are endangered species like the Sea Turtle, Florida Panther, Giraffe or the China Panda Bear for instance. More than 30 missions around the world, to heal endangered exotic animals, or to treat the animals directly in the clinic. Depending on the weather and the place, choose the right outfits to perform the treatment in the best conditions. Use the Wii Remote to perform realistic actions: rescue, diagnose and treat a variety of different species - adult and baby animals such as Florida Panther, Giraffe, China Panda Bear, Zebra, Kangaroos, India Elephant... Take care of your own pet: a cute baby tiger! Feed and clean it, play with it, and make sure it stays healthy!' FROM games WHERE igdb_id = 149267 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 149267 AND p.igdb_id = 5 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 149267 AND rs.code = 'PEGI' AND r.code = '3' ON CONFLICT DO NOTHING;
