INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers Animated: The Game', 'Based on the hit television series, Transformers Animated: The Game delivers an exciting action-adventure experience. As they blast through Decepticon-controlled hoverbots, players must solve challenging team-building puzzles and race through futuristic Detroit roadways, dodging on-coming traffic while seamlessly morphing between robot and vehicle form. Fans take control of all their favorite Autobot characters, including Optimus Prime, Bumblebee, Bulkhead and Prowl, as they work together to reclaim the lost fragments of the Allspark before the Decepticons intercept it and claim Cybertron as their own.' FROM games WHERE igdb_id = 47846 ON CONFLICT (game_id, language_code) DO NOTHING;
