INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Was in the War', 'I Was in the War is either a philosophical look at how war can escalate out of control or an action-packed—and rather distorted—arcade game that requires quick reactions and a steady hand. It all depends on your approach.' FROM games WHERE igdb_id = 242822 ON CONFLICT (game_id, language_code) DO NOTHING;
