INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz!: Quiz TV Special Edition', 'The Special Edition version of Buzz! also includes loads of game extras and features previously only available via PlayStation Network (PSN). These include four extra characters and ten cheeky new buzzer noises, as well as in-game trophies to reward top quizzers plus the new Quickstart mode, which cuts out set-up time and gets you straight into the game. Buzz!: Quiz TV Special Edition also offers PlayStation Eye compatibility, which means that the hilarious ‘Buzz! faces’ contestants pull at moments of tension and celebration can be broadcast in-game or shared with the world.' FROM games WHERE igdb_id = 268768 ON CONFLICT (game_id, language_code) DO NOTHING;
