INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bible Black: The Infection', 'Upon its release in 2000, Bible Black -La noche de Walpurgis made history with its tale of black magic and immoral situations wrapped in an occult setting. Now a sequel to that famous game has been announced! This new tales begins one month following the events of the earlier game, with the revelation that Kitami Reika, who should have died, has reappeared?! The protagonists are once again assailed by a nightmare!' FROM games WHERE igdb_id = 72571 ON CONFLICT (game_id, language_code) DO NOTHING;
