INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Questions Pour un Champion: Edition Spéciale 20 Ans', 'A quizz game adapted from a French TV show. You can test your general knowledge by playing one the three game modes. The Super Champion mode recreates the TV show specials where you need to reach 5 victories in a row. The Partie Classique mode allow you to play on game. The Entrainement mode allows you to train yourself.' FROM games WHERE igdb_id = 215783 ON CONFLICT (game_id, language_code) DO NOTHING;
