INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silver Star Chess', 'Silver Star Chess has two modes: 1-Player and 2-Player. 1-Player mode allows you to play a chess match against the computer opponent. 2-Player mode allows you to play against another person. In 1-Player mode, you can select one of five different computer opponents, as well as turn the background music off, adjust sound effects and access in-game help features.' FROM games WHERE igdb_id = 85371 ON CONFLICT (game_id, language_code) DO NOTHING;
