INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sprint Cars 2: Showdown at Eldora', 'Climb into 10 of the fastest and most dangerous dirt-track vehicles in the world. Survive 27 racetracks and thrill the fans; avoid spectacular crashes to get to the finish line first. Multiple-event championships in Arcade mode; 2-player head-to-head Race mode. Conquer brutal track tests to collect bronze, silver, or gold medals in Challenge mode. Realistic car physics will have cars flipping, colliding, and experiencing real-world damage.' FROM games WHERE igdb_id = 208777 ON CONFLICT (game_id, language_code) DO NOTHING;
