INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planet Rescue: Animal Emergency', 'Prove your skills as a vet in your own clinic and get the chance to join the planet rescue team for a great opportunity to treat exotic animals and rescue endangered species. From harp seals to pandas, keep a large variety of animals under observation in your clinic. Perform scans, take their temperature and pulse and apply ointments as you help your patients recover. Collect information cards about the animals, characters and equipment in the game and share them with friends using the DS wireless communications.' FROM games WHERE igdb_id = 139116 ON CONFLICT (game_id, language_code) DO NOTHING;
