INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big League Sports', 'Big League Sports for Wii offers instant access to the most action-packed moments in sports. The result is a title with a singular focus on putting you in the most thrilling situations while competing in your favorite sports. Six sports are represented for a combined total of 22 events, each using instinctive controls that mimic real athletic movement with the Wii Remote. Each sport -- tennis, basketball, football, soccer, lacrosse and hockey -- has its own kind of hit the shot at the buzzer style of heart-pounding action, and this is exactly what Big League Sports captures.' FROM games WHERE igdb_id = 81510 ON CONFLICT (game_id, language_code) DO NOTHING;
