INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark and Light', 'Dark and Light was a pay to play fantasy MMORPG developed in Reunion Island by NPCube and published by Farlan Entertainment. It was released on June 6, 2006, to largely negative reviews. Though there was never an official announcement regarding discontinuation of service, the servers have been offline since 2008, ostensibly due to a lawsuit by VWORLD, LLC. Snail Games acquired the rights to Dark and Light in 2008 and developed a "fantasy survival sandbox RPG", which was released as early access in 2017 with the same name.' FROM games WHERE igdb_id = 251093 ON CONFLICT (game_id, language_code) DO NOTHING;
