INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little League World Series Baseball 2008', 'Officially licensed Little League baseball action hits the Wii and DS! The first officially licensed Little League video game to hit next-generation consoles. Players will bat, pitch and field their way from local sandlot slugger to Little League World Series Champion. Featuring eight U.S. and eight international teams, extraordinarily deep character customization, World Series Mode, and a variety of skill based challenges, Little League World Series offers an exciting, authentic baseball experience. Motion-sensing controls on the Wii make it accessible for Little League players and parents alike, while the DS version gives players the freedom to get on the diamond anywhere.' FROM games WHERE igdb_id = 47953 ON CONFLICT (game_id, language_code) DO NOTHING;
