INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'STCC: The Game', 'STCC The Game is the official game of “STCC – Swedish Touring Car Championship”, the largest and most prestigious motorsport championship in Scandinavia. The game includes all cars and tracks from the 2008 season; seven Swedish and Norwegian tracks like Mantorp Park, Knutstorp Ring, Våler Track and the world exclusive city racetrack Eco Drive Arena in Gothenburg along with cars like Audi A4, Volvo C30 and BMW 320si. STCC The Game appeals to both old and young and features famous drivers like Janne “Flash” Nilsson, Tommy Rustad, Fredrik Ekblom and Thed Björk. STCC The Game – The most Scandinavian game package of 2008.' FROM games WHERE igdb_id = 10921 ON CONFLICT (game_id, language_code) DO NOTHING;
