INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gallop & Ride!', 'Life with a horse is a dream come true! Take on the ownership of the Old Mill Ranch—it''s up to you to renovate, manage and care for the stables and your horses. Train, groom and massage your horse, using the Wii Remote. Create the horse of your dreams from hundreds of combinations of coats, manes, saddles, bridles, blankets and more! Take your horse out for a ride and explore the woods, beach or mountains. Grow your stable and business, by adding new buildings and welcoming guests to your ranch.' FROM games WHERE igdb_id = 51073 ON CONFLICT (game_id, language_code) DO NOTHING;
