INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brain-assist', 21679, '2008-03-26', 67, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kuvzcmbihzocqntfy8zi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scspci.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brain Assist', 'Are you tired and overworked? Does your brain need a pick-me-up? Then you need Brain Assist! Re-energize your brain with 10 colorful mind-teasing mini-games that stimulate your concentration, memory, analysis, instincts and reflexes. Six nurses with widely varying personalities will guide you through the games and keep track of your best results. A unique new test even allows you and a friend to examine the compatibility of your right brains. Get more friends in on the action with the Wi-Fi Connection and race through a variety of fast-paced four-player mini-games to see who the true brainiac is! Ten mini-games stimulate and refresh your Right Brain. Ten mini-games improve your reflexes, memory and concentration. Get four friends in on the action in fun, fast-paced wireless battles. Enter fast-paced challenges with up to four friends wirelessly. Challenge up to four friends to fun, fast-paced wireless battles. Compare your brain with a friend’s in the unique Compatibility Check. Take compatibility tests to see if you and a friend have similar Right Brains!' FROM games WHERE igdb_id = 21679 ON CONFLICT (game_id, language_code) DO NOTHING;
