INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kung Fu Panda: Legendary Warriors', 'The sinister Tai Lung is determined to exact his revenge and has concocted a plot to capture the Furious Five. Only Po, the new Dragon Warrior, can battle Tai Lung and save his friends, but he''s going to need your help. Throw yourself into the action and unleash your most awesome kung fu moves to help Po complete his mission and put a stop to Tai Lung''s evil plan.' FROM games WHERE igdb_id = 4963 ON CONFLICT (game_id, language_code) DO NOTHING;
