INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Classic British Motor Racing', 'Classic British Motor Racing is a racing simulation game. Choose from an amazing range of 13 high performance classic cars, including Austin Mini, Austin-Healy, MG, Rover and Triumph. Each car is accurately recreated under license and features the real handling characteristics of the vehicles. Race through six different courses throughout the British Isles, including the heart-stopping thrills of the traditional ''Westminster Run'' around the streets of London. Take on various game modes, including Time Trial and Grand Prix. Try and beat the track records or race against friends in the insanely addictive multiplayer mode.' FROM games WHERE igdb_id = 4766 ON CONFLICT (game_id, language_code) DO NOTHING;
