INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '10 Gnomes 1: The Rooftops', 'For all of You that enjoyed search for secret items in Submachines, or the bird quest in DayMare Town. This is a game created entirely on the idea of finding hidden objects (Gnomes in this case). You have 10 minutes to find 10 Gnomes – navigate via the normal point and click manner.' FROM games WHERE igdb_id = 306567 ON CONFLICT (game_id, language_code) DO NOTHING;
