INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Jockey', 'Family Jockey (ファミリージョッキー) is a party race game that can be easily played by a large number of people with easy operation by anyone from children to adults. By shaking the Wii remote and the nunchuk as a rein, you can accelerate the horse or hit the whip to make it drastically dash, and you can feel the jockey feeling. A variety of courses such as “Oval”, “Nangoku Resort”, “Western”, etc. are waiting for the jockey, and many unique horses that can be selected according to the player''s preference will appear, so you can enjoy playing as many times as you like receive. In various battle modes where up to four players can participate, you can also use “Mii” to play races with family and friends.' FROM games WHERE igdb_id = 268128 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 268128 AND p.igdb_id = 5 ON CONFLICT DO NOTHING;
