INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loftus and the Sky Cap', 'Inessa is woken by the smell of smoke. She races down the stair case to discover the workshop torched and no trace of her Master Loftus. The townsfolk are convinced that a dragon must be responsible or that the crazy inventor must simply have blown himself up- but Inessa believes otherwise.' FROM games WHERE igdb_id = 170282 ON CONFLICT (game_id, language_code) DO NOTHING;
