INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts coded', 'Kingdom Hearts coded is the fourth game in the Kingdom Hearts series, taking place just before the epilogue of Kingdom Hearts II and possessing a deep connection with Kingdom Hearts Birth by Sleep. It is an episodic puzzle video game which was released from 2008 to 2010 in eight episodes on the Docomo Prime Series-P-01A Panasonic mobile phone.' FROM games WHERE igdb_id = 20285 ON CONFLICT (game_id, language_code) DO NOTHING;
