INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimson Gem Saga', 'With beautiful, high-resolution 2-D artwork, novel battle mechanics, and a classic tale of fantasy, adventure, and heroism, Crimson Gem Saga delivers the pure, classic Japanese RPG play experience PSP owners have been clamoring for since the hardware''s launch. Taking full advantage of the crisp, clear PSP screen and boasting a colorful, catchy musical score, Crimson Gem Saga is a blast from the past presented just as you''d expect a modern RPG to be.' FROM games WHERE igdb_id = 19640 ON CONFLICT (game_id, language_code) DO NOTHING;
