INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('splitter', 90241, '2008-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6eb5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm66z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splitter', 'This physics-based puzzle game challenges you with 25 brain-teasers aimed to develop your spatial thinking and accuracy. Draw a line to cut joints, as well as wooden blocks and planks. Learn to avoid obstacles and use dynamic figures to bring the smiley to the exit. The objective gets challenging as you get fewer moves to solve the puzzle. Collect all the stars and prove a physics games pro. Having become a smash hit among flash games online, this logic game returns to your desktop or mobile browser to play online without download.' FROM games WHERE igdb_id = 90241 ON CONFLICT (game_id, language_code) DO NOTHING;
