INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battlefield-2142-deluxe-edition', 41886, '2008-02-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8i7x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yctcrbbr7uxzxrafkxxb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield 2142: Deluxe Edition', 'A whole new Battlefield. Battlefield 2142 - In 2006 a climatic catastrophe triggered a new ice age on earth. A hundred years later, everyone gave up on finding a solution to the problem and two superpowers were formed: Europe and on the other side the Pan Asian Coalition - causing an arms race. Now it''s 2142 and the war for the few resources left has already been going on for a few years, with no end in sight. Armed with a devastating arsenal of hi-tech weaponry, including assault rifles, cloaking devices and sentry guns, players will also take control of the most lethal vehicles known to man. Massive battle Walkers wage fierce combat on the ground, while futuristic aircraft rule the skies. When taking on this futuristic armor players will need to use their wits and an arsenal of new hi-tech countermeasures like EMP grenades and smart mines to level the playing field. Epic online gameplay for up to 64 players drops gamers on the front lines as part of a formal squad, or behind the scenes in Commander Mode to direct the strategic assaults of their team-mates.' FROM games WHERE igdb_id = 41886 ON CONFLICT (game_id, language_code) DO NOTHING;
