INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman Touch: The Legend of Mystic Bomb', 'The story of ''The Legend of Mystic Bomb'': Get a hidden treasure in the ruins! It is said that deep inside the jungle lies a heretical ruins called KA-BOOM TEMPLE, where a legendary treasure is hidden somewhere... Many adventurers have tried, but none succeeded to even come home alive. It is here that you will see another daredevil who will take on this challenge, at the risk of his own life, to face KA-BOOM TEMPLE... He is, Bomberman.' FROM games WHERE igdb_id = 73033 ON CONFLICT (game_id, language_code) DO NOTHING;
