INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doeo', 'You’ll need a sharp eye and fast fingers to master Doeo! This online action game gets you grabbing as many Doeos as you can before the clock runs down. Mouse over to catch them as quickly as possible before they disappear. Catch your quota to advance to the next hilarious level. Make it to the sixth and final level to take on the boss. I bet you’ll laugh… at least once!' FROM games WHERE igdb_id = 254300 ON CONFLICT (game_id, language_code) DO NOTHING;
