INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Did it Mum! Picture Book', 'I Did it Mum! Picture Book is a new spin-off of the popular series featuring eight different delightful stories based on classic European and Asian fairy tales. As well as offering youngsters the opportunity to improve their reading, Picture Book also contains interactive drawings for players to colour in and fun mini games to keep inquisitive minds busy. Finally, for parents who want to read the stories to their children, there''s an option to turn off the in-game narration; perfect for a spot of bedtime storytelling.' FROM games WHERE igdb_id = 48040 ON CONFLICT (game_id, language_code) DO NOTHING;
