INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakuman Wii: Ide Yosuke no Kenkou Mahjong', 'This is a mahjong game where you play against characters of various ways using the rules of "Health Mahjong", which unifies the rules that differ depending on the generation and region, and makes it easy for anyone to enjoy. You can play against a character operated by a computer by yourself, or you can play against players from all over the country or acquaintances far away using the Nintendo Wi-Fi connection.' FROM games WHERE igdb_id = 63040 ON CONFLICT (game_id, language_code) DO NOTHING;
