INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Network Taisen Mahjong MJ4', 'The fourth entry in Sega''s MJ series of arcade games. Most notably, this installment adds a Sanma (3 Player) league, a training mode, and an improved 16:9 Live terminal. It received numerous minor updates, with features such as a customizable narrator and a visible tile wall when spectating being added, before eventually receiving a significant upgrade in 2010 called Sega Network Taisen Mahjong MJ4 Evolution.' FROM games WHERE igdb_id = 165395 ON CONFLICT (game_id, language_code) DO NOTHING;
