INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akatsuki no Goei: Principal-tachi no Kyuujitsu', 'This is a fan disc of Akatsuki no Goei, featuring six short stories. The game includes a Reika & Kyouka story, Tsuki story, Aya story, Moe story, Tae story, and an Anzu story focusing on Kaito''s past that is unlocked after the previous five are completed.' FROM games WHERE igdb_id = 202952 ON CONFLICT (game_id, language_code) DO NOTHING;
