INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War Operations', 'Go on secret missions in solo or co-op mode with another human player. Destroy military installations and rescue hostages in this fast paced 3D FPS game which requires all of your skill and wit to complete! Intelligent AI enemies guard the bases and will react to even the smallest sound. Be careful and try to get out alive in this epic game of War and Destruction!' FROM games WHERE igdb_id = 17715 ON CONFLICT (game_id, language_code) DO NOTHING;
