INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TV Show King Party', 'Become King of a TV trivia show! Confront friends - see who is the smartest! Let your Mii try to answer fun and challenging trivia questions, from the classics to original stumpers, spanning across history, geography, literature, science, sports and entertainment! For an extra challenge, use your Wii Remote in original ways. Make it to the finals and see who can win the greatest amount of cash in one last, ultimate duel. TV Show King will challenge your brain! Now, get ready... get set... and go play TV Show King!' FROM games WHERE igdb_id = 5248 ON CONFLICT (game_id, language_code) DO NOTHING;
