INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounce Tales', 'Bounce Tales is a classic mobile platformer game originally developed by Nokia for their Java (J2ME) phones. The game stars a small red bouncing ball that you control through different colorful levels filled with traps, puzzles, enemies, and moving platforms. Your main mission is to navigate through increasingly challenging stages, solve simple puzzles, avoid obstacles, and defeat enemies while keeping the ball alive. The controls are simple — move left, right, and bounce — but the game becomes tricky as you progress.' FROM games WHERE igdb_id = 133867 ON CONFLICT (game_id, language_code) DO NOTHING;
