INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akatsuki no Amaneka to Aoi Kyojin: Pashiate Bunmei Kenkyuukai Koubouki', 'Amaneka is a student of the Empire Junior Academy. Everyone in the country is excited because the 1st International Exhibition will be held there soon. Students of the Empire Junior Academy are excited as well. Only one club can take part in it, so students are now busy preparing for it. Amaneka and her friends also set out on an adventure for a secret treasure....' FROM games WHERE igdb_id = 67296 ON CONFLICT (game_id, language_code) DO NOTHING;
