INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz! Junior: Dino Den', 'This game allows the user to take control of one of four different dinosaur characters and play against the other three Buzz controllers. It includes 35 multi-player games including go-cart racing, riding a tyrannosaurus rex, and dunking cavemen, which are all played to win dino eggs. The person with the most dino eggs at the end of the game is declared the King of the Dinos.' FROM games WHERE igdb_id = 43507 ON CONFLICT (game_id, language_code) DO NOTHING;
