INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('broken-sword-2-dot-5-the-return-of-the-templars', 125018, '2008-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mmo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc77up.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Sword 2.5: The Return of the Templars', 'Broken Sword 2.5: The Return of the Templars is a fan made sequel to continue the storyline after the first two games in the Broken Sword adventure series, and ties up the events leading up to the third game. Like the first two games, a 2d view is used with point-and-click gameplay instead of the full 3d from the later games. Familiar locations all over the world are mixed with new settings and characters. George, Nico and André all return, but new ones such as Christophe Brai and English historian Jimmy McLaugh also play an important role. Movement is done with the mouse, while the cursor changes automatically to an available action when hovering over a hotspot. Items are stored in an inventory and dialogues trees are shown as icons representing items or characters. Players will control George and Nico intermittently throughout the story. It is also possible to die in the game. Although it is a tribute to the original series, the production values are high with entirely new environments, characters, rendered cut-scenes, sounds and a storyline that match the original games. Some people involved with the original game have contributed and there is full German (with a few of the voices of the original games) and English voice acting.' FROM games WHERE igdb_id = 125018 ON CONFLICT (game_id, language_code) DO NOTHING;
