INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ellen Whitaker''s Horse Life', 'In Horse Life 2 the player can select his horse from seven different breeds and can take care of it, train it and take part in various competitions. The horse''s behaviour is thereby depicted in a lifelike way in real-time. All competitions in the riding world such as dressage, show jumping and cross country are shown realistically. A gripping story really at-tracts the player to the screen and allows him to experience many differing tasks in a wide range of varied locations.' FROM games WHERE igdb_id = 92406 ON CONFLICT (game_id, language_code) DO NOTHING;
