INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Hollow', 'Time Hollow follows the story of Ethan Kairos and the mysterious disappearance of his entire family. As Ethan searches for his family he comes across a Hollow Pen, an uncanny object with the unique power to open portals to the past. This allows Ethan to change the past in order to solve problems in the present. Through the use of this mystical pen he must follow events in the present and past to locate his missing family.' FROM games WHERE igdb_id = 21055 ON CONFLICT (game_id, language_code) DO NOTHING;
