INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrigglui', 'Full moon has arrived and the fireflies, including Wriggle Nightbug, begin preparing their adventures. Like many visual novels, the gameplay in Wrigglui follows an interactive branching plot line with multiple scenarios. There are five main plot lines that the player will have the chance to experience, and five endings depending on the decisions that the player makes during the game.' FROM games WHERE igdb_id = 280867 ON CONFLICT (game_id, language_code) DO NOTHING;
