INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warzone Tower Defense', 'Warzone is a tower defense game featuring high-tech weaponry and large open maps with varying landscapes. The goal of the game is simply to survive as long as possible. There are also several different game modes available for those looking for a new twist on the game.' FROM games WHERE igdb_id = 272436 ON CONFLICT (game_id, language_code) DO NOTHING;
