INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High School Musical: DVD Game', 'Got what it takes to be a Wildcat? Join the coolest school in town. All you need is your DVD and a remote control! Play on your own, or with friends and family in Party Play Mode! Take center stage as you and your friends perform songs from every High School Musical movie! Engage in dance-offs with your friends to the hippest tunes! Test your skills in hoops as you slam-dunk to success! All this, plus hours of out-of-your-seat challenges and games that will test your High School Musical knowledge to the limit! The party starts here with 11 action-packed games you can play again and again.' FROM games WHERE igdb_id = 228419 ON CONFLICT (game_id, language_code) DO NOTHING;
