INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zafehouse', 'Zafehouse (also known as Zafehouse: Classic), is a freeware strategy game about surviving a zombie apocalypse. The player must manage resources, gather survivors, fortify buildings and scavenge supplies in an attempt to outlast the growing zombie hoards.  Zafehouse was programmed in Visual Basic by Logan Booker, with the original version developed in just seven days.  The popularity of Zafehouse led to Logan forming Screwfly Studios to develop a spiritual sequel, Zafehouse: Diaries (and later, Zafehouse: Diaries 2).' FROM games WHERE igdb_id = 125022 ON CONFLICT (game_id, language_code) DO NOTHING;
