INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teapot Poppers', 'It''s a race against time as you shoot colored marbles at the string of marbles rolling along a twisty 3D path amid an antique tea set. Hit them before they dip behind a teapot or cup! Match three or more of the same color to knock out all the marbles before they reach the mouth of a hungry cat. Be quick, or tea time will be over!' FROM games WHERE igdb_id = 146915 ON CONFLICT (game_id, language_code) DO NOTHING;
