INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barkley, Shut Up and Jam: Gaiden', 'Years after basketball was outlawed due to Charles Barkley causing the Great B-Ball Purge of 2041 by performing a Chaos Dunk, Barkley is framed for causing another such incident. In this turn-based JRPG and unofficial parodic sequel to Barkley: Shut Up and Jam! (1994) and the movie Space Jam (1996), he and a group of unlikely heroes set off to discover the truth of the matter and to relegalize basketball.' FROM games WHERE igdb_id = 50786 ON CONFLICT (game_id, language_code) DO NOTHING;
