INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('twin-strike-operation-thunder', 24296, '2008-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kxhf9xc5shtwetmnuqac.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twin Strike: Operation Thunder', 'You are the newest recruit of the United Nations Air Force-a top secret agency set up to protect citizens against the threat of unknown forces without breaking down international agreements or diplomatic acts. You will have to take to the skies in a variety of helicopters to defend the civilized world against wave after wave of enemy aggression. Suit up and choose the best helicopter to engage the enemy in the air while avoiding attacks from the ground. Put yourself in the pilot seat with "Twin Strike"!' FROM games WHERE igdb_id = 24296 ON CONFLICT (game_id, language_code) DO NOTHING;
