INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlezone', 'The original tank vs. tank action classic has received an Xbox Live overhaul, adding in new multiplayer modes including Deathmatch, Team Deathmatch and Capture the Flag. This updated version also includes the original game. Players can use the Xbox Live Vision camera to watch live video of their opponents. Additionally, there are new special effects for weapon firing, impacts and explosions.' FROM games WHERE igdb_id = 294546 ON CONFLICT (game_id, language_code) DO NOTHING;
