INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cursor-star-10', 29042, '2008-01-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8lsu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tbjra6rozkjyejdibpth.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cursor*10', 'Cursor*10 is a puzzle game where the player controls a cursor and the goal is to reach the sixteenth floor of a level in a race against time. During the course of the game, events will loop when time runs out and the player is able to cooperate with a past version of himself, as all the previous actions of the cursor can still be seen and influence the current session. As such, eventually up to ten cursors will cooperate to reach the sixteenth floor, clicking boxes to open them, mounting stairs and pressing buttons simultaneously. There is no sound and the graphics are drawn as outlines in black and white, shown from an isometric perspective.' FROM games WHERE igdb_id = 29042 ON CONFLICT (game_id, language_code) DO NOTHING;
