INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kidz Sports International Football', 'TAKE IT TO THE FIELD!  Take control of your favorite Kidz Sports characters in some of the wackiest games of international soccer ever!  • Pick Up and Play: Use the Wii Remote and Nunchuk to dribble your way down the field and blow away the competition!  • Hours of Fun: Defeat all challengers in the single-player Knockout Cup tournament, or take on a friend in two-player head-to-head action!  • Wild Zany Action: This isn''t your parents'' soccer game! Unleash dominating Super Moves with Wii Remote gestures, earn skill points, and control a full 11-Kidz soccer team!' FROM games WHERE igdb_id = 4957 ON CONFLICT (game_id, language_code) DO NOTHING;
