INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors 6: Special', 'Dynasty Warriors 6 PlayStation 2 (真・三國無双 5 Special, Shin Sangoku Musou 5 Special) is a revised and overhauled version of Dynasty Warriors 6. It features many changes that were not in the PlayStation 3 or Xbox 360 versions. The American version of Dynasty Warriors 6: Special is not on two discs like the Japanese port. This title is advertised in Asia as the "completely revised" version of Dynasty Warriors 6.' FROM games WHERE igdb_id = 269526 ON CONFLICT (game_id, language_code) DO NOTHING;
