INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeopardy! Deluxe', 'The Jeopardy! mobile game is all new and better than ever! Experience realistic game play with enhanced graphics, more special effects, dynamic avatars and countless new clues from the TV show''s writers. Features like Daily Doubles and Category of the Day add to the fast-paced fun of this hit mobile game. Get a clue and challenge yourself to Jeopardy! Deluxe today!' FROM games WHERE igdb_id = 225402 ON CONFLICT (game_id, language_code) DO NOTHING;
