INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SeizureDome', 'SeizureDome is a fast-paced shooter by cactus. The player controls a gun-wielding sumo wrestler standing in an arena. Various weird enemies appear from all sides and try to push the player against the edge of the arena, which kills him. Enemies can be taken out by shooting them with the mouse, and the player can move to dodge them by using the WASD keys.' FROM games WHERE igdb_id = 93095 ON CONFLICT (game_id, language_code) DO NOTHING;
