INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lead', 'Lead is a fast paced Atari 2600 shooter that will keep you on your toes! There are four types of stages: "Fire", in which you must shoot enemies down. "Dodge" where you must dodge asteroids plummeting towards you. "Scramble" where you must avoid sentinels. And "Catch" stages where you must catch satellites. There are Smart Bombs and Power-ups you can capture to help you in your goal to stay alive! Lead also features two variations: Lead 1K, which is a simpler 1K version of the game (only one stage type), and Lead 4K, which features two stage types.' FROM games WHERE igdb_id = 258843 ON CONFLICT (game_id, language_code) DO NOTHING;
