INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Impact: Meteor Shield', 'Unlike the other Space Impact games, Meteor Shield does not have a 2d shoot ''em up mode. Instead this game uses a first person view and has a stationary ship/turret that is used to shoot down meteors. The game uses the Nokias built in compass to spin around and you tap the touch screen to shoot when the game locks on to a target. The game was released on the 5th edition of the Symbian platform for Nokia smartphones.' FROM games WHERE igdb_id = 10216 ON CONFLICT (game_id, language_code) DO NOTHING;
