INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DJMax Trilogy', 'DJMax Trilogy is a rhythm action game with five difficulty modes ranging from limited four-key gameplay to a challenging eight-key setup. As notes are played with perfect accuracy, a "fever gauge" will be charged. When it is fully charged, Fever can be activated. Fever acts as a multiplier to score and it varies between x2 and x5.' FROM games WHERE igdb_id = 92347 ON CONFLICT (game_id, language_code) DO NOTHING;
