INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'McWorld', 'McWorld was a flash-based virtual-world MMO created by McDonalds in 2008. The in-game world was divided into a variety of themed areas with their own unique minigames, shops, and media tie-ins. Players could customize their avatar and treehouse with various items and accessories, some of which were based on McDonalds products.' FROM games WHERE igdb_id = 283408 ON CONFLICT (game_id, language_code) DO NOTHING;
