INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'What''s Cooking? Jamie Oliver', 'What''s Cooking? with Jamie Oliver walks players through virtual and real-life cooking situations, from shopping to chopping, dressing the dish to serving up meals. The portability of Nintendo DS means Jamie Oliver is with you every step of the way to offer help and inspiration at the supermarket, in the kitchen, on the barbecue or wherever you feel like cooking up a storm.' FROM games WHERE igdb_id = 80202 ON CONFLICT (game_id, language_code) DO NOTHING;
