INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spore Origins', 'Spore Origins is the mobile device spin-off of Spore, and focuses on a single phase of the larger game''s gameplay - the cell phase. The simplified game allows players to try to survive as a multicellular organism in a tide pool, with the ability to upgrade its creature as with the main game.' FROM games WHERE igdb_id = 78885 ON CONFLICT (game_id, language_code) DO NOTHING;
