INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tsuki to Taiyou no Raksharuki', 'In this Desert world death threatens all living beings. Main character is a trader who with brothers surfs between different nations selling goods. One day brother gets into an incident during the banquet, and king orders protagonist to retrieve a certain magical lamp within a year to save brother from punishment.' FROM games WHERE igdb_id = 194926 ON CONFLICT (game_id, language_code) DO NOTHING;
