INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supreme Ruler 2020', 'Overnight, the US dollar crashes AND the sound echoes across the globe. The economic crisis amplifies global instabilities and regional disputes, tearing the world asunder. Nations dissolve, economies collapse, and tensions escalate. Anarchy reigns supreme. The world needs a leader. At last, your time has come.' FROM games WHERE igdb_id = 2024 ON CONFLICT (game_id, language_code) DO NOTHING;
