INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeep Thrills', 'Jeep, the undisputed King of off road adventure, invites you to climb into the driver''s seat and experience racing like never before. 18 customizable Jeep vehicles (including futuristic concept cars!), 35 intense tracks, and one main objective: conquering the terrain and the elements and owning the planet. From the jungles of Central America to the frozen Alaskan tundra, this is adventure racing like it ought to be. Jeep Thrills! And everyone else? Get left behind.' FROM games WHERE igdb_id = 4940 ON CONFLICT (game_id, language_code) DO NOTHING;
