INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Chronicles 2: The Eternal Maze', 'Return to the wonderful world of Dream Chronicles(TM) in this eagerly-anticipated sequel. Faye, locked away by Lilith the Fairy Queen of Dreams, once again needs your help to navigate this brain-bending and beautiful world of puzzles. Discover the origins of the fairies, hunt for dream jewels, seek advice from the foliage, and find your way out of the Eternal Maze. An incredible journey that crosses the lines between reality and fantasy, humans and immortals, Dream Chronicles(TM) 2 - The Eternal Maze is a unique puzzle challenge featuring adventure, mystery, and fun!' FROM games WHERE igdb_id = 50502 ON CONFLICT (game_id, language_code) DO NOTHING;
