INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Insecticide Part 1', 'Enter the fast shooting world of Insecticide as hot shot rookie Detective Chrys Liszt and help solve a crime of epic proportions. Lead your team on a bug hunt, collecting clues and solving puzzles. Use old-fashioned street smarts, unique insect abilities and an arsenal of ingenious bug weapons to confront your suspects. Explore a futuristic world of mutant insects and uncover the truth in a city infested with corruption.' FROM games WHERE igdb_id = 29118 ON CONFLICT (game_id, language_code) DO NOTHING;
