INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kenny vs. Spenny: Best Friends/Worst Enemies', 'Kenny vs. Spenny: Best friends/Worst Enemies is a collection of mini-games for mobile phones based on the popular TV series Kenny vs Spenny. The mini-games are all based on episodes of the show such as ''Who can win a rat race?'', ''Who’s got the biggest balls?'' & ''Who can wear an octopus on his head the longest?''.' FROM games WHERE igdb_id = 303697 ON CONFLICT (game_id, language_code) DO NOTHING;
