INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rara Racer', 'Rara Racer is a racing game which is also a Let''s Play of itself: with a Let''s Play voiceover (e.g. every time the player dies the voice curses), internet popups, an instant messaging chat box, a fake YouTube style visuals with a progress bar, and so on. It''s notable for being humorous, unexpected, and meta.' FROM games WHERE igdb_id = 125769 ON CONFLICT (game_id, language_code) DO NOTHING;
