INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lumines Supernova', 'In January 2009 Lumines Supernova was released on the PlayStation Network. It has all the features of Lumines Live! (with the exception of online multiplayer) as well as the sequencer from Lumines II and a new mode, DigDown Mode. DigDown Mode is a timed mode where the player has to clear two vertical lines within a time limit to move "down" to the next stage.' FROM games WHERE igdb_id = 4692 ON CONFLICT (game_id, language_code) DO NOTHING;
