INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Life DS', 'City Life DS is the Nintendo DS version of the City Life Windows game, a city building game similar to the Sim City, but with a social component. The city is inhabited by citizens with different social backgrounds, from normal workers to rich people, acting differently throughout the game. The different social classes lead to conflicts the player has to take care of and solve, by forming an efficient strategy and a way of communication.' FROM games WHERE igdb_id = 262128 ON CONFLICT (game_id, language_code) DO NOTHING;
