INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Ring Thing', 'Is an online Flash game published on the 4Kids TV website by 4Kids Entertainment in 2008 to promote the then-airing anime series, Sonic X. The objective of the game is to score as many points within sixty seconds by clicking objects that move from the bottom of the game screen to the top. The player will earn one point for clicking on a Ring, five points for clicking on the Master Emerald and lose ten points for clicking on Dr. Eggman in his Egg Mobile.' FROM games WHERE igdb_id = 299875 ON CONFLICT (game_id, language_code) DO NOTHING;
