INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FPScore', 'FPScore is a multiplayer shooter based on the Quake III Arena. The game was published in cooperation with the Czech video game magazine Score. The game contains maps that are partly inspired by reality (Muzeum metro station in Prague, radar in Brdy), as well as sci-fi maps and map clones from Counter-Strike (namely Assault, Dust). FPScore contains original graphics (textures and models), completely new sounds and music.' FROM games WHERE igdb_id = 142971 ON CONFLICT (game_id, language_code) DO NOTHING;
