INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Aftermath', 'Project Aftermath is the PAX10 winning Arcade RTS where you command up to four squads of soldiers in exciting battles in a retro-futuristic world. Equip your squads to suit your playing style, researching new items using the spoils of war; choosing from over 100 different weapons, armour, power-up augmentations and spell-like special attacks.' FROM games WHERE igdb_id = 15964 ON CONFLICT (game_id, language_code) DO NOTHING;
