INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Academy', 'Grab your oven mitts and don your Chef''s Hat! Cooking Academy is the game that places you in the kitchen of a prestigious culinary school! From eggrolls to pancakes, from ravioli to creme brulee, it''s up to you to prepare over 50 recipes! Learn interesting trivia about food while mastering the skills of chopping, kneading, mashing, flipping, frying, and much more! Unlock new recipes and trophies by passing your cooking courses and exams. Are you ready to be a Master Chef? Well, then it''s time to enroll at the Cooking Academy!' FROM games WHERE igdb_id = 208792 ON CONFLICT (game_id, language_code) DO NOTHING;
