INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro Tripper', 'Astro Tripper is a furious shoot-em-up experience inspired by the painful, knuckle busting video games of years gone by. An evolution of PomPom''s 2001 award winning game, Space Tripper. Travel the surface of large horizontally-scrolling platforms, and pit your highly maneuverable craft against hoards of enemies eager to blow you to bits, eat you or worse.' FROM games WHERE igdb_id = 16265 ON CONFLICT (game_id, language_code) DO NOTHING;
