INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-monkey-ball--1', 134907, '2008-07-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hxu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8bwe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Monkey Ball', 'Super Monkey Ball was a game released in 2008 with the launch of the App Store for the iPhone and iPod touch. It was developed by Other Ocean Interactive and published by SEGA. The object of the game, like others in the Super Monkey Ball series, is to get AiAi, MeeMee, Baby or GonGon to the goal. The game is similar to both Super Monkey Ball: Touch and Roll and Super Monkey Ball: Banana Blitz: the game engine, monkey sprites, sound effects, and a few stages are reused from Touch and Roll, whereas the world theming and music are from Banana Blitz. Almost all the stages are original however. There are five continues of six lives, totaling 30 lives altogether. There are five worlds, and each world has two sets of ten stages. If you collect all the Bananas on a stage without falling off, you will earn a crown. Earning a crown on every stage in a set unlocks an Extra Stage.' FROM games WHERE igdb_id = 134907 ON CONFLICT (game_id, language_code) DO NOTHING;
