INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('akrasia', 91828, '2008-09-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ywd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sce61b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akrasia', 'Akrasia is an abstract game based on the concept of addiction. Designed around familiar game mechanics, a character explores a world, avoiding monsters and collecting items, while urging the player to reflect on the actions. The game is entirely controlled by the keyboard and is set in a maze that represents the mind. Based on the actions, it can be explored in a normal or a psychedelic state changing the main character''s features. In general, the gameplay is designed around the "chasing the dragon" and the "cold turkey" states that can be induced by addiction. The way the player tries to shake off or enhance the habit influences the outcome and the way the game is played and controlled.' FROM games WHERE igdb_id = 91828 ON CONFLICT (game_id, language_code) DO NOTHING;
