INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dovadula''s Burn', 'The story takes place in the imaginary town of Dovadula''s, where Punkkommando is trying to destroy the town with his bass guitar.  The police stop Punkkommando''s plan and he runs away.  Punkkommando loses his bass guitar, and to escape the policeman he assumes the identity of the crazy green man Capitan Fortuna.  Then he goes to his music master Matt Freeman to find a method to definitively destroy Dovadula''s.' FROM games WHERE igdb_id = 125020 ON CONFLICT (game_id, language_code) DO NOTHING;
