INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Color Cross', 'Color Cross is a challenging puzzle game where the goal is to uncover the hidden picture by applying the right color to the appropriate square. Utilizing the familiar "paint by numbers" picture logic puzzle mechanic, completing a grid will reveal a portion of a larger hidden image as well as unlocking increasingly difficult challenges. With over 150 individual grids to unlock, Color Cross provides hours of brain-teasing gameplay that is colorful in more ways than one.' FROM games WHERE igdb_id = 47769 ON CONFLICT (game_id, language_code) DO NOTHING;
