INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samba de Amigo', 'The samba-inspired rhythm music game made popular in the arcades is shaking its way onto the Wii! Keeping the beat with over 40 songs on a Samba-inspired sound track, players shake the Wii Remote and Nunchuk like maracas and compete with friends to see who has the best moves. Throughout the dynamic songs there will be opportunities to strike a pose for extra points. Friends and family will be thoroughly entertained cheering each other on as they anxiously await their next turn.' FROM games WHERE igdb_id = 21807 ON CONFLICT (game_id, language_code) DO NOTHING;
