INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bratz: Girlz Really Rock', 'This is your chance to be a superstar! Practice lead guitar, keyboard, or dance and rock out live on stage. Check out the Fashion Designer Suite to create wicked outfits, apply killer make-up and try out some fabulous hairstyles. Take five and catch some air skydiving, or hit the mini-golf course in single or multiplayer modes.' FROM games WHERE igdb_id = 43248 ON CONFLICT (game_id, language_code) DO NOTHING;
