INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeal', 'Zeal is a hidden object game about a fashion magazine. Instead of the usual locations, the game takes place inside the magazine pages, with mini-games related to editing tasks. Each page has several objects and a list at the bottom of the ones that must be removed. A hint button shows the position of one of the objects, but takes about a minute to recharge after being used.' FROM games WHERE igdb_id = 117287 ON CONFLICT (game_id, language_code) DO NOTHING;
