INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M&M''s Adventure', 'Your favorite colorful candy characters are back in their first free-roaming adventure! It''s the end of the day at the M&M''S Candy Factory, but one packet of candy is missing from the delivery truck! It''s your mission to explore each sector of the factory and discover all of the scattered hidden candies in order to make the delivery on time. Run on conveyor belts, jump around packing crates, and sneak your way around the factory -- but be prepared for the Bosses that are waiting to thwart the missions and keep the candies from leaving!' FROM games WHERE igdb_id = 50668 ON CONFLICT (game_id, language_code) DO NOTHING;
