INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R2 Online: Reign of Revolution', 'R2 Online is a MMORPG game with a focus on player-vs-player combat. The game takes place in the fantasy world, torn apart by endless conflicts between mercenary guilds. Choose your side in this confrontation or challenge the whole world by creating a new guild. Hone your skills by slaying monsters and completing quests in between fierce battles.' FROM games WHERE igdb_id = 91269 ON CONFLICT (game_id, language_code) DO NOTHING;
