INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnival Games Mini Golf', 'Set across nine whacky theme park styled environments, the courses players will explore in Carnival Games MiniGolf have something for everyone. Whether it''s a trip back in time to the land of dinosaurs, keeping order in the Wild West or searching for a buried treasure in Pirate''s Cove, the game combines traditional mini-golf fare with action-oriented game play - utilizing the unique capabilities of the Wii Remote. Toss in its multiple game modes, including single and multiplayer campaigns supporting up to four players, extensive character customization and accessories and a golf bag full of mini-games and you have the makings for a ''Hole'' Lotta Fun!' FROM games WHERE igdb_id = 4058 ON CONFLICT (game_id, language_code) DO NOTHING;
