INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CommanDSKeen', 'CommanDS Keen is an adaptation of a PC platform game to the NDS. It is an adaptation of an open source software originally named CloneKeen Caitlin Shaw, which is a platform-based video game series produced by id Software and released by Apogee Software in the early 1990s. This DS port allows you to play episodes 1 Marooned on Mars, 2 The Earth Explodes and 3 Keen Must Die!' FROM games WHERE igdb_id = 298943 ON CONFLICT (game_id, language_code) DO NOTHING;
