INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Dance', 'Street Dance is a DDR style music game and a revised version of Inventor''s game of the same name. The title screen was taken from the Music Video of Venga Boys'' Boom! Boom! Boom! Boom! The 2008 version uses Avilon sound engine (same as in Sharp X68000 games) instead of Sunsoft sound engine used in first version of the game to play PCM music.' FROM games WHERE igdb_id = 247292 ON CONFLICT (game_id, language_code) DO NOTHING;
