INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guinness World Records: The Video Game', 'Guinness World Records: The Videogame will allow players to experience the "thrill" of setting their own world records. This is done through "quick-fire action challenges" aka mini-games, doing anything from tightrope walking across the Grand Canyon to growing the world''s longest, most disgusting fingernails.' FROM games WHERE igdb_id = 4901 ON CONFLICT (game_id, language_code) DO NOTHING;
