INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('active-life-outdoor-challenge', 50685, '2008-05-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9po3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctlix.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Active Life: Outdoor Challenge', 'Jump into the fun with Active Life Outdoor Challenge. The first of many planned titles in the new Active Life series, Outdoor Challenge offers a variety of fast-paced, heart-pumping games that will engage your whole body for a fun and challenging experience. Using the specially-designed eight pad Active Life mat and the Wii Remote, players get totally physical as they compete in over a dozen single and multi-player challenges like river rafting, mine-cart adventure, log jumping, and more. Simple controls and intuitive actions make these games easy to pick up and play right out of the box and in the process will get you and your whole family off the couch and into the game in no time. Game Features: •The Active Life Mat - A fun and easy way to get off the couch and get hearts pumping. •Gameplay Variety - Play over a dozen fast-paced games, alone or with friends,in energetic events that gets players’ whole bodies into the action. •Intuitive Gameplay - Simple controls allow for quick pick up and play. Great for parties. •Play Together - With both competitive and co-operative challenges. •Track Character’s Fitness Progress - See your character’s body change according to how you play. •Tremendous Replay Value - Over a dozen games, each with multiple levels of play: river rafting, mine-cart adventure, log jumping, see-saw, jump rope, water trampoline, plus many more. •Other Features - Includes training mode to work different body parts and synchronization gauge to check the level of team work in cooperative play.' FROM games WHERE igdb_id = 50685 ON CONFLICT (game_id, language_code) DO NOTHING;
