INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout 3: Survival Edition', 'An Amazon.com Exclusive, the Fallout 3: Survival Edition, is the ultimate Fallout 3 package that includes a life-size replica of the Pip-Boy 3000, the wrist-mounted device worn by characters in-game. The Pip-Boy 3000 has been painstakingly recreated and modified for real world display as a digital clock. In addition to the Pip-Boy 3000, the Survival Edition will include all of the items from the Fallout 3 Collector’s Edition including the Fallout 3 game, a customized, metal Vault-Tec lunch box, 5" Vault Boy Bobblehead, The Art of Fallout 3 hardcover book, and The Making of Fallout 3 DVD.' FROM games WHERE igdb_id = 72381 ON CONFLICT (game_id, language_code) DO NOTHING;
