INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Orphan Feast', 'Creaky Tom''s got a devilish plan to raise some quick cash-turn the orphans roaming the streets of London into delicious pies to be sold to unsuspecting citizens. Bag as many Orphans as you can in each level while avoiding the police and other unruly citizens that would keep you from your goal (and steal your precious orphans).' FROM games WHERE igdb_id = 306962 ON CONFLICT (game_id, language_code) DO NOTHING;
