INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kanokon: Esuii', 'Kanokon SE is a romantic comedy adventure game based on the Kanokon TV anime but with an original story and scenario. Originally released for PS2 console, this game was a non-adult from the start. As a visual novel adventure game, the gameplay and visual style is similar to any other title from its genre. Much like in EVE series, the game features a viewpoint change which switches between the two main characters who came to an isolated island during summer vacation.' FROM games WHERE igdb_id = 72556 ON CONFLICT (game_id, language_code) DO NOTHING;
