INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('harvey-birdman-attorney-at-law', 4907, '2008-01-08', 54, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gtt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/syoq2ahmfrnkgbv2nlyo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvey Birdman: Attorney at Law', 'Harvey Birdman, Attorney at Law is an animated interactive adventure game that merges the fun and mayhem of the Adult Swim TV show with a unique style of gameplay. Players will step into the shiny wingtips of Harvey Birdman, a third-rate superhero turned third-rate defense attorney charged with exonerating parodied classic cartoon characters. Over the course of the game, players must guide Harvey through a series of odd and comical cases. Each of the game''s five interactive stories takes the winged crusader of justice to familiar locations from the TV show. In order to prove his client''s innocence, Harvey must peruse the scene of the crime, gather evidence, talk with other cartoon characters, occasionally have drinks with opposing council, and tear holes-no matter how ridiculous-in the testimony provided by the witness for the prosecution. Harvey must bring the whole story together to defend his client in a court where anything can happen...including a confrontation with the prosecution who brandishes a Shrink Ray Gun. With outrageous game play and the comical antics of animated characters, players and fans alike will feel that they are not just taking control of a character, but actually taking part in a brand new episode of Harvey Birdman.' FROM games WHERE igdb_id = 4907 ON CONFLICT (game_id, language_code) DO NOTHING;
