INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Singstar: Wakacyjna Impreza', 'Exclusive release for the Polish market. TRACKLIST: Boys - "Szalona" Brathanki - "Czerwone korale" Edyta Górniak - "Jestem kobiet?" Formacja Nie?ywych Schabuff - "Lato" Just 5 - "Kolorowe sny" K.A.S.A - "Maczo" K.A.S.A - "To w?a?nie lato" Kasia Cerekwicka - "S.O.S" Kasia Kowalska - "Co? optymistycznego" Kombi - "Pokolenie" Kombi - "Sen si? spe?ni" Krzysztof Krawczyk - "Bo jeste? Ty" ?zy - "Agnieszka" ?zy - "Narcyz si? nazywam" Myslovitz - "D?ugo?? d?wi?ku samotno?ci" Norbi - "Kobiety s? gor?ce" Norbi feat. Krzysztof Krawczyk - "Pi?kny dzie?" Reni Jusis - "Zakr?cona" Varius Manx - "Or?a Cie?" Amy Winehouse - "Tears Dry On Their Own" Blondie - "The Tide Is High" Blur - "Girls & Boys" David Bowie - "Let''s Dance" Diana Ross - "I''m Coming Out" Elton John - "I''m Still Standing" Lou Bega - "Mambo No. 5" Peter Andre - "Mysterious Girl" Rihanna - "Umbrella" Sugababes - "Red Dress" Wham! - "Club Tropicana"' FROM games WHERE igdb_id = 15441 ON CONFLICT (game_id, language_code) DO NOTHING;
