INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jenny''s Fish Shop', 'Turn Jenny''s humble fish shop into a booming business and use the proceeds to build a spectacular aquarium in Jenny''s Fish Shop. Give your fish the perfect environment and feed them and they will grow into the perfect pet for some lucky family! Your choice of adorable pet will give you a helping hand, but it''s up to you to make Jenny''s dreams come true. Reel in Jenny''s Fish Shop!' FROM games WHERE igdb_id = 177044 ON CONFLICT (game_id, language_code) DO NOTHING;
