INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ryuu ga Gotoku Kenzan!', 'Ryu ga Gotoku Kenzan! is an action-adventure video game published by Sega for the PlayStation 3. It is a jidaigeki-themed spin-off game in the Like a Dragon series. It was released exclusively in Japan on March 6, 2008. Kenzan! is a dramatic telling of the life of the historical figure Miyamoto Musashi, who retired and adopted a new identity, but is later drawn into a new conflict where he must hunt down an imposter using his namesake.' FROM games WHERE igdb_id = 7442 ON CONFLICT (game_id, language_code) DO NOTHING;
