INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sands of Destruction', 'Sands of Destruction is a 2008 role-playing video game developed by Imageepoch and published by Sega for the Nintendo DS. It was released in Japan in 2008, and in North America in 2010. Set in a desert world where humans are ruled over and persecuted by the anthropomorphic Ferals, the story revolves around protagonist Kyrie after learning he holds the power to destroy the world. Gameplay features exploration of the game world from a top-down perspective, and a turn-based combat system incorporating real-time mechanics.' FROM games WHERE igdb_id = 24331 ON CONFLICT (game_id, language_code) DO NOTHING;
