INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barnyard-blast-swine-of-the-night', 47917, '2008-02-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7hog.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barnyard Blast: Swine of the Night', 'One Halloween evening, young piglet Cliffy Belmart and his rebellious friends decide to test their bravery by tee-peeing Barnyard Town''s Ancient Castle ruled by Darkness. But as soon as the fun begins, horrendouse evil trees sweep them all into the castle. Instantly aware of his son''s peril, Robert Belmart equips himself with a slew of weapons and a plan to get Cliffy back. But first, Robert must tackle six different spooky worlds - each with their own tough monsters and dangerous bosses. Is Robert a bad enough dude to rescue his son? In Barnyard Blast, you control Robert Belmart, the Swine of the Night. Through 6 levels you kill zombies, exterminate monsters, slash ghouls, and more! Vintage shooting and platform gameplay with simple, intuitive controls Hilarious characters and scenes combined with intense, state-of-the-art fighting Six long and unique levels: A Night Walk in the Graveyard, The Ancient Castle Ruled by Darkness, The Volcano BBQ, The Old Creepy Wooden Jail, The Forest in the Way, and The Castle of Intolerable Pain Challenging enemies and bosses including Pumpkin Zombies, Assassin Rats, Evil Trees, and Sinister Monkeys A collection of weapons (whip, shotgun, gun, dynamite), items and upgrades' FROM games WHERE igdb_id = 47917 ON CONFLICT (game_id, language_code) DO NOTHING;
