INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golden Axe: Beast Rider', 'Beast Rider is the first Golden Axe game in 3D as opposed to side scrolling hack and slash. While this is a major shift in game style from the previous games, Beast Rider maintains many of the elements from the originals such as magic and riding beasts, as well as sending the player on a quest to defeat Death Adder.' FROM games WHERE igdb_id = 7001 ON CONFLICT (game_id, language_code) DO NOTHING;
