INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ai space', 'A now defunct Japanese 3D MMO social game. Formed by a partnership between several companies, players had the chance to interact with characters and visit locations from the worlds of "Clannad", "Shuffle!", and "Da Capo II". Players could furnish their own dwellings, and meet up with one another on Akihabara Island to socialize. There were also online events such as water gun battles for players to participate in.' FROM games WHERE igdb_id = 153680 ON CONFLICT (game_id, language_code) DO NOTHING;
